/* 偿二代二期 监管规则 题库（自动生成） */
window.QUESTION_BANK = {"questions":[{"id":"01-S01","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"根据规则第1号，实际资本等于（　）。","options":["认可资产减去认可负债后的余额","核心资本加附属资本","净资产减去非认可资产","认可资产减去保险合同负债"],"answer":"A","explanation":"第四条规定，实际资本等于认可资产减去认可负债后的余额。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S02","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"实际资本的评估应当以（　）为基础。","options":["合并财务报表","母公司财务报表","监管报表","预算报表"],"answer":"B","explanation":"第五条规定，实际资本的评估应当以母公司财务报表而不以合并财务报表为基础。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S03","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司以物权方式或通过项目公司方式持有的投资性房地产，应当以（　）作为其认可价值。","options":["公允价值","评估价值","成本模式计量金额","账面价值的80%"],"answer":"C","explanation":"第十三条规定，以物权方式或通过项目公司方式持有的投资性房地产，应当按成本模式计量金额作为其认可价值。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S04","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司对子公司的长期股权投资，应当按照（　）确定其账面价值。","options":["成本法","权益法","公允价值法","市价法"],"answer":"B","explanation":"第十四条规定，保险公司对子公司的长期股权投资，应当按照权益法确定其账面价值。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S05","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"下列各项中，属于非认可资产的是（　）。","options":["土地使用权","由经营性亏损引起的递延所得税资产","应急资本","存出分保保证金"],"answer":"B","explanation":"第十条规定由经营性亏损引起的递延所得税资产为非认可资产；无形资产以土地使用权除外，应急资本属于认可资产，存出分保保证金属于再保险资产。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S06","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"合营或联营企业为上市公司的，市价持续（　）以上低于账面价值或市价低于账面价值的比例超过50%的，应当计提减值。","options":["6个月","1年","2年","3年"],"answer":"B","explanation":"第十五条第（一）项规定，市价持续一年以上低于账面价值或市价低于账面价值的比例超过50%的，应根据账面价值和市价的差额计提减值。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S07","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"现金价值保证的认可价值计算公式为（　）。","options":["Max（CV－PL－MC，0）","Max（PL－CV－MC，0）","CV－PL－MC","Min（CV－PL，MC）"],"answer":"A","explanation":"第二十三条规定，现金价值保证的认可价值＝Max（CV－PL－MC，0），其中CV为全部寿险业务现金价值，PL为寿险合同负债，MC为最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S08","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司发行的没有赎回条款的次级定期债务，剩余期限在1年以上（含）、2年以内的，以账面价值的（　）作为其认可价值。","options":["0","20%","50%","80%"],"answer":"C","explanation":"第二十五条规定，无赎回条款次级债务剩余期限1年以上（含）2年以内的，以账面价值的50%作为认可价值。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S09","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"赎回日之前和赎回日之后的票面利率差额超过（　）个基点，或者有证据表明保险公司会提前赎回的，剩余期限按赎回日计算。","options":["50","100","150","200"],"answer":"B","explanation":"第二十六条规定，票面利率差额超过100个基点或有提前赎回证据的，剩余期限按赎回日计算。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S10","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"根据资本分级规定，核心资本是指（　）的资本。","options":["在持续经营状态下和破产清算状态下均可以吸收损失","仅在持续经营状态下可以吸收损失","仅在破产清算状态下可以吸收损失","只能用于补充偿付能力充足率"],"answer":"A","explanation":"第二十九条规定，核心资本是指在持续经营状态下和破产清算状态下均可以吸收损失的资本；附属资本是仅在破产清算状态下可以吸收损失的资本。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S11","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"核心二级资本工具的永续性要求是（　）。","options":["应当没有到期日","应当没有到期日或者期限不低于10年，发行5年后方可赎回","期限不低于5年","期限可以低于5年"],"answer":"B","explanation":"第三十一条规定，核心二级资本应当没有到期日或者期限不低于10年，发行5年后方可赎回并且不得含有利率跳升机制及其他赎回激励。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S12","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"附属一级资本工具的期限要求是（　）。","options":["没有到期日","期限不低于10年","期限不低于5年","期限可以低于5年"],"answer":"C","explanation":"第三十二条规定，附属一级资本在永续性方面期限不低于5年。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S13","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保单剩余期限在30年（含）以上的，保单未来盈余按核心一级资本对应的资本报酬率折现到评估时点的现值作为核心一级资本工具，剩余部分作为（　）资本工具。","options":["核心二级","附属一级","附属二级","资本性负债"],"answer":"B","explanation":"第三十六条第（一）项规定，剩余期限30年（含）以上的，剩余部分作为附属一级资本工具。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S14","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保单剩余期限在5年以内的，保单未来盈余应当（　）。","options":["全部作为核心一级资本工具","全部作为核心二级资本工具","全部作为附属一级资本工具","全部作为附属二级资本工具"],"answer":"D","explanation":"第三十六条第（四）项规定，保单剩余期限在5年以内的，保单未来盈余全部作为附属二级资本工具。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S15","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司根据第三十五条计算的保单未来盈余小于零的，应当（　）。","options":["直接调减核心一级资本","直接调减附属二级资本","确认为非认可负债","不计入实际资本"],"answer":"A","explanation":"第三十七条规定，保单未来盈余小于零的，应当直接调减核心一级资本。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S16","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司开展长期寿险再保险，再保险合同（　）内可终止的，不得确认该再保险合同对实际资本的影响金额。","options":["1年","2年","3年","5年"],"answer":"C","explanation":"第三十八条规定，再保险合同3年内可终止的，不得确认该再保险合同对实际资本的影响金额。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S17","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"长期寿险再保险中资产未真实转移、再保险合同期限10年（含）以上且5年后方可终止的，因再保险合同增加的资本计入（　）。","options":["核心一级资本","核心二级资本","附属一级资本","附属二级资本"],"answer":"B","explanation":"第三十八条规定，资产未真实转移时，再保险合同期限10年（含）以上、5年后方可终止的，增加的资本计入核心二级资本。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S18","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"根据各级资本限额标准，附属资本不得超过核心资本的（　）。","options":["25%","35%","50%","100%"],"answer":"D","explanation":"第四十一条规定，附属资本不得超过核心资本的100%。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S19","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"按第三十五条至第三十七条计入核心资本的保单未来盈余，不得超过核心资本的（　）。","options":["25%","30%","35%","50%"],"answer":"C","explanation":"第四十一条第（二）项规定，计入核心资本的保单未来盈余不得超过核心资本的35%。","difficulty":2,"type":"concept","source":"core"},{"id":"01-S20","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"保险公司发行的次级可转换债券剩余期限在2年以上（含）的，其认可价值为（　）。","options":["账面价值的20%","账面价值的50%","账面价值的80%","0"],"answer":"D","explanation":"第二十五条规定，次级可转换债券及无赎回条款次级债务剩余期限在2年以上（含）的，认可价值为0。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M01","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"关于实际资本评估应遵循的原则，下列说法正确的有（　）。","options":["在银保监会认可的企业会计准则基础上，根据偿付能力监管目的对资产、负债的评估标准进行调整","应适时、恰当地反映保险公司资产、负债在其商业模式和市场环境中的价值及其变化","应当以母公司财务报表而不以合并财务报表为基础","资产与负债的评估原则应当一致"],"answer":["A","B","C","D"],"explanation":"第五条规定了实际资本评估的五项原则，选项均属之，另包括不同类型保险公司经营相同业务适用相同评估原则。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M02","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"保险公司的下列资产中，属于非认可资产的有（　）。","options":["无形资产（土地使用权除外）","由经营性亏损引起的递延所得税资产","待摊费用和长期待摊费用","文物、艺术作品和动植物标本"],"answer":["A","B","C","D"],"explanation":"第十条列举的非认可资产包括上述四项，另有处置受限资产和银保监会规定的其他非认可资产。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M03","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"有迹象表明保险公司到期不能处置或者对其处置受到限制的资产包括（　）。","options":["被依法冻结的资产","为他人担保而被质押或抵押的资产（为自身担保的除外）","由于交易对手或被投资企业出现财务危机、被接管、被宣告破产等导致处置受限的资产","由于当地管制、政治动乱、战争、金融危机等原因导致处置受到限制的境外资产"],"answer":["A","B","C","D"],"explanation":"第十一条列举了处置受限资产的情形，选项均属之。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M04","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"除下列（　）项目外，保险公司各项认可资产以账面价值作为认可价值。","options":["以物权方式或通过项目公司方式持有的投资性房地产","对子公司的长期股权投资","寿险业务的应收分保准备金","非寿险业务的应收保费"],"answer":["A","B","C"],"explanation":"第十二条规定，投资性房地产、对子公司长期股权投资、寿险业务应收分保准备金及银保监会规定的其他项目不以账面价值作为认可价值；应收保费以账面价值认可。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M05","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"保险公司资本应当符合的特性包括（　）。","options":["存在性","永续性","次级性","非强制性和外生性"],"answer":["A","B","C","D"],"explanation":"第二十八条规定资本应符合存在性、永续性、次级性、非强制性、外生性五项特性。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M06","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"关于各级资本限额标准，下列说法正确的有（　）。","options":["附属资本不得超过核心资本的100%","核心二级资本不得超过核心资本的30%","附属二级资本不得超过核心资本的25%","计入核心资本的保单未来盈余不得超过核心资本的35%"],"answer":["A","B","C","D"],"explanation":"第四十一条规定了上述四项限额标准；超过限额的应确认为资本性负债。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M07","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"保险公司的下列负债中，属于非认可负债的有（　）。","options":["根据财政部有关规定对农业保险业务提取的大灾风险保费准备金","保险公司发行的符合核心资本或附属资本标准、用于补充实际资本且符合计入资本相关条件的次级定期债务","资本补充债券","应付赔付款"],"answer":["A","B","C"],"explanation":"第二十条规定，大灾风险保费准备金以及符合资本标准用于补充实际资本的长期债务（次级定期债务、资本补充债券、次级可转换债券等）为非认可负债；应付赔付款属于认可负债。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M08","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"关于长期寿险再保险对实际资本的影响，下列说法正确的有（　）。","options":["再保险合同3年内可终止的，不得确认该再保险合同对实际资本的影响金额","3年后方可终止且相关风险和资产真实转移的，再保险合同相应增加的实际资本计入核心一级资本","资产未真实转移、合同期限5年（含）以上10年以内且5年后方可终止的，增加的资本计入附属一级资本","分出保费递延支付的，递延支付期限不应超过6个月"],"answer":["A","B","C","D"],"explanation":"第三十八条对长期寿险再保险的资本确认和分级作出规定，选项均符合该条要求。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M09","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"保险公司发行的具有赎回条款的次级定期债务和资本补充债券，其认可价值标准包括（　）。","options":["剩余期限在4年以上（含）的，认可价值为0","剩余期限在2年以上（含）、3年以内的，以账面价值的40%作为认可价值","剩余期限在1年以上（含）、2年以内的，以账面价值的60%作为认可价值","剩余期限在1年以内的，以账面价值的80%作为认可价值"],"answer":["A","B","C","D"],"explanation":"第二十六条规定了有赎回条款次级债务的五档认可标准：4年以上为0、3－4年20%、2－3年40%、1－2年60%、1年以内80%。","difficulty":2,"type":"concept","source":"core"},{"id":"01-M10","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"关于保单未来盈余的资本分级，下列说法正确的有（　）。","options":["保单剩余期限10年（含）以上、30年以内的，折现现值作为核心二级资本工具，剩余部分作为附属一级资本工具","保单剩余期限5年（含）以上、10年以内的，折现现值作为附属一级资本工具，剩余部分作为附属二级资本工具","分组保单未来盈余小于零的，折现前按零取值，相应冲减剩余期限30年（含）以上组的未来盈余","30年（含）以上组的未来盈余不足冲减的，冲减核心一级资本"],"answer":["A","B","C","D"],"explanation":"第三十六条、第三十七条对保单未来盈余按剩余期限分级及负值冲减规则作出规定，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"01-X-S01","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"根据规则第1号，下列关于认可资产的定义，正确的是：","options":["处置不受限制，并可用于履行对保单持有人赔付义务的资产","能够为公司带来未来经济利益的全部资产","以公允价值计量且其变动计入当期损益的资产","账面价值为正且流动性较高的资产"],"answer":"A","explanation":"规则第1号规定，认可资产是指处置不受限制，并可用于履行对保单持有人赔付义务的资产；不符合该条件的资产为非认可资产。","difficulty":1,"type":"concept","source":"extra"},{"id":"01-X-S02","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"某保险公司持有一笔无赎回条款的次级定期债务，账面价值为20亿元，剩余期限为1.5年。该债务的认可价值为：","options":["16亿元","10亿元","0元","20亿元"],"answer":"B","explanation":"无赎回条款的次级定期债务，剩余期限1年以上（含）2年以内的，认可价值为账面价值的50%，即20×50%＝10亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"01-X-S03","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"某寿险公司全部寿险业务现金价值CV为500亿元，寿险业务保险合同负债PL为460亿元，最低资本MC为30亿元。该公司的现金价值保证为：","options":["40亿元","30亿元","10亿元","0元"],"answer":"C","explanation":"现金价值保证的认可价值＝Max（CV－PL－MC，0）＝Max（500－460－30，0）＝10亿元。","difficulty":3,"type":"calc","source":"extra"},{"id":"01-X-S04","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"根据规则第1号，下列资产中属于非认可资产的是：","options":["无形资产中的土地使用权","由经营性亏损引起的递延所得税资产","经营性亏损以外的其他递延所得税资产","对子公司的长期股权投资"],"answer":"B","explanation":"由经营性亏损引起的递延所得税资产属于非认可资产，其他递延所得税资产属于认可资产；无形资产中的土地使用权不属于非认可资产。","difficulty":1,"type":"concept","source":"extra"},{"id":"01-X-S05","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"某寿险公司保单未来盈余对应剩余期限为12年。根据保单未来盈余的分级标准，该部分盈余应计入：","options":["核心一级资本","核心二级资本和附属一级资本","附属一级资本和附属二级资本","全部计入附属二级资本"],"answer":"B","explanation":"保单未来盈余剩余期限10年（含）至30年的，计入核心二级资本加附属一级资本；12年处于该区间。","difficulty":2,"type":"scenario","source":"extra"},{"id":"01-X-S06","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"下列关于各级资本工具期限要求的表述，正确的是：","options":["核心二级资本工具期限不低于10年，发行5年后方可赎回且不得含利率跳升机制","附属一级资本工具的期限不得低于10年","附属二级资本工具的期限不得低于5年","核心二级资本工具可以含利率跳升机制"],"answer":"A","explanation":"核心二级资本工具期限不低于10年，发行5年后方可赎回且不得含利率跳升机制；附属一级资本期限不低于5年，附属二级资本期限可以低于5年。","difficulty":2,"type":"concept","source":"extra"},{"id":"01-X-S07","rule_no":1,"rule_title":"实际资本","qtype":"single","q":"某寿险公司签订一份长期寿险再保险合同，合同约定生效后2年内可以终止。根据规则第1号，该公司对该再保险合同的处理正确的是：","options":["可按分出保费的50%确认对实际资本的影响","经公司董事会批准后可全额确认影响金额","不得确认该再保险合同对实际资本的影响金额","可正常确认，同时向银保监会备案"],"answer":"C","explanation":"保险公司开展长期寿险再保险，再保险合同3年内可终止的，不得确认该再保险合同对实际资本的影响金额。","difficulty":2,"type":"scenario","source":"extra"},{"id":"01-X-M01","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"根据规则第1号的资本分级框架，下列属于核心资本的有：","options":["核心一级资本","核心二级资本","附属一级资本","附属二级资本"],"answer":["A","B"],"explanation":"核心资本是在持续经营状态下和破产清算状态下均可以吸收损失的资本，分为核心一级资本和核心二级资本；附属一级和附属二级资本属于附属资本。","difficulty":1,"type":"concept","source":"extra"},{"id":"01-X-M02","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"下列关于各级资本限额的表述，正确的有：","options":["附属资本不得超过核心资本的100%","计入核心资本的保单未来盈余不得超过核心资本的35%","核心二级资本不得超过核心资本的50%","附属二级资本不得超过核心资本的25%"],"answer":["A","B","D"],"explanation":"核心二级资本不得超过核心资本的30%而非50%，C错误；A、B、D均符合规则第1号的资本限额规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"01-X-M03","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"某保险公司发行一笔带赎回条款的资本补充债券，赎回日前后票面利率差额为120个基点，且有证据表明公司将提前赎回；至赎回日的剩余期限为2.5年，账面价值为20亿元。下列表述正确的有：","options":["认可价值为12亿元","剩余期限应按赎回日计算","认可价值为8亿元","若无证据表明会提前赎回，剩余期限按到期日计算"],"answer":["B","C","D"],"explanation":"赎回日前后票面利率差额超过100个基点且有证据表明会提前赎回的，剩余期限按赎回日计算；有赎回条款的工具剩余期限2年以上（含）3年以内认可价值为账面价值的40%，即20×40%＝8亿元。","difficulty":3,"type":"calc","source":"extra"},{"id":"01-X-M04","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"某寿险公司全部寿险业务现金价值CV为300亿元，寿险业务保险合同负债PL为280亿元，最低资本MC为15亿元。下列表述正确的有：","options":["该公司现金价值保证的认可价值为5亿元","公式中的MC指公司的市场风险最低资本","若保险合同负债PL上升至310亿元，现金价值保证为0","现金价值保证以Max函数确保认可价值不为负"],"answer":["A","C","D"],"explanation":"现金价值保证＝Max（300－280－15，0）＝5亿元；公式中的MC为最低资本而非仅市场风险最低资本；若PL＝310，则300－310－15＜0，认可价值为0。","difficulty":3,"type":"cross","source":"extra"},{"id":"01-X-M05","rule_no":1,"rule_title":"实际资本","qtype":"multi","q":"某寿险公司开展再保险业务。下列关于再保险相关确认与转移要求的表述，正确的有：","options":["再保险合同3年内可终止的，不得确认该长期寿险再保险合同对实际资本的影响金额","分出保费递延支付的，递延支付期限不应超过6个月","资产真实转移要求分出保费现金流真实由分出人转入分入人，且未出现分入人通过佣金和手续费大比例返还等转回现金流的情况","风险真实转移仅指保险风险的部分或全部转移"],"answer":["A","B","C"],"explanation":"风险真实转移是指保险风险、市场风险、信用风险等部分或全部从分出人真实转移给分入人，不仅限于保险风险，D错误。","difficulty":2,"type":"scenario","source":"extra"},{"id":"02-S01","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险公司偿付能力风险由（　）组成。","options":["保险风险和市场风险","固有风险和控制风险","可资本化风险和难以资本化风险","定量风险和定性风险"],"answer":"B","explanation":"第三条规定，保险公司偿付能力风险由固有风险和控制风险组成。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S02","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"下列风险中，属于难以资本化为最低资本的风险的是（　）。","options":["保险风险","市场风险","信用风险","声誉风险"],"answer":"D","explanation":"第三条规定，难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险；保险风险、市场风险、信用风险属于可资本化风险。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S03","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险公司最低资本由三部分组成，下列不属于其中的是（　）。","options":["可资本化风险最低资本","控制风险最低资本","附加资本","操作风险最低资本"],"answer":"D","explanation":"第五条规定最低资本由可资本化风险最低资本、控制风险最低资本和附加资本组成，操作风险属于难以资本化风险，不单独计量最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S04","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"附加资本不包括（　）。","options":["逆周期附加资本","系统重要性保险机构的附加资本","流动性附加资本","其他附加资本"],"answer":"C","explanation":"第五条规定附加资本包括逆周期附加资本、系统重要性保险机构的附加资本以及其他附加资本，无流动性附加资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S05","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"最低资本的计量应采用（　），以反映各类风险之间的分散效应。","options":["简单加总法","相关系数矩阵法","压力测试法","情景模拟法"],"answer":"B","explanation":"第七条规定，最低资本的计量应采用相关系数矩阵法，反映各类风险之间的分散效应。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S06","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险风险、市场风险和信用风险等可资本化风险的最低资本计量采用（　）。","options":["在险价值（VaR）法","监管评价法","综合因子法","情景测试法"],"answer":"A","explanation":"第九条规定，可资本化风险的最低资本计量采用在险价值法，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S07","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"控制风险的最低资本计量采用（　）。","options":["在险价值法","监管评价法","相关系数矩阵法","风险敏感度法"],"answer":"B","explanation":"第十条规定，控制风险的最低资本计量采用监管评价法。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S08","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险风险、市场风险和信用风险的风险暴露（　）非认可资产和非认可负债。","options":["包括","不包括","仅包括部分","由保险公司自行选择是否包括"],"answer":"B","explanation":"第十一条规定，三类可资本化风险的风险暴露不包括非认可资产和非认可负债，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S09","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"独立账户资产和独立账户负债不计提的最低资本是（　）。","options":["由保单持有人自行承担的市场风险、信用风险对应的最低资本","由保险公司承担的保险风险最低资本","控制风险最低资本","附加资本"],"answer":"A","explanation":"第十二条规定，独立账户资产和负债不计提根据保险合同由保单持有人自行承担的市场风险、信用风险所对应的最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S10","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险公司的长期寿险再保险合同，合同生效日后（　）内可终止的，不得计量因再保险合同降低的最低资本。","options":["1年","2年","3年","5年"],"answer":"C","explanation":"第十四条规定，长期寿险再保险合同生效日后3年内可终止的，不得计量因再保险合同降低的最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S11","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"财产保险公司最低资本向量由（　）组成。","options":["寿险保险、非寿险保险、市场、信用","非寿险保险、市场、信用","寿险再保险、非寿险再保险、市场、信用","保险、市场、信用、控制"],"answer":"B","explanation":"第十六条规定，财产保险公司MC向量由非寿险业务保险风险、市场风险、信用风险最低资本组成。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S12","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"对于财产保险公司，非寿险保险风险最低资本与市场风险最低资本的相关系数为（　）。","options":["0.1","0.15","0.27","0.35"],"answer":"A","explanation":"第十六条相关系数矩阵显示，财产险公司非寿险保险与市场风险相关系数为0.1，与信用风险为0.15，市场与信用为0.27。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S13","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"人身保险公司最低资本向量中，寿险业务保险风险与市场风险的相关系数为（　）。","options":["0.10","0.20","0.30","0.35"],"answer":"C","explanation":"第十七条相关系数矩阵显示，人身险公司寿险保险与市场风险相关系数为0.30，寿险与非寿险为0.20，寿险与信用为0.15。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S14","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"人身保险公司最低资本向量中，市场风险与信用风险的相关系数为（　）。","options":["0.27","0.30","0.35","0.15"],"answer":"C","explanation":"第十七条相关系数矩阵显示，人身险公司市场与信用风险相关系数为0.35。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S15","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"再保险公司最低资本向量中，寿险再保险业务与非寿险再保险业务保险风险的相关系数为（　）。","options":["0.05","0.10","0.15","0.27"],"answer":"B","explanation":"第十八条相关系数矩阵显示，再保险公司寿险再与非寿险再保险风险相关系数为0.10。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S16","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"分红保险和万能保险账户合并计算市场与信用风险最低资本时，市场与信用风险的相关系数ρ为（　）。","options":["0.25","0.27","0.30","0.35"],"answer":"D","explanation":"第十九条规定，分红万能账户合并计算的市场与信用风险最低资本中ρ＝0.35。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S17","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"保险公司应当根据（　）计量控制风险最低资本。","options":["偿付能力监管规则第12号","偿付能力监管规则第3号","偿付能力监管规则第4号","偿付能力监管规则第8号"],"answer":"A","explanation":"第二十条规定，保险公司应根据《保险公司偿付能力监管规则第12号：偿付能力风险管理要求与评估》计量控制风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S18","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"损失吸收效应调整上限LA上限的计算公式为（　）。","options":["PV基础＋PV下限","PV基础－PV下限","PV基础×β","Max（PV基础－PV下限，0）×K"],"answer":"B","explanation":"第十九条规定，LA上限＝PV基础－PV下限，即基础情景现金流现值与按红利水平和结算利率假设下限重新预测的现金流现值之差。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S19","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"境外国家（地区）的偿付能力监管制度获得中国偿付能力监管等效资格的，对于该国家（地区）保险公司在中国境内设立的保险分公司，银保监会可认可其（　）。","options":["母公司的偿付能力充足率","分公司的偿付能力充足率","母公司的风险综合评级","分公司的核心偿付能力充足率"],"answer":"A","explanation":"第二十二条规定，银保监会可认可其母公司的偿付能力充足率，具体办法另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"02-S20","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"本规则于2015年2月13日第一次发布，于（　）修订发布。","options":["2021年10月30日","2021年12月30日","2022年1月1日","2020年12月30日"],"answer":"B","explanation":"第二十五条规定，本规则于2015年2月13日第一次发布，于2021年12月30日修订发布。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M01","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"下列风险中，属于可资本化为最低资本的风险的有（　）。","options":["保险风险","市场风险","信用风险","操作风险"],"answer":["A","B","C"],"explanation":"第三条规定，可资本化风险包括保险风险、市场风险和信用风险；操作风险属于难以资本化风险。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M02","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"下列风险中，属于难以资本化为最低资本的风险的有（　）。","options":["操作风险","战略风险","声誉风险","流动性风险"],"answer":["A","B","C","D"],"explanation":"第三条规定，难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M03","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"关于最低资本的计量原则，下列说法正确的有（　）。","options":["计量应以风险为基础","应涵盖保险公司面临的所有可资本化的固有风险、控制风险和系统风险","应采用相关系数矩阵法反映各类风险之间的分散效应","采用行业统一的方法、模型和参数，银保监会另有规定的除外"],"answer":["A","B","C","D"],"explanation":"第六条至第八条规定了最低资本计量的风险基础、风险覆盖、相关系数矩阵法和行业统一标准等原则。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M04","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"人身保险公司最低资本向量包括（　）。","options":["寿险业务保险风险最低资本","非寿险业务保险风险最低资本","市场风险最低资本","信用风险最低资本"],"answer":["A","B","C","D"],"explanation":"第十七条规定，人身保险公司MC向量由寿险保险、非寿险保险、市场、信用四部分组成。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M05","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"关于分红保险和万能保险损失吸收效应调整，下列说法正确的有（　）。","options":["分红保险和万能保险业务应当考虑损失吸收效应调整","账户合并计算的市场与信用风险最低资本中市场与信用相关系数为0.35","损失吸收效应调整比率β中的K由银保监会发布并根据市场周期进行调整","PV下限是按分红保险保单红利水平和万能保险结算利率假设下限重新预测、采用基础情景折现率评估的现金流现值"],"answer":["A","B","C","D"],"explanation":"第十九条对损失吸收效应调整的计算作出规定，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M06","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"对于财产保险公司最低资本的相关系数矩阵，下列数值正确的有（　）。","options":["非寿险保险与市场为0.1","非寿险保险与信用为0.15","市场与信用为0.27","非寿险保险与信用为0.35"],"answer":["A","B","C"],"explanation":"第十六条矩阵中，非寿险保险与市场0.1、非寿险保险与信用0.15、市场与信用0.27；0.35为人身险公司市场与信用的相关系数。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M07","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"关于长期寿险再保险合同最低资本的计量，下列说法正确的有（　）。","options":["合同生效日后3年内可终止的，不得计量因再保险合同降低的最低资本","分出人减少的最低资本与分入人增加的最低资本原则上应保持一致","分出人和分入人均可自行决定是否计量再保险影响","再保险影响只对分出人计量"],"answer":["A","B"],"explanation":"第十四条规定，3年内可终止的不得计量降低的最低资本；分出人与分入人的最低资本变动原则上应保持一致。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M08","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"再保险公司最低资本向量包括（　）。","options":["寿险再保险业务保险风险最低资本","非寿险再保险业务保险风险最低资本","市场风险最低资本","信用风险最低资本"],"answer":["A","B","C","D"],"explanation":"第十八条规定，再保险公司MC向量由寿险再保险、非寿险再保险、市场、信用四部分组成。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M09","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"关于本规则的适用与解释，下列说法正确的有（　）。","options":["相互保险组织适用本规则","本规则由银保监会负责解释和修订","本规则施行日期另行规定","外国保险公司分公司不适用本规则"],"answer":["A","B","C"],"explanation":"第二条规定本规则所称保险公司包括外国保险公司分公司；第二十三条至第二十五条规定相互保险组织适用、银保监会负责解释修订、施行日期另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"02-M10","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"下列关于最低资本组成部分的表述，正确的有（　）。","options":["可资本化风险最低资本即保险风险、市场风险、信用风险对应的最低资本","控制风险最低资本即控制风险对应的最低资本","附加资本包括逆周期附加资本","附加资本包括系统重要性保险机构的附加资本"],"answer":["A","B","C","D"],"explanation":"第五条规定最低资本由可资本化风险最低资本、控制风险最低资本和附加资本组成，附加资本包括逆周期附加资本、系统重要性保险机构的附加资本以及其他附加资本。","difficulty":2,"type":"concept","source":"core"},{"id":"02-X-S01","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"根据规则第2号，可资本化风险包括：","options":["保险风险、市场风险和信用风险","操作风险、战略风险和声誉风险","流动性风险、声誉风险和保险风险","控制风险、系统风险和保险风险"],"answer":"A","explanation":"可资本化风险是指可以资本化为最低资本的风险，包括保险风险、市场风险和信用风险；操作、战略、声誉和流动性风险属于难以资本化风险。","difficulty":1,"type":"concept","source":"extra"},{"id":"02-X-S02","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"根据规则第2号，控制风险的最低资本计量采用的方法是：","options":["在险价值法（VaR）","监管评价法","相关系数矩阵法","情景模拟法"],"answer":"B","explanation":"可资本化风险的最低资本计量采用在险价值（VaR）法，控制风险的最低资本计量采用监管评价法。","difficulty":1,"type":"concept","source":"extra"},{"id":"02-X-S03","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"根据规则第2号，人身保险公司的最低资本（MC）向量由下列哪组风险组成：","options":["非寿险保险风险、市场风险、信用风险","寿险保险风险、非寿险保险风险、市场风险、信用风险","寿险再保险、非寿险再保险、市场风险、信用风险","寿险保险风险、市场风险、信用风险"],"answer":"B","explanation":"人身保险公司MC向量由寿险保险、非寿险保险、市场、信用四类风险组成；A为财产保险公司向量，C为再保险公司向量。","difficulty":2,"type":"concept","source":"extra"},{"id":"02-X-S04","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"某财产保险公司非寿险保险风险、市场风险、信用风险的最低资本均为100亿元，不考虑损失吸收效应调整。经相关系数矩阵聚合后的可资本化风险最低资本约为：","options":["300亿元","201亿元","252亿元","404亿元"],"answer":"B","explanation":"聚合值＝√（100²＋100²＋100²＋2×(0.1＋0.15＋0.27)×100×100）＝√40400≈201亿元，小于三者简单相加的300亿元，体现了风险分散效应。","difficulty":2,"type":"calc","source":"extra"},{"id":"02-X-S05","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"某人身保险公司各类可资本化风险经相关系数矩阵聚合后的结果为150亿元，分红和万能保险业务对应的损失吸收效应调整LA为20亿元。该公司的可资本化风险最低资本为：","options":["150亿元","170亿元","130亿元","110亿元"],"answer":"C","explanation":"可资本化风险最低资本＝√（MC向量×相关系数矩阵×MC向量转置）－LA＝150－20＝130亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"02-X-S06","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"某人身保险公司与某财产保险公司分别计量最低资本，两公司在聚合市场风险与信用风险时采用的相关系数分别为：","options":["人身险公司0.27，财产险公司0.35","人身险公司0.35，财产险公司0.27","均为0.35","均为0.27"],"answer":"B","explanation":"市场与信用风险相关系数在人身险公司为0.35，在财产险公司和再保险公司均为0.27，这是常见的易混淆点。","difficulty":3,"type":"scenario","source":"extra"},{"id":"02-X-S07","rule_no":2,"rule_title":"最低资本","qtype":"single","q":"某财产险公司作为分出人签订一份长期寿险再保险合同，合同生效日后2年内可以终止。根据规则第2号，该公司对该合同的处理正确的是：","options":["可以计量因该再保险合同降低的最低资本","不得计量因该再保险合同降低的最低资本","分入人不得增加相应最低资本","该合同对双方最低资本均无任何影响"],"answer":"B","explanation":"长期寿险再保险合同生效日后3年内可终止的，不得计量因再保险合同降低的最低资本；同时按规则第1号也不得确认其对实际资本的影响。","difficulty":3,"type":"cross","source":"extra"},{"id":"02-X-M01","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"根据规则第2号，下列属于难以资本化风险的有：","options":["操作风险","战略风险","声誉风险","保险风险"],"answer":["A","B","C"],"explanation":"难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险四类；保险风险属于可资本化风险。","difficulty":1,"type":"concept","source":"extra"},{"id":"02-X-M02","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"根据规则第2号，保险公司的最低资本由下列哪些部分组成：","options":["可资本化风险最低资本","控制风险最低资本","流动性风险最低资本","逆周期附加资本"],"answer":["A","B","D"],"explanation":"最低资本由可资本化风险最低资本、控制风险最低资本和附加资本（含逆周期附加资本、系统重要性保险机构的附加资本以及其他附加资本）组成；流动性风险属于难以资本化风险。","difficulty":2,"type":"concept","source":"extra"},{"id":"02-X-M03","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"某人身保险公司计量最低资本时，下列关于各类风险间相关系数的表述，正确的有：","options":["寿险保险风险与非寿险保险风险的相关系数为0.20","寿险保险风险与市场风险的相关系数为0.30","市场风险与信用风险的相关系数为0.35","非寿险保险风险与市场风险的相关系数为0.30"],"answer":["A","B","C"],"explanation":"人身保险公司中非寿险保险与市场的相关系数为0.1而非0.30，D错误；A、B、C均符合规则第2号的规定。","difficulty":3,"type":"scenario","source":"extra"},{"id":"02-X-M04","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"下列关于损失吸收效应调整（LA）的表述，正确的有：","options":["损失吸收效应调整适用于所有寿险业务","损失吸收效应调整仅适用于分红保险和万能保险业务","LA的上限＝PV基础－PV下限，即基础情景现金流现值与红利、结算利率假设下限情景现金流现值之差","分红万能账户合并计算的市场与信用风险最低资本中，市场与信用相关系数ρ＝0.35"],"answer":["B","C","D"],"explanation":"LA仅适用于分红保险和万能保险业务，A错误；B、C、D均为规则第2号的原文规定。","difficulty":2,"type":"calc","source":"extra"},{"id":"02-X-M05","rule_no":2,"rule_title":"最低资本","qtype":"multi","q":"下列关于最低资本计量要求的表述，正确的有：","options":["分出人减少的最低资本与分入人增加的最低资本原则上应保持一致","保险风险、市场风险和信用风险的风险暴露不包括非认可资产和非认可负债","独立账户资产和独立账户负债不计提根据保险合同由保单持有人自行承担的市场、信用风险所对应的最低资本","保险公司通过特定安排导致风险暴露和风险特征发生重大变动的，可自行调减其最低资本要求"],"answer":["A","B","C"],"explanation":"通过特定安排导致风险暴露和风险特征发生重大变动的，由银保监会调整其最低资本要求，公司不能自行调减，D错误。","difficulty":2,"type":"scenario","source":"extra"},{"id":"03-S01","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"本规则所称寿险合同是指（　）。","options":["长期寿险合同（含年金保险）、长期健康险合同和长期意外险合同","所有人身保险合同","所有保险合同","长期寿险合同和短期健康险合同"],"answer":"A","explanation":"第二条规定，寿险合同指长期寿险合同（含年金保险）、长期健康险合同和长期意外险合同。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S02","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"寿险合同负债由（　）组成。","options":["未到期责任准备金和未决赔款准备金","最优估计准备金和风险边际","现金流现值和TVOG","保险责任准备金和保户储金"],"answer":"A","explanation":"第三条规定，寿险合同负债由未到期责任准备金和未决赔款准备金组成。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S03","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"未决赔款准备金以（　）为认可价值。","options":["最优估计准备金","财务报表账面价值","风险边际","现金流现值"],"answer":"B","explanation":"第三条规定，未决赔款准备金以财务报表账面价值为认可价值。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S04","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"未到期责任准备金的计算公式为（　）。","options":["最优估计准备金＋风险边际","现金流现值＋风险边际","最优估计准备金－风险边际","现金流现值＋TVOG"],"answer":"A","explanation":"第四条规定，未到期责任准备金＝最优估计准备金＋风险边际。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S05","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"最优估计准备金的计算公式为（　）。","options":["现金流现值＋选择权及保证利益的时间价值","现金流现值＋风险边际","预期现金流入－预期现金流出","账户准备金×TVOG因子"],"answer":"A","explanation":"第七条规定，最优估计准备金＝现金流现值（PV）＋选择权及保证利益的时间价值（TVOG）。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S06","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"关于分保前后寿险合同负债的处理，正确的是（　）。","options":["将分保前的寿险合同负债确认为认可负债，分保前后差额作为应收分保准备金确认为认可资产","将分保后的寿险合同负债确认为认可负债","分保前后负债均确认为认可负债","分保前后差额确认为非认可资产"],"answer":"A","explanation":"第六条规定，应分别评估分保前和分保后的寿险合同负债，分保前的确认为认可负债，差额作为应收分保准备金确认为认可资产。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S07","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"评估万能保险最优估计准备金时，对保险部分与投资部分的现金流应（　）。","options":["合并评估，不进行拆分","分别评估","仅评估保险部分","仅评估投资部分"],"answer":"A","explanation":"第九条规定，评估万能保险最优估计准备金时，应对保险部分与投资部分的现金流合并评估，不进行拆分。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S08","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"投资连结保险独立账户负债的认可价值等于（　）。","options":["独立账户资产在评估日的市场价值","独立账户资产的账面价值","非账户部分的最优估计准备金","独立账户资产的未来现金流现值"],"answer":"A","explanation":"第十条规定，独立账户负债的认可价值等于独立账户资产在评估日的市场价值。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S09","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"折现率曲线由（　）形成。","options":["基础利率曲线加综合溢价","无风险利率曲线加信用溢价","国债收益率曲线加流动性溢价","市场利率曲线加通胀补偿"],"answer":"A","explanation":"第十九条规定，计算现金流现值所采用的折现率曲线由基础利率曲线加综合溢价形成。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S10","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"基础利率曲线由三段组成，其中期望无风险收益率曲线适用的期限为（　）。","options":["0＜t≤t1","t1＜t≤t2","t＞t2","全部期限"],"answer":"A","explanation":"第十九条规定，期望无风险收益率曲线适用于0＜t≤t1，终极利率过渡曲线适用于t1＜t≤t2，终极利率水平适用于t＞t2。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S11","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"TVOG的计算公式为（　）。","options":["PV（账户准备金）×TVOG因子","账户准备金×TVOG因子","PV（账户准备金）＋TVOG因子","现金流现值×85%"],"answer":"A","explanation":"第二十条规定，TVOG＝PV（账户准备金）×TVOG因子。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S12","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"风险边际计算的分位点法中，所采用的概率水平为（　）。","options":["75%","85%","95%","99.5%"],"answer":"B","explanation":"第二十一条规定，风险边际＝MC×Φ⁻¹(85%)/Φ⁻¹(99.5%)，其中分位点概率α＝85。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S13","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"分保前的风险边际计算时，应按照（　）计算分保前保险风险最低资本。","options":["偿付能力监管规则第5号","偿付能力监管规则第4号","偿付能力监管规则第2号","本规则第二十条"],"answer":"A","explanation":"第二十二条规定，按照《保险公司偿付能力监管规则第5号：保险风险最低资本（寿险业务）》计算分保前保险风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S14","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"评估时点起连续36个月内，万能保险结算利率假设与投资收益率假设之间的利差不得高于（　）。","options":["投资收益率假设的25%与150BP之间的较小值","投资收益率假设的25%与150BP之间的较大值","100BP","50BP"],"answer":"A","explanation":"附件1规定，结算利率假设与投资收益率假设的利差不得高于投资收益率假设的25%与150BP之间的较小值。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S15","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"月度结算的万能保险产品，当月结算利率假设不得低于上月结算利率复利年化水平的（　）。","options":["80%","94.57%","98.16%","105%"],"answer":"C","explanation":"附件1规定，月度结算产品当月利率假设不得低于上月的98.16%；季度结算为94.57%，年度结算为80%。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S16","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"死亡发生率假设计算所采用的基础生命表为（　）。","options":["《中国人寿保险业经验生命表（2010～2013）》","《中国人身保险业重大疾病经验发生率表（2020）》","《中国人寿保险业经验生命表（2000～2003）》","公司自身经验生命表"],"answer":"A","explanation":"附件2规定，死亡发生率假设的基础生命表为《中国人寿保险业经验生命表（2010～2013）》。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S17","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"重疾率假设中乘数因子为（　）。","options":["0.65","0.7","1.0","0.8"],"answer":"B","explanation":"附件2规定，重疾率假设的乘数因子假设为0.7。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S18","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"核保选择因子不受上下限约束的保单年度为（　）。","options":["前1个保单年度","前3个保单年度","前5个保单年度","全部保单年度"],"answer":"B","explanation":"附件2规定，核保选择因子前3个保单年度由保险公司根据自身经验确定，不受上下限约束，其他保单年度为1。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S19","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"保险公司有证据证明最近两年每年保单维持费用的实际金额与自身费用假设的比例不超过（　）的，可采用自身费用假设。","options":["100%","105%","110%","95%"],"answer":"B","explanation":"第十五条规定，最近两年每年实际金额与自身费用假设的比例不超过105%的，可采用自身费用假设。","difficulty":2,"type":"concept","source":"core"},{"id":"03-S20","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"每保单费用的物价总水平变动假设下限为每年度（　）。","options":["1%","2%","3%","5%"],"answer":"B","explanation":"附件3规定，每保单费用的物价总水平变动假设下限为每年度2%。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M01","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"关于寿险合同负债的评估，下列说法正确的有（　）。","options":["计量单元可以是单个保险合同","计量单元可以是具有同质保险风险的保险合同组合","计量单元的确定标准在各评估期间应保持一致","计量单元可随意变更"],"answer":["A","B","C"],"explanation":"第五条规定，计量单元可为单个合同或同质风险组合，确定标准在各评估期间应保持一致，不得随意变更。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M02","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"预期未来现金流出主要包括（　）。","options":["根据保险合同承诺的保证利益，包括死亡给付、残疾给付、生存给付等","构成推定义务的非保证利益，包括分红保险红利给付等","保单维持费用，包括续期佣金、保险保障基金、监管费等","预期未来保费收入"],"answer":["A","B","C"],"explanation":"第八条规定现金流出包括保证利益、非保证利益、保单维持费用和其他现金流出；保费收入属于预期未来现金流入。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M03","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"基础利率曲线由以下（　）部分组成。","options":["期望无风险收益率曲线","终极利率过渡曲线","终极利率水平","综合溢价曲线"],"answer":["A","B","C"],"explanation":"第十九条规定，基础利率曲线由期望无风险收益率曲线、终极利率过渡曲线和终极利率水平三段组成；综合溢价是折现率曲线的另一构成部分而非基础利率曲线的组成段。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M04","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"关于TVOG的计算，下列说法正确的有（　）。","options":["保险公司应计算分红保险、万能保险和变额年金保险等业务的TVOG","万能保险的PV（账户准备金）为万能保单账户价值的现值之和","计算现值之和时应使用评估日及以后各年度末的账户准备金","应按本规则规定的折现率曲线计算PV（账户准备金）"],"answer":["A","B","C","D"],"explanation":"第二十条对TVOG的计算作出规定，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M05","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"下列TVOG因子（单位：万分之一）对应关系正确的有（　）。","options":["保证利率0（含）~1%（含）：16","保证利率2%~2.5%（含）：24","保证利率2.5%~3%（含）：38","保证利率3%~3.5%（含）：65"],"answer":["A","B","C","D"],"explanation":"附件5规定，各档保证利率对应TVOG因子分别为16、19、24、38、65、100，选项所列均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M06","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"保险公司预测分红保险保单红利现金流出应满足的条件包括（　）。","options":["评估时点起连续36个月内，红利水平假设下限不得低于产品说明书红利演示中低档红利水平","红利水平假设在预测期间不得低于0","当年年度红利水平假设不得低于上年度红利水平的80%","红利水平假设不得低于上年度的120%"],"answer":["A","B","C"],"explanation":"附件1规定分红保险红利假设须同时满足两项条件：36个月内不低于演示中低档水平且不低于0；当年红利不低于上年度的80%。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M07","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"关于保险事故发生率假设，下列说法正确的有（　）。","options":["应根据公司的实际经验和未来发展变化趋势确定","不得超过银保监会规定的上限或下限","高于上限时采用上限作为假设","低于下限时采用下限作为假设"],"answer":["A","B","C","D"],"explanation":"第十四条对发生率假设的确定和上下限约束作出规定，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M08","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"关于死亡发生率假设的乘数因子，下列说法正确的有（　）。","options":["非养老类业务一表个人业务乘数因子下限为0.65","非养老类业务二表个人业务乘数因子下限为0.70","养老类业务表乘数因子上限为1.00","团体业务的乘数因子与个人业务相同"],"answer":["A","B","C","D"],"explanation":"附件2规定，非养老类一表为下限0.65、非养老类二表为下限0.70、养老类为上限1.00，个人业务与团体业务数值相同。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M09","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"关于退保率假设的设定，下列说法正确的有（　）。","options":["退保给付包含退保、账户部分领取和停缴续期保费","自身退保率假设高于指导区间上限时采用上限作为备考退保率假设","应分别计算自身假设和备考假设下的现金流现值，选取现值较大者对应的假设","退保率假设指导区间见附件4"],"answer":["A","B","C","D"],"explanation":"第十七条规定了退保率假设的设定步骤和退保给付的范围，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"03-M10","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"下列业务或情形中，由保险公司以自身经验分析为基础确定合理退保率假设的有（　）。","options":["经代、网销、电销等其他渠道的产品","1999年（含）以前签发的高利率保单","进入领取期的年金保险","所有个险渠道的分红产品"],"answer":["A","B","C"],"explanation":"附件4规定，经代、网销、电销等其他渠道产品、1999年（含）以前签发的高利率保单、进入领取期的年金保险由公司以自身经验分析为基础确定退保率假设。","difficulty":2,"type":"concept","source":"core"},{"id":"03-X-S01","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"根据规则第3号，寿险合同的未到期责任准备金等于：","options":["现金流现值＋TVOG","最优估计准备金＋风险边际","现金流现值＋风险边际","账户准备金＋TVOG"],"answer":"B","explanation":"未到期责任准备金＝最优估计准备金＋风险边际；而最优估计准备金＝现金流现值（PV）＋选择权及保证利益的时间价值（TVOG）。","difficulty":1,"type":"concept","source":"extra"},{"id":"03-X-S02","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"根据规则第3号，短期意外伤害险合同的负债认可价值确定方式为：","options":["按本规则采用未来现金流折现的精算方法评估","以财务报表账面价值为认可价值","按退保金与现金价值中的较大者确定","按法定最低准备金标准确定"],"answer":"B","explanation":"短期寿险合同、短期意外伤害险合同、短期健康险合同的负债以财务报表账面价值为认可价值，不适用本规则的评估方法。","difficulty":1,"type":"concept","source":"extra"},{"id":"03-X-S03","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"某万能保险产品最低保证利率为2.2%，其账户准备金现值为100亿元。该产品的TVOG为：","options":["0.19亿元","0.24亿元","0.38亿元","0.16亿元"],"answer":"B","explanation":"保证利率2%（含）~2.5%（含）档的TVOG因子为24（万分之一），TVOG＝PV（账户准备金）×TVOG因子＝100×24/10000＝0.24亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"03-X-S04","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"某人身险公司评估时点寿险合同的保险风险最低资本MC为200亿元，已知Φ⁻¹(85%)＝1.036，Φ⁻¹(99.5%)＝2.576。采用分位点法计算的风险边际约为：","options":["100亿元","96.6亿元","80.4亿元","40.2亿元"],"answer":"C","explanation":"风险边际＝MC×Φ⁻¹(85%)/Φ⁻¹(99.5%)＝200×1.036/2.576≈80.4亿元，分位点概率为85%。","difficulty":3,"type":"calc","source":"extra"},{"id":"03-X-S05","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"根据规则第3号，寿险合同负债评估的折现率基础利率曲线由下列哪三段组成：","options":["期望无风险收益率曲线、终极利率过渡曲线、终极利率水平","即期利率曲线、远期利率曲线、到期利率曲线","无风险曲线、信用溢价曲线、流动性溢价曲线","短期国债曲线、中期国债曲线、长期国债曲线"],"answer":"A","explanation":"基础利率曲线由三段组成：期望无风险收益率曲线（0＜t≤t1）、终极利率过渡曲线（t1＜t≤t2）、终极利率水平（t＞t2），再加综合溢价形成折现率曲线。","difficulty":2,"type":"concept","source":"extra"},{"id":"03-X-S06","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"某万能保险产品采用月度结算，上月结算利率（年化）为4.8%。根据规则第3号，本月结算利率不得低于：","options":["4.80%","4.71%","4.61%","3.84%"],"answer":"B","explanation":"月度结算产品当月利率不得低于上月的98.16%，即4.8%×98.16%≈4.71%。","difficulty":2,"type":"calc","source":"extra"},{"id":"03-X-S07","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"single","q":"根据规则第3号分位点法风险边际计算公式，公式中MC的含义是：","options":["公司的全部最低资本","评估时点寿险合同的保险风险最低资本","公司的市场风险最低资本","非寿险业务的保险风险最低资本"],"answer":"B","explanation":"分位点法公式中MC为评估时点寿险合同的保险风险最低资本，该最低资本按规则第2号体系计量，体现规则间的衔接。","difficulty":3,"type":"cross","source":"extra"},{"id":"03-X-M01","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"根据规则第3号，下列属于本规则所指寿险合同范围的有：","options":["长期寿险合同","年金保险合同","长期健康险合同","保险期间为一年的意外伤害险合同"],"answer":["A","B","C"],"explanation":"寿险合同指长期寿险合同（含年金保险）、长期健康险合同和长期意外险合同；一年期意外险属于短期业务，不适用本规则。","difficulty":1,"type":"concept","source":"extra"},{"id":"03-X-M02","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"下列关于TVOG因子（单位：万分之一）按保证利率水平分档的表述，正确的有：","options":["0（含）~1%（含）为16","2%~2.5%（含）为19","3%~3.5%（含）为65","高于3.5%为100"],"answer":["A","C","D"],"explanation":"2%~2.5%（含）档的TVOG因子为24而非19（19对应1%~2%档），B错误；A、C、D均符合TVOG因子表。","difficulty":2,"type":"concept","source":"extra"},{"id":"03-X-M03","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"某人身险公司评估死亡发生率假设。下列表述正确的有：","options":["基础生命表为《中国人寿保险业经验生命表（2010～2013）》","非养老类业务的乘数因子下限为0.65","养老类业务的乘数因子上限为1.20","前3个保单年度的核保选择因子由保险公司根据自身经验确定，不受上下限约束"],"answer":["A","B","D"],"explanation":"养老类业务的乘数因子上限为1.00而非1.20，C错误；死亡发生率假设＝基础生命表×乘数因子×核保选择因子。","difficulty":3,"type":"scenario","source":"extra"},{"id":"03-X-M04","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"某人身险公司对某类寿险合同进行再保险安排并评估负债。下列表述正确的有：","options":["分保后的寿险合同负债应确认为认可负债","分保前的寿险合同负债应确认为认可负债","分保前后负债的差额作为应收分保准备金确认为认可资产","未决赔款准备金以财务报表账面价值为认可价值"],"answer":["B","C","D"],"explanation":"保险公司应将分保前的寿险合同负债确认为认可负债，分保前后差额作为应收分保准备金确认为认可资产；未决赔款准备金以财务报表账面价值为认可价值。","difficulty":2,"type":"scenario","source":"extra"},{"id":"03-X-M05","rule_no":3,"rule_title":"寿险合同负债评估","qtype":"multi","q":"某人身险公司同时经营万能保险和投资连结保险。在偿付能力目的下评估其合同负债时，下列表述正确的有：","options":["评估万能保险最优估计准备金时，保险部分与投资部分的现金流合并评估，不进行拆分","评估投资连结保险时，应将独立账户部分和非账户部分分别评估","投连险独立账户负债认可价值等于独立账户资产在评估日的市场价值","评估万能保险时，应将保险部分与投资部分的现金流分别评估"],"answer":["A","B","C"],"explanation":"万能保险的保险部分与投资部分合并评估、不拆分；投资连结保险应将独立账户部分和非账户部分分别评估，独立账户负债认可价值等于独立账户资产在评估日的市场价值。","difficulty":2,"type":"scenario","source":"extra"},{"id":"04-S01","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"本规则的适用主体不包括（　）。","options":["财产保险公司","人身保险公司","外国保险公司分公司","再保险公司及其分公司"],"answer":"D","explanation":"第二条规定，本规则适用于财产保险公司、人身保险公司和外国保险公司分公司，但不包括再保险公司及其分公司。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S02","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"保险公司非寿险业务的保险风险包括（　）。","options":["保费及准备金风险、巨灾风险","市场风险、信用风险","操作风险、战略风险","保险风险、流动性风险"],"answer":"A","explanation":"第五条规定，非寿险业务的保险风险包括保费及准备金风险和巨灾风险。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S03","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"根据综合因子法，风险因子RF的计算公式为（　）。","options":["RF＝RF0×(1＋K)","RF＝RF0＋K","RF＝RF0×K","RF＝RF0/(1＋K)"],"answer":"A","explanation":"第七条规定，RF＝RF0×(1＋K)，其中K为特征因子，K∈[－0.25，0.25]。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S04","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"特征因子K的取值区间为（　）。","options":["[－0.25，0.25]","[－0.5，0.5]","[0，0.25]","[－0.25，0]"],"answer":"A","explanation":"第七条规定，K＝k1＋k2＋…＋kn，K∈[－0.25，0.25]，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S05","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"各业务类型保费风险最低资本的风险暴露为该业务类型（　）的自留保费。","options":["最近12个月","最近6个月","上一个会计年度","当年累计"],"answer":"A","explanation":"第九条规定，保费风险最低资本风险暴露为该业务类型最近12个月的自留保费。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S06","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"车险保费风险的基础因子RF0为（　）。","options":["0.098","0.103","0.123","0.203"],"answer":"B","explanation":"第十条规定，车险保费风险基础因子RF0＝0.103。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S07","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"非融资性信用保证险保费风险的基础因子RF0为（　）。","options":["0.326","0.391","0.467","0.605"],"answer":"C","explanation":"第十五条规定，非融资性信用保证险保费风险基础因子RF0＝0.467。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S08","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"各业务类型准备金风险最低资本的风险暴露为该业务类型的（　）。","options":["最近12个月自留保费","再保后未决赔款准备金","未到期责任准备金","总准备金"],"answer":"B","explanation":"第二十二条规定，准备金风险最低资本的风险暴露为该业务类型的再保后未决赔款准备金。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S09","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"财产险准备金风险的基础因子RF0为（　）。","options":["0.433","0.561","0.604","0.441"],"answer":"B","explanation":"第二十四条规定，财产险准备金风险基础因子RF0＝0.561。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S10","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"当最近12个月综合成本率C∈[100%，105%)时，多数险种保费风险特征系数k1为（　）。","options":["－0.05","0","0.05","0.1"],"answer":"C","explanation":"各险种条款规定，综合成本率在[100%，105%)区间时k1＝0.05。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S11","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"对上一会计年度车险原保费收入与分入保费收入之和小于20亿元的保险公司，车险保费风险的调控性特征系数k5为（　）。","options":["－0.15","0","0.15","－0.10"],"answer":"A","explanation":"第十条规定，上一会计年度车险原保费收入与分入保费收入之和小于20亿元的，k5＝－0.15；其他公司k5＝0。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S12","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"融资性信用保证险中，个人住房抵押贷款的基础因子RFi为（　）。","options":["0.052","0.078","0.105","0.157"],"answer":"A","explanation":"第三十五条基础因子表规定，个人住房抵押贷款为0.052，追加贷款部分0.157，个人其他贷款0.078，企业类及其他贷款0.105。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S13","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"融资性信用保证险的风险暴露EXi为（　）。","options":["再保后贷款余额－对应再保后未决赔款准备金","再保后贷款余额","承保保费","最近12个月自留保费"],"answer":"A","explanation":"第三十五条规定，EXi＝承保的第i种贷款类型再保后贷款余额－第i种贷款类型对应的再保后未决赔款准备金。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S14","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"融资性信用保证险中，前十大交易对手集中度P集中度∈[5%，100%]时，特征系数k3为（　）。","options":["0","0.1","0.2","0.25"],"answer":"C","explanation":"第三十八条规定，P集中度在[5%，100%)区间时k3＝0.2，在[0，5%)区间时k3＝0。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S15","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"各业务类型保费及准备金风险最低资本计算中，MC保费与MC准备金的相关系数ρ为（　）。","options":["0.25","0.35","0.5","0.65"],"answer":"C","explanation":"第四十二条规定，ρ为MC保费和MC准备金的相关系数，ρ＝0.5。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S16","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"保险公司应对（　）业务计提巨灾风险最低资本。","options":["车险和财产险","所有非寿险业务","责任险和农业险","信用保证险和短期健康险"],"answer":"A","explanation":"第四十五条规定，保险公司应对车险和财产险业务计提巨灾风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S17","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"巨灾风险的风险区域划分，境外按照（　）四个区域划分。","options":["东亚、西亚、欧洲、其他","亚太、北美、欧洲、其他","亚洲、美洲、欧洲、非洲","亚太、北美、南美、欧洲"],"answer":"B","explanation":"第四十六条规定，境外巨灾风险区域按亚太、北美、欧洲、其他四个区域划分。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S18","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"巨灾风险最低资本计算的置信度p为（　）。","options":["95%","97.5%","99%","99.5%"],"answer":"D","explanation":"第四十七条至第五十一条规定，各巨灾风险最低资本计算公式中置信度p＝99.5%。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S19","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"关于境内车险台风及洪水巨灾风险最低资本的计算范围，正确的是（　）。","options":["只计算商业车险中的车损险及其附加险","计算交强险和商业车险全部险种","只计算交强险","只计算商业三责险"],"answer":"A","explanation":"第四十七条规定，境内车险台风洪水巨灾风险应计算商业车险中的车损险及其附加险，不计算交强险和商业车险中其他险种。","difficulty":2,"type":"concept","source":"core"},{"id":"04-S20","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"非寿险业务保险风险最低资本公式中的调控性特征因子K，对专业科技保险公司取值为（　）。","options":["0.9","1","1.1","0.8"],"answer":"A","explanation":"第五十五条规定，专业科技保险公司K＝0.9，其他保险公司K＝1。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M01","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"非寿险业务划分为以下哪些类型（　）。","options":["车险、财产险、船货特险","责任险、农业险","信用保证险","短期意外伤害险、短期健康险、短期寿险"],"answer":["A","B","C","D"],"explanation":"第六条规定非寿险业务分为车险、财产险、船货特险、责任险、农业险、信用保证险、短期意外伤害险、短期健康险、短期寿险、其他险十类。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M02","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"关于综合因子法的计算，下列说法正确的有（　）。","options":["MC＝EX×RF","RF＝RF0×(1＋K)","K为特征系数之和","对特征系数ki无明确规定并赋值的，ki＝0"],"answer":["A","B","D"],"explanation":"第七条规定，K为特征因子（各特征系数ki之和），ki为单个特征系数；选项C表述混淆了K与ki。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M03","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"下列关于各业务类型保费风险基础因子RF0的数值，正确的有（　）。","options":["财产险0.391","责任险0.203","短期健康险0.115","农业险0.232"],"answer":["A","B","C"],"explanation":"第十一、十三、十四、十七条规定：财产险0.391、责任险0.203、短期健康险0.115、农业险0.326；0.232为船货特险的基础因子。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M04","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"下列关于各业务类型准备金风险基础因子RF0的数值，正确的有（　）。","options":["车险0.123","船货特险0.604","短期意外伤害险0.251","财产险0.433"],"answer":["A","B","C"],"explanation":"第二十三、二十四、二十五、二十九条规定：车险0.123、财产险0.561、船货特险0.604、短意险0.251；0.433为责任险基础因子。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M05","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"车险保费风险最低资本的特征系数包括（　）。","options":["根据最近6个月综合成本率设定的k1","根据6个月综合成本率变动设定的k2","根据非比例分保净分出比例设定的k3","根据公司与行业累计原保费收入增速相对值设定的k4"],"answer":["A","B","C","D"],"explanation":"第十条规定，车险保费风险特征系数包括k1（最近6个月综合成本率）、k2（综合成本率变动）、k3（非比例分保净分出比例）、k4（增速相对值）和k5（发展阶段）。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M06","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"关于融资性信用保证险最低资本计量，下列说法正确的有（　）。","options":["采用综合因子法计算","风险暴露为再保后贷款余额减去对应再保后未决赔款准备金","特征因子Ki∈[－0.25，0.25]","个人其他贷款根据年化损失率设定特征系数k5"],"answer":["A","B","C","D"],"explanation":"第三十五条至第四十条规定了融资性信用保证险的综合因子法计算、风险暴露定义、K区间及k5年化损失率系数，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M07","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"融资性信用保证险的基础因子包括（　）。","options":["个人住房抵押贷款0.052","已抵押房产追加贷款部分0.157","个人其他贷款0.078","企业类贷款0.105"],"answer":["A","B","C","D"],"explanation":"第三十五条基础因子表列示了各类贷款的基础因子，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M08","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"关于巨灾风险最低资本，下列说法正确的有（　）。","options":["境内业务的巨灾风险以保险金额作为风险暴露","境外业务的巨灾风险以保费作为风险暴露","境内风险区域按省（自治区、直辖市）行政区划划分","巨灾风险仅包括台风洪水风险"],"answer":["A","B","C"],"explanation":"第四十六条规定了境内外风险暴露与区域划分；巨灾风险包括台风洪水和地震等类型（境内财产险需计提地震巨灾风险）。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M09","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"关于境内车险与财产险巨灾风险的相关系数矩阵，下列数值正确的有（　）。","options":["车险台风与财产险台风的相关系数为0.65","车险台风与财产险地震的相关系数为0","财产险台风与财产险地震的相关系数为0","车险台风与财产险台风的相关系数为0.25"],"answer":["A","B","C"],"explanation":"第五十四条相关系数表显示，车险台风与财产险台风相关系数0.65，财产险地震与车险台风、财产险台风的相关系数均为0。","difficulty":2,"type":"concept","source":"core"},{"id":"04-M10","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"关于最终非寿险业务保险风险最低资本的计量，下列说法正确的有（　）。","options":["由保费及准备金风险最低资本与巨灾风险最低资本聚合计算","MC保费及准备金与MC巨灾的相关系数为0.25","专业科技保险公司的调控性特征因子K为0.9","其他保险公司的调控性特征因子K为1"],"answer":["A","B","C","D"],"explanation":"第五十五条规定了最终聚合公式，ρ＝0.25，专业科技保险公司K＝0.9，其他保险公司K＝1，选项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"04-X-S01","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"根据规则第4号，非寿险业务的保险风险包括：","options":["保费及准备金风险和巨灾风险","保险风险和市场风险","保费风险和信用风险","巨灾风险和操作风险"],"answer":"A","explanation":"非寿险业务的保险风险包括保费及准备金风险和巨灾风险；市场风险、信用风险属于其他可资本化风险，按相应规则计量。","difficulty":1,"type":"concept","source":"extra"},{"id":"04-X-S02","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"根据规则第4号综合因子法，风险因子RF＝RF0×(1＋K)，其中特征系数之和K的取值范围为：","options":["[-0.25，0.25]","[-0.5，0.5]","[0，0.25]","[-0.25，0]"],"answer":"A","explanation":"综合因子法下RF＝RF0×(1＋K)，K＝k1＋k2＋…＋kn，且K∈[－0.25，0.25]。","difficulty":1,"type":"concept","source":"extra"},{"id":"04-X-S03","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"某财产险公司车险业务最近12个月的自留保费为100亿元，车险保费风险基础因子RF0为0.103，各特征系数均为0。该车险业务的保费风险最低资本为：","options":["10.3亿元","12.3亿元","39.1亿元","20.3亿元"],"answer":"A","explanation":"保费风险最低资本＝EX×RF0×(1＋K)＝100×0.103×(1＋0)＝10.3亿元；12.3亿元是误用准备金风险因子0.123的结果。","difficulty":2,"type":"calc","source":"extra"},{"id":"04-X-S04","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"某财产险公司责任险业务的保费风险最低资本为10亿元，准备金风险最低资本为8亿元，两者相关系数ρ为0.5。该业务责任险保费及准备金风险最低资本约为：","options":["18亿元","13.42亿元","15.62亿元","12.65亿元"],"answer":"C","explanation":"MC＝√(10²＋8²＋2×0.5×10×8)＝√244≈15.62亿元；18亿元是忽略相关系数直接相加的结果。","difficulty":3,"type":"calc","source":"extra"},{"id":"04-X-S05","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"某财产险公司上一会计年度车险原保费收入与分入保费收入之和为12亿元，最近12个月车险自留保费为50亿元，车险保费风险基础因子为0.103，k5特征系数适用小公司标准，其他特征系数均为0。其车险保费风险最低资本约为：","options":["5.15亿元","4.38亿元","3.60亿元","5.98亿元"],"answer":"B","explanation":"车险原保费收入与分入保费之和小于20亿元，适用k5＝－0.15，MC＝50×0.103×(1－0.15)≈4.38亿元；5.15亿元是不考虑k5的结果。","difficulty":2,"type":"calc","source":"extra"},{"id":"04-X-S06","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"某财产险公司承保境外财产险业务并计量巨灾风险最低资本。其风险暴露和风险区域的确定方式为：","options":["以保险金额作为风险暴露，按省（自治区、直辖市）划分风险区域","以保费作为风险暴露，按亚太、北美、欧洲、其他四个区域划分","以保险金额作为风险暴露，按国别划分风险区域","以再保后未决赔款准备金作为风险暴露，按洲际区域划分"],"answer":"B","explanation":"巨灾风险计量中，境内业务以保险金额作为风险暴露并按省划分风险区域；境外业务以保费作为风险暴露，按亚太、北美、欧洲、其他四个区域划分。","difficulty":2,"type":"scenario","source":"extra"},{"id":"04-X-S07","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"single","q":"某专业科技保险公司保费及准备金风险最低资本为100亿元，巨灾风险最低资本为20亿元。该公司非寿险业务保险风险最低资本约为：","options":["106.8亿元","96.1亿元","108亿元","85.4亿元"],"answer":"B","explanation":"聚合值＝√(100²＋2×0.25×100×20＋20²)＝√11400≈106.77亿元，再乘以调控性特征因子K＝0.9（专业科技保险公司），约96.1亿元。","difficulty":3,"type":"cross","source":"extra"},{"id":"04-X-M01","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"根据规则第4号，下列关于业务类型划分及适用范围的表述，正确的有：","options":["船舶保险属于船货特险","工程保险属于财产险","短期健康险属于非寿险业务","再保险公司及其分公司适用本规则"],"answer":["A","B","C"],"explanation":"再保险公司及其分公司不适用本规则，D错误；财产险包括企业财产保险、家庭财产保险和工程保险，船货特险包括船舶保险、货物运输保险、特殊风险保险。","difficulty":1,"type":"concept","source":"extra"},{"id":"04-X-M02","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"下列关于非寿险业务基础因子RF0的表述，正确的有：","options":["车险保费风险基础因子为0.103","财产险保费风险基础因子为0.391","车险准备金风险基础因子为0.103","责任险保费风险基础因子为0.203"],"answer":["A","B","D"],"explanation":"车险准备金风险基础因子为0.123而非0.103，C错误；A、B、D均与规则第4号规定的基础因子一致。","difficulty":2,"type":"concept","source":"extra"},{"id":"04-X-M03","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"下列关于综合成本率特征系数k1（多数险种适用）的表述，正确的有：","options":["综合成本率C∈[0，95%)时，k1为－0.05","综合成本率C∈[95%，100%)时，k1为0","某公司车险综合成本率为103%，处于[100%，105%)区间，k1为0.05","综合成本率小于0时，k1为－0.05"],"answer":["A","B","C"],"explanation":"经营期限不足无法计算特征系数或综合成本率小于0的，ki＝0而非－0.05，D错误；A、B、C均符合k1的赋值标准。","difficulty":2,"type":"concept","source":"extra"},{"id":"04-X-M04","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"某财产险公司计量巨灾风险最低资本。下列表述正确的有：","options":["境内车险台风及洪水巨灾风险只计算商业车险中的车损险及其附加险，不计算交强险","境外业务以保险金额作为风险暴露","境内业务按省（自治区、直辖市）划分风险区域","巨灾地震风险与境内车险台风洪水风险的相关系数为0"],"answer":["A","C","D"],"explanation":"境外业务以保费作为风险暴露，B错误；境内车险台风洪水与境内财产险台风洪水相关系数为0.65，地震风险与两者相关系数均为0。","difficulty":3,"type":"scenario","source":"extra"},{"id":"04-X-M05","rule_no":4,"rule_title":"保险风险最低资本（非寿险业务）","qtype":"multi","q":"某财产险公司经营融资性信用保证险业务。下列表述正确的有：","options":["融资性信用保证险属于市场风险，按市场风险规则计量","风险暴露EXi＝再保后贷款余额－对应的再保后未决赔款准备金","个人住房抵押贷款的基础因子为0.052","融资性信用保证险承保不受限于特定风险事件"],"answer":["B","C","D"],"explanation":"融资性信用保证险属于保险风险，按本规则计量而非市场风险，A错误；B、C、D均为规则第4号的规定。","difficulty":2,"type":"scenario","source":"extra"},{"id":"05-S01","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"本规则所称保险公司不包括下列哪类机构？","options":["健康保险公司","养老保险公司","再保险公司及其分公司","相互保险组织"],"answer":"C","explanation":"第二条规定，本规则所称保险公司不含再保险公司及其分公司；相互保险组织依第二十六条适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S02","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"下列哪项业务不属于本规则所称寿险业务的范围？","options":["长期寿险（含年金保险）业务","长期健康险业务","长期意外险业务","短期健康险"],"answer":"D","explanation":"第三条规定寿险业务包括长期寿险、长期健康险及长期意外险业务，不包括短期意外险、短期健康险和短期寿险。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S03","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"寿险业务保险风险最低资本采用的计算方法是：","options":["风险因子法","情景法","压力测试法","方差-协方差法"],"answer":"B","explanation":"第六条规定，寿险业务保险风险最低资本采用情景法计算，即分别在基础情景假设和不利情景假设下计算评估日的现金流现值。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S04","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"寿险业务保险风险最低资本的基本计算公式为：","options":["MC保险 = Max（PV不利情景 − PV基础情景，0）","MC保险 = PV基础情景 − PV不利情景","MC保险 = PV不利情景 × SF","MC保险 = Max（PV基础情景 − PV不利情景，0）"],"answer":"A","explanation":"第六条规定最低资本等于两种情景下现金流现值之差，且不得为负，即MC保险 = Max（PV不利情景 − PV基础情景，0）。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S05","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"不利情景假设与基础情景假设的关系是：","options":["不利情景假设 = 基础情景假设 ×（1 + SF）","不利情景假设 = 基础情景假设 + SF","不利情景假设 = 基础情景假设 ÷（1 + SF）","不利情景假设 = SF × 基础情景假设 ÷ 2"],"answer":"A","explanation":"第六条规定，不利情景假设 = 基础情景假设 ×（1 + SF），SF为不利情景因子，表示对基础情景假设上浮或下浮一定比例。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S06","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"保险公司确定寿险业务保险风险最低资本适用的不利情景，计量单元一般为：","options":["保险公司的全部寿险业务","单个保险产品或具有同质风险的保险合同组合在评估日的所有有效保单","单一保单","按季度划分的保单组合"],"answer":"B","explanation":"第七条规定，应以单个保险产品或具有同质风险的保险合同组合在评估日的所有有效保单作为计量单元，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S07","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"死亡发生率风险的不利情景因子SF赋值为：","options":["10%","15%","20%","25%"],"answer":"B","explanation":"第九条规定，死亡发生率风险SF为未来剩余保险期间内死亡发生率上浮一定比例，赋值为15%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S08","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"死亡巨灾风险的不利情景为在基础情景假设基础上，评估日后的12个月内年度死亡发生率：","options":["上浮15%","上浮20%","增加绝对数额0.0018","上浮10%"],"answer":"C","explanation":"第十条规定，死亡巨灾风险不利情景为评估日后12个月内年度死亡发生率增加绝对数额0.0018，属于绝对数增加而非比例上浮。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S09","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"长寿风险是指死亡发生率改善的实际经验高于预期导致的风险，其不利情景因子在前10年的赋值方式是：","options":["每年死亡率下浮3%","每年死亡率下浮2%","每年死亡率上浮3%","死亡率一次性下浮3%"],"answer":"A","explanation":"第十一条给出了长寿风险SF的分段赋值：评估日后第1至10个年度，SF = 1 − 3%的t次方减1，即每年下浮3%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S10","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"专属商业养老保险业务的长寿风险不利情景因子SF长寿风险等于：","options":["SF × 0.8","SF × 0.9","SF × 1.1","SF × 0.95"],"answer":"B","explanation":"第十一条规定，专属商业养老保险业务的长寿风险不利情景因子SF长寿风险 = SF × 0.9。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S11","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"疾病风险包括以下哪两类风险？","options":["疾病发生率风险和疾病趋势风险","疾病发生率风险和疾病恶化风险","疾病趋势风险和医疗赔付风险","疾病发生率风险和长寿风险"],"answer":"A","explanation":"第十二条规定，疾病风险包括疾病发生率风险和疾病趋势风险。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S12","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"疾病发生率风险的不利情景因子SF赋值为：","options":["10%","15%","20%","25%"],"answer":"C","explanation":"第十二条规定，疾病发生率风险SF为未来剩余保险期间内疾病发生率上浮一定比例，赋值为20%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S13","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"疾病趋势风险中，女性疾病发生趋势因子的赋值为：","options":["1%","2%","3%","5%"],"answer":"C","explanation":"第十二条规定，趋势因子中男性疾病发生趋势因子赋值为2%，女性赋值为3%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S14","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"疾病风险最低资本计算公式中，疾病趋势风险与疾病发生率风险间的风险相关系数ρ赋值为：","options":["0.2","0.25","0.4","0.5"],"answer":"B","explanation":"第十二条（三）规定，ρ为疾病趋势风险与疾病发生率风险间的风险相关系数，赋值为0.25。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S15","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"费用风险的不利情景因子SF赋值为：","options":["5%","10%","15%","20%"],"answer":"B","explanation":"第十八条规定，费用风险SF为未来剩余保险期间内各年度维持费用上浮一定比例，赋值为10%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S16","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"费用风险的不利情景计量中，维持费用不包含下列哪项？","options":["保单管理费用","续期佣金","保险保障基金","续期佣金、保险保障基金、监管费"],"answer":"D","explanation":"第十八条规定，费用风险不利情景因子针对各年度维持费用（不含续期佣金、保险保障基金、监管费）上浮。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S17","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"退保率风险计量中，确定计量单元归属产品类型时，若计量单元内超过50%的有效保单的现金价值与累计生存金之和首次超过已交保费的整数年度大于10年，则该计量单元归属：","options":["类型Ⅰ","类型Ⅱ","类型Ⅲ","特殊类型"],"answer":"A","explanation":"第二十一条规定，超过50%的有效保单的该整数年度大于10年时归属类型Ⅰ，否则归属类型Ⅱ。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S18","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"退保率风险中，类型Ⅱ计量单元的不利情景因子SF1和SF2分别为：","options":["30%和−30%","40%和−40%","30%和−40%","40%和−30%"],"answer":"B","explanation":"第二十一条因子表规定，类型Ⅰ的SF1=30%、SF2=−30%；类型Ⅱ的SF1=40%、SF2=−40%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S19","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"大规模退保风险的不利情景为评估日后的12个月内年度退保率上浮多少（退保率以100%为上限）？","options":["100%","120%","150%","200%"],"answer":"C","explanation":"第二十二条规定，大规模退保风险不利情景为评估日后12个月内年度退保率上浮150%，且上浮后的月度退保率假设不低于2.4%或年度退保率假设不低于25%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-S20","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"保险公司寿险业务的保险风险最低资本汇总公式中，MC向量由以下哪三项组成？","options":["（MC死亡, MC疾病, MC退保）","（MC损失发生, MC费用, MC退保）","（MC死亡, MC长寿, MC费用）","（MC损失发生, MC费用, MC医健）"],"answer":"B","explanation":"第二十四条规定，MC向量由（MC损失发生, MC费用, MC退保）组成，通过相关系数矩阵汇总计算寿险业务保险风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M01","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于本规则的适用范围，下列说法正确的有：","options":["适用于依法在中华人民共和国境内设立的人身保险公司","健康保险公司适用本规则","再保险公司适用本规则","相互保险组织适用本规则"],"answer":["A","B","D"],"explanation":"第二条规定适用于境内经营商业保险业务的人身保险公司（含健康保险公司和养老保险公司），不包括再保险公司及其分公司；第二十六条规定相互保险组织适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M02","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"寿险业务保险风险包括下列哪些风险？","options":["损失发生风险","费用风险","退保风险","市场风险"],"answer":["A","B","C"],"explanation":"第五条规定，保险公司寿险业务保险风险包括损失发生风险、费用风险和退保风险；市场风险属于其他类风险，不在本规则范围。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M03","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"损失发生风险包括下列哪些子风险？","options":["死亡发生率风险","死亡巨灾风险","长寿风险","疾病风险"],"answer":["A","B","C","D"],"explanation":"第八条规定，损失发生风险包括死亡发生率风险、死亡巨灾风险、长寿风险、疾病风险、医疗及健康赔付损失率风险、其他损失发生率风险。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M04","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"下列关于死亡巨灾风险的说法，正确的有：","options":["巨灾事件如流行病、地震、海啸等的发生可能导致短期内死亡发生率大幅上升","不利情景为评估日后12个月内年度死亡发生率增加绝对数额0.0018","以评估日全部寿险业务的有效保单作为计量单元","不利情景为评估日后12个月内年度死亡率上浮15%"],"answer":["A","B","C"],"explanation":"第十条规定，死亡巨灾风险由流行病、地震、海啸等巨灾事件引起，不利情景为12个月内年度死亡发生率增加绝对数额0.0018，以全部寿险业务有效保单为计量单元；15%是死亡发生率风险的比例上浮，不是巨灾风险。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M05","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于长寿风险不利情景因子SF的赋值，下列说法正确的有：","options":["评估日后第1至10个年度每年下浮3%","第11至20个年度每年下浮2%","第21至30个年度每年下浮1%","超过30年后死亡率不再变化"],"answer":["A","B","C"],"explanation":"第十一条给出了SF的分段公式：前10年每年下浮3%，第11-20年每年下浮2%，第21-30年每年下浮1%，超过30年时SF固定为累计乘积形式不再继续下浮，并非死亡率不再变化。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M06","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"下列各风险的不利情景因子SF赋值为20%的包括：","options":["疾病发生率风险","医疗及健康赔付损失率风险","其他损失发生率风险（第九至十三条未涵盖的）","死亡发生率风险"],"answer":["A","B","C"],"explanation":"第十二条、第十三条、第十四条分别规定疾病发生率风险、医疗及健康赔付损失率风险及其他损失发生率风险的SF均为20%；死亡发生率风险SF为15%。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M07","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于疾病风险最低资本的计算，下列说法正确的有：","options":["疾病发生率风险与疾病趋势风险通过相关系数矩阵汇总","相关系数ρ赋值为0.25","计算公式考虑了两个子风险的平方和及交叉项","疾病风险最低资本等于疾病发生率风险和疾病趋势风险最低资本的简单加总"],"answer":["A","B","C"],"explanation":"第十二条（三）规定，MC疾病 = √（MC疾病发生率² + MC疾病趋势² + 2×ρ×MC疾病发生率×MC疾病趋势），ρ=0.25，并非简单加总。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M08","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于退保率风险的计量，下列说法正确的有：","options":["计量单元包含万能、投资连结、变额年金等产品的，直接归属类型Ⅱ","确定计量单元归属产品类型时需考虑非保证利益部分","需分别采用SF1和SF2计算现金流现值PVSF1和PVSF2","PV不利情景 = Max（PVSF1，PVSF2）"],"answer":["A","C","D"],"explanation":"第二十一条规定，包含万能、投连、变额年金等产品的计量单元直接归属类型Ⅱ，且确定产品类型时不考虑非保证利益部分；应分别用SF1、SF2计算现值并取较大者作为PV不利情景。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M09","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于大规模退保风险，下列说法正确的有：","options":["由金融危机、声誉危机等特殊事件引发","评估日后12个月内年度退保率上浮150%","上浮后的月度退保率假设不低于2.4%或年度退保率假设不低于25%","计量单元包含评估日现金价值为0的保单"],"answer":["A","B","C"],"explanation":"第二十二条规定，大规模退保风险由特殊事件引发，12个月内年度退保率上浮150%，月度退保率不低于2.4%或年度不低于25%；计量单元为所有有效保单但不含评估日现金价值为0的保单。","difficulty":2,"type":"concept","source":"core"},{"id":"05-M10","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于寿险业务保险风险最低资本汇总相关系数矩阵，下列说法正确的有：","options":["损失发生风险与费用风险的相关系数为0.4","损失发生风险与退保风险的相关系数为0","费用风险与退保风险的相关系数为0.5","损失发生风险与退保风险的相关系数为0.25"],"answer":["A","B","C"],"explanation":"第二十五条的汇总相关系数矩阵规定：损失发生与费用0.4、损失发生与退保0、费用与退保0.5。","difficulty":2,"type":"concept","source":"core"},{"id":"05-X-S01","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"根据第5号规则，下列哪项业务属于本规则所规范的寿险业务范围？","options":["一年期短期健康险","长期健康险","一年期短期意外险","一年期定期寿险"],"answer":"B","explanation":"寿险业务包括长期寿险（含年金保险）、长期健康险及长期意外险，不包括短期意外险、短期健康险和短期寿险。","difficulty":1,"type":"concept","source":"extra"},{"id":"05-X-S02","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某人身险公司计量专属商业养老保险的长寿风险，其不利情景因子应如何确定？","options":["直接适用普通寿险业务的长寿风险SF","普通寿险业务长寿风险SF×0.9","普通寿险业务长寿风险SF×1.1","统一按每年下浮3%执行"],"answer":"B","explanation":"长寿风险SF为死亡率逐年下浮（第1-10年每年3%、第11-20年每年2%、第21-30年每年1%），专属商业养老保险的长寿风险SF=SF×0.9。","difficulty":1,"type":"concept","source":"extra"},{"id":"05-X-S03","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某寿险公司某计量单元基础情景死亡发生率为0.004，按死亡发生率风险SF=15%计算，不利情景假设应为多少？","options":["0.0046","0.0052","0.0060","0.0055"],"answer":"A","explanation":"不利情景假设=基础情景假设×（1+SF）=0.004×1.15=0.0046。","difficulty":2,"type":"calc","source":"extra"},{"id":"05-X-S04","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某寿险公司某计量单元的疾病发生率风险最低资本为10百万元，疾病趋势风险最低资本为8百万元，相关系数ρ=0.25，则疾病风险最低资本约为多少？","options":["14.28百万元","18.00百万元","12.81百万元","16.12百万元"],"answer":"A","explanation":"MC疾病=√（10²+8²+2×0.25×10×8）=√204≈14.28百万元。","difficulty":2,"type":"calc","source":"extra"},{"id":"05-X-S05","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某寿险公司开发了一款万能保险产品，在计量退保率风险时，该产品的计量单元应归属的类型是？","options":["类型Ⅰ","类型Ⅱ","由公司根据经验自行选择","按保单件数规模确定"],"answer":"B","explanation":"包含万能、投资连结、变额年金等产品的计量单元直接归属类型Ⅱ（确定产品类型时不考虑非保证利益部分）。","difficulty":2,"type":"scenario","source":"extra"},{"id":"05-X-S06","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某寿险公司正面临声誉危机，需计量大规模退保风险最低资本，下列关于其不利情景的表述正确的是？","options":["评估日后12个月内年度退保率上浮150%，上浮后月度退保率假设不低于2.4%或年度退保率假设不低于25%","评估日后12个月内年度退保率上浮100%，上浮后月度退保率假设不低于2%","评估日后24个月内年度退保率上浮150%，上浮后年度退保率假设不低于20%","仅对类型Ⅰ产品计量，上浮后年度退保率假设不低于25%"],"answer":"A","explanation":"大规模退保风险不利情景为评估日后12个月内年度退保率上浮150%，且上浮后的月度退保率假设不低于2.4%或年度退保率假设不低于25%。","difficulty":3,"type":"scenario","source":"extra"},{"id":"05-X-S07","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"single","q":"某人身险公司计量寿险业务保险风险最低资本时，PV基础情景和PV不利情景的现金流现值应按下列哪项规则考虑再保因素后计算？","options":["第1号规则（实际资本）","第3号规则（寿险合同负债评估）","第4号规则（非寿险业务保险风险）","第8号规则（市场风险最低资本）"],"answer":"B","explanation":"第5号规则规定，PV基础情景和PV不利情景均按照第3号规则（寿险合同负债评估）考虑再保因素后计算现金流现值。","difficulty":3,"type":"cross","source":"extra"},{"id":"05-X-M01","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"根据第5号规则，寿险业务保险风险包括下列哪些风险？","options":["损失发生风险","费用风险","退保风险","市场风险"],"answer":["A","B","C"],"explanation":"寿险业务保险风险包括损失发生风险、费用风险和退保风险三大类；市场风险属于另一类偿付能力风险。","difficulty":1,"type":"concept","source":"extra"},{"id":"05-X-M02","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"在计量费用风险最低资本（SF=10%）时，下列哪些费用项目不包括在计量范围内？","options":["续期佣金","保单行政管理费","保险保障基金","监管费"],"answer":["A","C","D"],"explanation":"费用风险SF=10%的计量不含续期佣金、保险保障基金和监管费，保单维持费用（如行政管理费）属于计量范围。","difficulty":2,"type":"concept","source":"extra"},{"id":"05-X-M03","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于退保率风险的不利情景因子，下列说法正确的有？","options":["类型Ⅰ的SF1为30%","类型Ⅰ的SF2为−40%","类型Ⅱ的SF1为40%","退保率以100%为上限"],"answer":["A","C","D"],"explanation":"类型Ⅰ的SF1=30%、SF2=−30%；类型Ⅱ的SF1=40%、SF2=−40%；退保率以100%为上限，PV不利情景取PVSF1与PVSF2较大者。","difficulty":2,"type":"calc","source":"extra"},{"id":"05-X-M04","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"某寿险公司汇总寿险业务保险风险最低资本时，关于相关系数的下列说法正确的有？","options":["死亡发生率风险与长寿风险的相关系数为−0.25","损失发生风险与退保风险的相关系数为0","费用风险与退保风险的相关系数为0.25","损失发生风险与费用风险的相关系数为0.4"],"answer":["A","B","D"],"explanation":"损失发生风险中死亡与长寿为−0.25；寿险总体中损失发生与费用为0.4、损失发生与退保为0、费用与退保为0.5（不是0.25）。","difficulty":3,"type":"scenario","source":"extra"},{"id":"05-X-M05","rule_no":5,"rule_title":"保险风险最低资本（寿险业务）","qtype":"multi","q":"关于第5号规则计量单元的规定，下列说法正确的有？","options":["确定不利情景一律以公司全部业务作为计量单元","死亡巨灾风险以全部寿险业务有效保单作为计量单元","大规模退保风险计量时不含评估日现金价值为0的保单","退保率风险类型判定时不考虑非保证利益部分"],"answer":["B","C","D"],"explanation":"确定不利情景以单个保险产品或同质风险合同组合在评估日的所有有效保单作为计量单元（并非全部业务）；B、C、D均为规则的明确规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"06-S01","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"本规则所称再保险公司不包括下列哪项？","options":["境内经营再保险业务的再保险公司","境外再保险公司的分支机构","境内直接保险公司","被银保监会指定适用本规则的直接保险公司"],"answer":"C","explanation":"第二条规定，再保险公司指境内经营再保险业务的再保险公司和境外再保险公司的分支机构；直接保险公司仅在银保监会依第三十八条指定时才适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S02","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"再保险业务分为非寿险再保险业务和寿险再保险业务，二者均包括：","options":["合约再保险和临分再保险","比例再保险和非比例再保险","共保再保险和修正共保再保险","法定再保险和商业再保险"],"answer":"A","explanation":"第三条规定，非寿险再保险业务和寿险再保险业务均包括合约再保险和临分再保险；比例/非比例的划分仅适用于非寿险再保险业务。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S03","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"本规则第四条将非寿险再保险业务划分为多少类？","options":["10类","11类","13类","15类"],"answer":"C","explanation":"第四条列举了比例类10种加非比例类3种共十三类非寿险再保险业务，对应保费及准备金风险汇总矩阵中的MC1至MC13。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S04","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"以年度保证续保方式分保的业务认定为寿险再保险业务，需满足的条件是：","options":["仅保证续保","仅保证再保险费率","保证续保且保证再保险费率（包括浮动范围）","保证续保且合同期限超过1年"],"answer":"C","explanation":"第五条规定，以年度保证续保方式分保的业务须同时满足保证续保和保证再保险费率（包括保证再保险费率浮动范围）两个条件方为寿险再保险业务，否则为非寿险再保险业务。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S05","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非寿险再保险业务的保险风险是指由于什么假设的实际经验与预期发生不利偏离导致的风险？","options":["赔付率等假设","死亡率假设","退保率假设","投资收益率假设"],"answer":"A","explanation":"第七条规定，非寿险再保险业务的保险风险是指由于赔付率等假设的实际经验与预期发生不利偏离，导致再保险公司遭受非预期损失的风险。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S06","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非寿险再保险业务的保险风险最低资本计算的第一步是：","options":["计算巨灾风险最低资本","计算各非寿险再保险业务类型的保费风险最低资本和准备金风险最低资本","计算保费及准备金风险最低资本","计算保险风险最低资本"],"answer":"B","explanation":"第八条规定计算步骤依次为：各类型保费风险和准备金风险→各类型保费及准备金风险→业务整体保费及准备金风险→巨灾风险→保险风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S07","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非寿险再保险业务的保费风险和准备金风险最低资本采用的计算方法是：","options":["情景法","综合因子法","风险矩阵法","蒙特卡洛模拟法"],"answer":"B","explanation":"第九条规定，保费风险最低资本和准备金风险最低资本采用综合因子法计算，公式为MC = EX × RF。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S08","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"综合因子法中风险因子RF的计算公式为：","options":["RF = RF0 ×（1 + K）","RF = RF0 + K","RF = RF0 × K","RF = RF0 ÷（1 + K）"],"answer":"A","explanation":"第九条规定，RF = RF0 ×（1 + K），其中RF0为基础因子，K为特征系数之和。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S09","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"关于特征系数ki，若偿付能力监管规则无明确规定并赋值，则ki取值为：","options":["0","0.5","1","由公司自行确定"],"answer":"A","explanation":"第九条规定，特征系数由偿付能力监管规则规定和赋值，无明确规定并赋值的，则ki = 0。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S10","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"分出公司向境内分入公司提供计算保险风险最低资本所必需相关数据的时限是：","options":["每季度结束后10日内","每季度结束后15日内","每季度结束后30日内","每月结束后10日内"],"answer":"A","explanation":"第十条规定，分出公司应当在每季度结束后10日内向境内分入公司提供融资性信用保证险贷款余额、车险和财产险有效保险金额、境外业务有效保单保费等必需数据。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S11","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非比例再保险业务保费风险最低资本的风险暴露EX为：","options":["该类型业务的再保后未决赔款准备金","该类型业务的过去12个月自留保费","该类型业务的年度自留保费","该类型业务的有效保额"],"answer":"B","explanation":"第十三条规定，非比例再保险业务保费风险最低资本的风险暴露EX为该类型业务的过去12个月自留保费。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S12","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非比例财产再保险的保费风险基础因子RF0赋值为：","options":["0.254","0.376","0.394","1.85"],"answer":"C","explanation":"第十四条规定，非比例财产再保险的保费风险基础因子RF0赋值为0.394。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S13","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"责任险、短期意外险、短期健康险和短期寿险的非比例再保险的准备金风险基础因子RF0赋值为：","options":["0.488","0.541","0.653","0.394"],"answer":"A","explanation":"第二十一条规定，责任险、短期意外险、短期健康险和短期寿险的非比例再保险的准备金风险基础因子RF0赋值为0.488。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S14","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非比例再保险业务准备金风险最低资本的风险暴露EX为：","options":["该类型业务的过去12个月自留保费","该类型业务的再保后未决赔款准备金","该类型业务的再保后应收保费","该类型业务的年度总保费"],"answer":"B","explanation":"第十九条规定，非比例再保险业务准备金风险最低资本的风险暴露EX为该类型业务的再保后未决赔款准备金。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S15","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"各业务类型保费及准备金风险最低资本计算公式中，保费风险与准备金风险的相关系数ρ为：","options":["0.25","0.4","0.5","1"],"answer":"C","explanation":"第二十三条规定，ρ为MC保费i和MC准备金i的相关系数，ρ = 0.5。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S16","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"再保险公司应当对哪些险种的再保险业务计提巨灾风险最低资本？","options":["车险和财产险","责任险和信用险","农业险和船舶险","短期意外险和短期健康险"],"answer":"A","explanation":"第二十六条规定，再保险公司应当对车险和财产险的再保险业务计提巨灾风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S17","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非比例再保险业务巨灾风险基础因子RF0为：","options":["0.394","0.653","1.85","2.5"],"answer":"C","explanation":"第二十九条规定，非比例再保险业务巨灾风险基础因子RF0 = 1.85。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S18","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"非寿险再保险业务保险风险最低资本计算公式中，保费及准备金风险与巨灾风险的相关系数ρ为：","options":["0.25","0.4","0.5","0.75"],"answer":"A","explanation":"第三十一条规定，ρ为MC保费及准备金和MC巨灾的相关系数，ρ = 0.25。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S19","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"寿险再保险业务的保险风险最低资本计量适用哪项规则？","options":["第4号规则（非寿险业务）","第5号规则（寿险业务）","第7号规则（穿透计量）","第8号规则（市场风险）"],"answer":"B","explanation":"第三十四条规定，寿险再保险业务的保险风险最低资本计量适用第5号规则，退保率风险不利情景因子适用产品类型Ⅰ。","difficulty":2,"type":"concept","source":"core"},{"id":"06-S20","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"寿险再保险合同涵盖多个保险产品的，确定保险风险最低资本适用的不利情景时，计量单元为：","options":["整个再保险合同","单个保险产品在评估日所有有效原保险合同","全部寿险再保险业务","按再保险费规模划分的合同组"],"answer":"B","explanation":"第三十六条规定，应以单个保险产品在评估日所有有效原保险合同作为一个计量单元；现金流取决于多个计量单元的应将多个计量单元合并。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M01","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"本规则第四条所列的非比例再保险业务类型包括：","options":["非比例财产险","非比例责任险及非比例短期人身险","非比例特殊险","非比例农业险"],"answer":["A","B","C"],"explanation":"第四条列举的非比例类业务为（十一）非比例财产险、（十二）非比例责任险及非比例短期人身险、（十三）非比例特殊险；农业险包含在非比例特殊险之中，没有单独的非比例农业险类别。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M02","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"以年度保证续保方式分保的业务认定为寿险再保险业务需满足的条件包括：","options":["保证续保","保证再保险费率（包括保证再保险费率浮动范围）","合同期限超过5年","分保金额超过一定门槛"],"answer":["A","B"],"explanation":"第五条规定，同时满足保证续保和保证再保险费率（包括浮动范围）两个条件的为寿险再保险业务，否则为非寿险再保险业务。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M03","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于保证再保险费率浮动范围的经济实质判断，下列说法正确的有：","options":["再保险公司可以选择将浮动范围不具有经济实质的业务归入非寿险再保险业务","具有经济实质指该浮动范围能够对交易双方产生清晰可辨认的经济影响","判断时应从浮动范围的限制是否可被触及进行考虑","交易双方无需就经济实质判断进行沟通"],"answer":["A","B","C"],"explanation":"第五条规定，再保险公司可以选择将保证再保险费率浮动范围不具有经济实质的业务归入非寿险再保险业务；经济实质指对交易双方产生清晰可辨认的经济影响，从限制是否可被触及判断；交易双方应对经济实质判断进行沟通并保持一致。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M04","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"第4号规则中不适用于再保险公司比例再保险业务保费风险的特征系数包括：","options":["非比例分保净分出比例特征系数","车险的综合成本率变动特征系数","保费收入增速特征系数","保险公司发展阶段特征系数"],"answer":["A","B","C","D"],"explanation":"第十二条规定，非比例分保净分出比例、车险综合成本率变动、保费收入增速、保险公司发展阶段以及融资性信用保证险最低资本的特征系数均不适用。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M05","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于非比例财产再保险保费风险风险暴露的计算，下列说法正确的有：","options":["风险暴露为过去12个月自留保费","不包括财产险巨灾超赔再保险的自留保费","不包括财产险位与巨灾混合超赔再保险的自留保费","风险暴露为再保后未决赔款准备金"],"answer":["A","B","C"],"explanation":"第十三条规定，非比例再保险业务保费风险风险暴露为过去12个月自留保费，且非比例财产再保险计算风险暴露时不包括财产险巨灾超赔和财产险位与巨灾混合超赔再保险的自留保费。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M06","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"下列关于非比例再保险业务基础因子的赋值，正确的有：","options":["非比例财产再保险保费风险RF0=0.394","责任险等非比例再保险保费风险RF0=0.254","非比例特殊风险再保险准备金风险RF0=0.541","非比例财产再保险准备金风险RF0=0.488"],"answer":["A","B","C"],"explanation":"第十四至二十二条规定：非比例财产保费RF0=0.394、责任险等保费RF0=0.254、非比例特殊保费RF0=0.376；准备金方面非比例财产0.653、责任险等0.488、非比例特殊0.541。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M07","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于非寿险再保险业务巨灾风险最低资本，下列说法正确的有：","options":["比例再保险业务的巨灾风险最低资本适用第4号规则","非比例再保险业务巨灾风险的风险暴露为过去12个月自留保费","既包含险位又包含巨灾的非比例业务以全部自留保费作为风险暴露","比例巨灾与非比例巨灾的相关系数为0.25"],"answer":["A","B","C"],"explanation":"第二十七至三十条规定：比例业务适用第4号规则；非比例巨灾风险暴露为过去12个月自留保费，险位与巨灾混合业务以全部自留保费为风险暴露；比例巨灾与非比例巨灾的相关系数ρ=0.5，非0.25。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M08","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于寿险再保险业务保险风险最低资本，下列说法正确的有：","options":["包括损失发生风险、费用风险和退保风险","计量适用第5号规则","退保率风险不利情景因子适用产品类型Ⅰ","应毛额计算，不考虑转分保"],"answer":["A","B","C"],"explanation":"第三十三至三十五条规定，寿险再保险业务保险风险包括损失发生风险、费用风险和退保风险，计量适用第5号规则，退保率风险适用产品类型Ⅰ，且应以转分保后的净现金流为基础评估再保险合同负债。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M09","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"分出公司应当及时向分入公司提供的寿险再保险业务保单信息包括：","options":["产品责任","保费","保额","保单件数"],"answer":["A","B","C","D"],"explanation":"第三十七条规定，分出公司应及时提供计算保险风险最低资本所必需的保单信息，包括但不限于产品责任、保费、保额、保单件数等。","difficulty":2,"type":"concept","source":"core"},{"id":"06-M10","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于本规则的适用与解释，下列说法正确的有：","options":["银保监会可根据审慎监管需要指定满足特定条件的直接保险公司适用本规则","被指定的直接保险公司同时延伸适用其他偿付能力监管规则的再保险相关规定","本规则由银保监会负责解释和修订","本规则于2021年12月30日第一次发布"],"answer":["A","B","C"],"explanation":"第三十八、三十九条规定，银保监会可指定直接保险公司适用本规则并延伸适用再保险相关规定，本规则由银保监会负责解释和修订；第四十条规定本规则于2015年2月13日第一次发布，2021年12月30日修订发布。","difficulty":2,"type":"concept","source":"core"},{"id":"06-X-S01","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"根据第6号规则，本规则适用于下列哪类主体？","options":["境内经营再保险业务的再保险公司和境外再保险公司的分支机构","仅境内依法设立的再保险公司","全部直接保险公司","境内商业保险公司和外国保险公司分公司"],"answer":"A","explanation":"第6号规则适用于境内经营再保险业务的再保险公司和境外再保险公司的分支机构；银保监会可指定符合条件的直接保险公司适用。","difficulty":1,"type":"concept","source":"extra"},{"id":"06-X-S02","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"根据第6号规则，非寿险再保险业务共分为多少类？","options":["10类","11类","13类","15类"],"answer":"C","explanation":"非寿险再保险业务分为13类，其中比例类10种、非比例类3种，各类业务分别计量后通过相关系数矩阵汇总。","difficulty":1,"type":"concept","source":"extra"},{"id":"06-X-S03","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"某再保险公司非比例财产再保险业务过去12个月自留保费为1亿元（已剔除财产险巨灾超赔及险位巨灾混合超赔业务的自留保费），特征系数K=0.05，则该业务保费风险最低资本为多少？","options":["4137万元","3940万元","3490万元","4410万元"],"answer":"A","explanation":"MC=EX×RF0×（1+K）=10000万×0.394×1.05=4137万元；非比例财产再保险保费风险RF0=0.394。","difficulty":2,"type":"calc","source":"extra"},{"id":"06-X-S04","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"某再保险公司某类非寿险再保险业务的保费风险最低资本为600万元，准备金风险最低资本为400万元，保费与准备金风险相关系数ρ=0.5，则该类业务保费及准备金风险最低资本约为多少？","options":["871.78万元","1000万元","721.11万元","923.76万元"],"answer":"A","explanation":"MC=√（600²+400²+2×0.5×600×400）=√760000≈871.78万元。","difficulty":2,"type":"calc","source":"extra"},{"id":"06-X-S05","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"再保险公司B以合约方式承接某寿险公司的长期寿险分保业务，在计量该业务退保率风险时，适用的不利情景因子为？","options":["SF1=30%、SF2=−30%（产品类型Ⅰ）","SF1=40%、SF2=−40%（产品类型Ⅱ）","由再保险公司根据经验自行设定","SF1=15%、SF2=−15%"],"answer":"A","explanation":"第6号规则规定，寿险再保险业务的退保率风险适用产品类型Ⅰ，即SF1=30%、SF2=−30%。","difficulty":2,"type":"scenario","source":"extra"},{"id":"06-X-S06","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"某境外再保险公司分公司以年度保证续保方式承接分保业务，判断该业务是否属于寿险再保险业务时，须同时满足的条件是？","options":["保证续保且保证再保险费率（含浮动范围）","仅须满足保证续保条件","仅须满足保证再保险费率条件","交易双方可随时协商调整再保险费率"],"answer":"A","explanation":"年度保证续保方式分保的业务须同时满足保证续保和保证再保险费率（含浮动范围）两个条件方为寿险再保险业务；浮动范围还须具有经济实质（限制可被触及）。","difficulty":3,"type":"scenario","source":"extra"},{"id":"06-X-S07","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"single","q":"某再保险公司同时经营比例财产再保险合约业务和非比例责任险超赔临分业务，关于两类业务保险风险最低资本的计量路径，正确的是？","options":["比例业务的保费、准备金和巨灾风险适用第4号规则（部分特征系数不适用），非比例业务按第6号规则计量","两类业务均按第6号规则的综合因子法计量","两类业务均适用第4号规则计量","非比例业务适用第5号规则计量"],"answer":"A","explanation":"比例再保险业务适用第4号规则（非寿险业务），但非比例分保净分出比例等特征系数不适用；非比例业务按第6号规则规定的综合因子法计量。","difficulty":3,"type":"cross","source":"extra"},{"id":"06-X-M01","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于第6号规则中再保险业务及主体的界定，下列说法正确的有？","options":["非寿险再保险业务包含合约再保险和临分再保险","寿险再保险业务包含合约再保险和临分再保险","再保险公司包括境外再保险公司的分支机构","相互保险组织一律适用本规则"],"answer":["A","B","C"],"explanation":"再保险业务（非寿险/寿险）均含合约和临分两类；再保险公司包括境外再保险公司分支机构；相互保险组织并非本规则的适用主体。","difficulty":1,"type":"concept","source":"extra"},{"id":"06-X-M02","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"根据第6号规则，关于分出公司的数据报送义务，下列说法正确的有？","options":["分出公司应在每季度结束后10日内向境内分入公司提供计算保险风险最低资本所必需的相关数据","寿险再保险业务中，分出公司应及时提供产品责任、保费、保额、保单件数等保单信息","数据报送时限为每季度结束后15日内","相关数据仅需每年报送一次"],"answer":["A","B"],"explanation":"第10条规定分出公司应在每季度结束后10日内向境内分入公司提供计算保险风险最低资本所需数据；寿险再保业务还应及时提供保单相关信息。","difficulty":2,"type":"concept","source":"extra"},{"id":"06-X-M03","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于非比例再保险业务的基础因子RF0，下列数值正确的有？","options":["非比例财产再保险保费风险RF0为0.394","责任险、短期意外险、短期健康险和短期寿险的非比例再保险保费风险RF0为0.254","非比例财产再保险准备金风险RF0为0.488","非比例特殊风险再保险准备金风险RF0为0.541"],"answer":["A","B","D"],"explanation":"非比例财产再保险准备金风险RF0为0.653（0.488是责任险等的准备金风险因子），其余三项数值均正确。","difficulty":2,"type":"calc","source":"extra"},{"id":"06-X-M04","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"某再保险公司同时经营车险、财产险比例再保险和非比例巨灾超赔业务，下列说法正确的有？","options":["应对车险和财产险再保险业务计提巨灾风险最低资本","巨灾风险汇总公式中比例巨灾与非比例巨灾的相关系数为0.5","非比例再保险业务巨灾风险基础因子RF0为1.85","非寿险再保险保险风险汇总中保费及准备金风险与巨灾风险的相关系数为0.5"],"answer":["A","B","C"],"explanation":"A、B、C均正确；非寿险再保险保险风险最低资本汇总中，保费及准备金风险与巨灾风险的相关系数为0.25（0.5是巨灾汇总中比例与非比例巨灾之间的相关系数）。","difficulty":3,"type":"scenario","source":"extra"},{"id":"06-X-M05","rule_no":6,"rule_title":"保险风险最低资本（再保险公司）","qtype":"multi","q":"关于寿险再保险业务保险风险的计量，下列说法正确的有？","options":["主要援引第5号规则计量","退保率风险适用产品类型Ⅱ","以转分保后的净现金流为基础评估再保险合同负债","现金流取决于多个计量单元的（如需合同层面合并计算再保手续费），应合并计量单元"],"answer":["A","C","D"],"explanation":"寿险再保险业务计量主要援引第5号规则，退保率风险适用产品类型Ⅰ（而非类型Ⅱ）；B错误，A、C、D均正确。","difficulty":2,"type":"concept","source":"extra"},{"id":"07-S01","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"本规则所称保险公司是指依法在中华人民共和国境内设立的经营商业保险业务的保险公司和：","options":["再保险公司","外国保险公司分公司","保险资产管理公司","相互保险组织"],"answer":"B","explanation":"第二条规定，本规则所称保险公司指境内经营商业保险业务的保险公司和外国保险公司分公司；相互保险组织依第三十五条适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S02","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"基础资产是指风险清晰、信息完备、可以直接计量最低资本的资产，下列哪项属于基础资产？","options":["信托计划","银行理财产品","公募证券投资基金（公开募集基础设施证券投资基金除外）","不动产金融产品"],"answer":"C","explanation":"第三条规定公募证券投资基金（公募REITs除外）属于基础资产；信托计划、银行理财和不动产金融产品均属第四条列举的非基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S03","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"下列哪项不属于本规则列举的非基础资产？","options":["保险资产管理产品","对企业或个人的债权资产","股权投资基金","债转股投资计划"],"answer":"B","explanation":"第四条列举的非基础资产包括信托计划、保险资管产品、股权投资基金、债转股投资计划、SPV、银行理财、资产支持计划、不动产金融产品和公募REITs；对企业或个人的债权资产属于基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S04","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"本规则所称底层资产是指：","options":["非基础资产第一层交易结构涉及的资产","基础资产和豁免穿透的非基础资产","非基础资产穿透后的全部资产","无法穿透的非基础资产"],"answer":"B","explanation":"第六条规定，底层资产是指基础资产和豁免穿透的非基础资产；表层资产才是非基础资产第一层交易结构涉及的资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S05","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"保险公司应当对所有非基础资产进行穿透计量最低资本，这一原则称为：","options":["应穿尽穿原则","穿透到底原则","风险穿透原则","可靠计量原则"],"answer":"A","explanation":"第八条规定应穿尽穿原则，即对所有非基础资产进行穿透计量；穿透到底原则（第九条）是要求逐层穿透至基础资产或豁免穿透的非基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S06","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"保险公司因客观条件限制无法获取非基础资产本季度相关信息进行穿透计量的，可以使用：","options":["上季度投后报告等相关信息","上年度财务报告信息","同类产品的市场平均信息","保险公司自行估计的信息"],"answer":"A","explanation":"第十一条规定，因客观条件限制无法获取本季度信息的，可以使用上季度投后报告等相关信息；本季度和上季度信息均无法获取的，应作为无法穿透的非基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S07","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"非基础资产穿透后，底层资产最低资本计算公式为MC底层资产i = EX底层资产i × RF底层资产i，其中风险因子RF底层资产i = RF0 ×（1 + K + Kp），Kp表示：","options":["基础因子","特征系数","交易结构风险特征系数","信用评级调整系数"],"answer":"C","explanation":"第十四条规定，RF底层资产i = RF0×（1＋K＋Kp），其中Kp为交易结构风险特征系数，K为特征系数。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S08","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"底层资产的风险因子RF底层资产i超过1时，应当：","options":["按实际值计量","取值为1","取值为0.5","由保险公司报银保监会确定"],"answer":"B","explanation":"第十四条明确规定，RF底层资产i超过1时，取值为1。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S09","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"没有公开活跃交易市场且有财务报表的底层资产，其风险暴露应按照什么确定？","options":["市价","财务报表中底层资产的账面价值","投后报告中底层资产的投资金额","认可价值"],"answer":"B","explanation":"第十五条规定，无公开活跃交易市场的底层资产按财务报表账面价值确认风险暴露；没有财务报表的，可按投后报告中投资金额确认。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S10","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"交易结构风险特征系数Kp的确定公式中，非基础资产为债权类资产时Kp等于：","options":["n × 0.1","（n − 1）× 0.1","n × 0.2","（n − 1）× 0.05"],"answer":"B","explanation":"第十八条规定，债权类资产Kp =（n−1）×0.1，其他非基础资产Kp = n×0.1，n为交易结构层数。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S11","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"交易结构风险特征系数Kp公式中的交易结构层数n：","options":["包括表层和底层","包括表层，不包括底层","不包括表层，包括底层","既不包括表层也不包括底层"],"answer":"B","explanation":"第十八条明确规定，n为交易结构的层数，包括表层，不包括底层。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S12","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"对于公开募集基础设施证券投资基金，在计算其底层资产最低资本时设定的特征系数k1赋值为：","options":["−0.2","0.2","−0.1","0.1"],"answer":"A","explanation":"第十九条规定，公开募集基础设施证券投资基金计算底层资产最低资本时设定特征系数k1，赋值为−0.2。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S13","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"关于穿透后底层资产的利率风险计量，下列说法正确的是：","options":["人身保险公司底层固定收益类基础资产不计量利率风险","财产保险公司底层固定收益类基础资产不计量利率风险","人身保险公司底层境内债券应计量利率风险","财产保险公司底层利率金融衍生品不计量利率风险"],"answer":"A","explanation":"第二十条规定，人身保险公司穿透后底层固定收益类基础资产不计量利率风险；财产保险公司穿透后底层境内债券资产和利率金融衍生品等基础资产应计量利率风险。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S14","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"非基础资产表层资产为债权类资产的，其交易对手违约风险的风险暴露EX表层资产为：","options":["底层资产的账面价值","其认可价值","其市场价值","其投资成本"],"answer":"B","explanation":"第二十二条规定，非基础资产的表层资产风险暴露EX表层资产为其认可价值。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S15","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"非基础资产的表层资产基础因子RF0按信用评级赋值，其中信用评级为AAA的表层资产基础因子为：","options":["0.010","0.015","0.020","0.025"],"answer":"A","explanation":"第二十三条评级赋值表规定：AAA为0.010、AA+为0.015、AA为0.020、AA−为0.025、A+/A/A−为0.075、BBB+及以下和无评级为0.150。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S16","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"豁免穿透的组合类保险资产管理产品中，固定收益类产品计量权益价格风险的基础因子为：","options":["0.01","0.06","0.23","0.28"],"answer":"B","explanation":"第二十六条规定：货币市场类0.01、固定收益类0.06、权益类0.28、混合类及商品金融衍生品类0.23。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S17","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"豁免穿透的资产支持计划计量交易对手违约风险，信用评级为AA的基础因子为：","options":["0.1","0.13","0.18","0.23"],"answer":"C","explanation":"第二十八条规定：AAA为0.1、AA+为0.13、AA为0.18、AA−为0.23、A+/A/A−为0.33、BBB+及以下和无评级为0.45。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S18","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"无法穿透的权益类信托计划应当计量什么风险，基础因子为多少？","options":["权益价格风险，0.6","交易对手违约风险，0.6","权益价格风险，0.28","交易对手违约风险，0.45"],"answer":"A","explanation":"第三十一条规定，权益类信托计划等无法穿透的资产应计量权益价格风险，风险暴露为认可价值，基础因子为0.6。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S19","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"非基础资产无法穿透的部分占多少比例以上时，保险公司可以直接将其认定为无法穿透的非基础资产？","options":["50%","70%","90%","95%"],"answer":"C","explanation":"第三十四条规定，非基础资产无法穿透的部分占90%以上的，保险公司可以直接将其认定为无法穿透的非基础资产，按第三十一条和第三十二条计量。","difficulty":2,"type":"concept","source":"core"},{"id":"07-S20","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"保险公司对无法获取本季度和上季度相关信息的非基础资产，应当：","options":["免于计量最低资本","按同类资产平均风险因子计量","将其作为无法穿透的非基础资产","按其账面价值全额计提"],"answer":"C","explanation":"第十一条规定，保险公司无法获取非基础资产本季度或上季度相关信息的，应当将该项资产作为无法穿透的非基础资产，按第五章规定计量。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M01","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"下列资产中属于基础资产的有：","options":["保险公司存放在金融机构的结构性存款","金融衍生品（期货、远期、期权、互换）","银行理财产品","对企业或个人的债权资产"],"answer":["A","B","D"],"explanation":"第三条列举的基础资产包括存款类、金融衍生品和企业或个人债权资产；银行理财产品属第四条列举的非基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M02","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"下列资产中属于非基础资产的有：","options":["信托计划","债权投资计划","公开募集基础设施证券投资基金","以物权方式直接持有的投资性房地产"],"answer":["A","B","C"],"explanation":"信托计划、债权投资计划（属保险资产管理产品）、公募REITs均为第四条列举的非基础资产；以物权方式直接持有的投资性房地产属于基础资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M03","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"保险公司穿透计量应遵循的基本原则包括：","options":["应穿尽穿原则","穿透到底原则","风险穿透原则","可靠计量原则"],"answer":["A","B","C","D"],"explanation":"第二章第八至十二条规定了应穿尽穿、穿透到底、风险穿透、可靠计量、信息穿透五项基本原则。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M04","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"非基础资产最低资本穿透计量包括的内容有：","options":["各项底层资产按照其风险性质并结合交易结构风险分别计量最低资本","表层资产的交易对手违约风险（若表层资产为债权类资产）","表层资产的权益价格风险","基础资产的利率风险"],"answer":["A","B"],"explanation":"第十三条规定的穿透计量包括两部分：底层资产结合交易结构风险的最低资本，以及表层资产为债权类资产时的交易对手违约风险。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M05","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"下列情形中属于无法穿透的非基础资产的有：","options":["无法识别底层资产","无法确定在底层资产中持有的份额","无法可靠计量底层资产的风险暴露","底层资产超过100笔"],"answer":["A","B","C"],"explanation":"第三十条规定无法穿透的三种情形：无法识别底层资产、无法确定持有份额、无法可靠计量风险暴露；底层资产超过100笔是资产支持计划豁免穿透的条件。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M06","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"下列无法穿透的非基础资产中，应当计量权益价格风险的有：","options":["权益类信托计划","股权投资基金","债权投资计划","不动产金融产品"],"answer":["A","B","D"],"explanation":"第三十一条规定九类资产计量权益价格风险（含权益类信托计划、股权投资基金、不动产金融产品等）；债权投资计划属于第三十二条计量交易对手违约风险的资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M07","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"下列无法穿透的非基础资产中，应当计量交易对手违约风险的有：","options":["固定收益类信托计划","债权投资计划","资产支持计划","债转股投资计划"],"answer":["A","B","C"],"explanation":"第三十二条规定，固定收益类信托计划、债权投资计划、资产支持计划计量交易对手违约风险，基础因子均为0.6；债转股投资计划属于第三十一条计量权益价格风险的资产。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M08","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"关于豁免穿透的条件，下列说法正确的有：","options":["全部直接投资于基础资产的组合类保险资产管理产品，最大一笔底层资产账面价值不超过总和的20%可豁免","资产支持计划底层资产大于100笔且最大一笔不超过20%可豁免","现金及流动性管理工具不受20%的限制","银行理财产品一律不得豁免穿透"],"answer":["A","B","C"],"explanation":"第二十五条规定了组合类产品、银行理财、资产支持计划的豁免条件，且现金及流动性管理工具、政府债券、政策性银行金融债券和政府支持机构债券不受20%限制；符合条件的银行理财可以豁免。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M09","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"关于豁免穿透后的计量，下列说法正确的有：","options":["豁免穿透的组合类保险资产管理产品计量权益价格风险","豁免穿透的银行理财产品计量权益价格风险","豁免穿透的资产支持计划计量交易对手违约风险","保险公司可以放弃豁免权选择穿透计量"],"answer":["A","B","C","D"],"explanation":"第二十六至二十八条规定了豁免穿透产品的风险类别，第二十九条规定保险公司可以选择放弃豁免权，按本规则穿透计量。","difficulty":2,"type":"concept","source":"core"},{"id":"07-M10","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"关于部分穿透的计量方法，下列说法正确的有：","options":["可识别的底层资产按第十四条至第二十条计量","无法穿透的部分按第三十一条和第三十二条计量","表层资产为债权类的按第二十一条至第二十三条计量交易对手违约风险","可识别部分应按表层资产风险因子计量"],"answer":["A","B","C"],"explanation":"第三十三条规定的部分穿透三步计量方法：可识别底层资产按第十四条至第二十条，无法穿透部分按第三十一条和第三十二条，表层债权资产按第二十一条至第二十三条计量。","difficulty":2,"type":"concept","source":"core"},{"id":"07-X-S01","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"根据第7号规则，底层资产包括下列哪类资产？","options":["仅指基础资产","基础资产和豁免穿透的非基础资产","全部非基础资产","非基础资产第一层交易结构涉及的资产"],"answer":"B","explanation":"底层资产包括基础资产和豁免穿透的非基础资产两类，而非仅指基础资产；非基础资产第一层交易结构涉及的资产是表层资产。","difficulty":1,"type":"concept","source":"extra"},{"id":"07-X-S02","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"下列哪项不属于第7号规则规定的穿透计量基本原则？","options":["应穿尽穿","穿透到底","实质重于形式","信息穿透"],"answer":"C","explanation":"穿透计量基本原则为应穿尽穿、穿透到底、风险穿透、可靠计量、信息穿透五项，不含实质重于形式。","difficulty":1,"type":"concept","source":"extra"},{"id":"07-X-S03","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"某保险公司持有一项债权类非基础资产（信托计划），其交易结构共3层（含表层、不含底层），则交易结构风险特征系数Kp为多少？","options":["0.2","0.3","0.1","0.15"],"answer":"A","explanation":"债权类资产Kp=（n−1）×0.1=（3−1）×0.1=0.2；其他非基础资产Kp=n×0.1。","difficulty":2,"type":"calc","source":"extra"},{"id":"07-X-S04","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"某债权投资计划作为表层资产计量交易对手违约风险，信用评级为AA，认可价值为5000万元，其特征系数K=−0.2，则该表层资产的交易对手违约风险最低资本为多少？","options":["80万元","100万元","125万元","64万元"],"answer":"A","explanation":"RF=RF0×（1+K）=0.020×（1−0.2）=0.016，MC=5000万×0.016=80万元；AA级表层债权类资产基础因子为0.020。","difficulty":2,"type":"calc","source":"extra"},{"id":"07-X-S05","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"某保险公司持有一款组合类保险资产管理产品，其底层资产中最大一笔资产的账面价值占底层资产账面价值总和的25%，则对该产品的正确处理是？","options":["不满足豁免穿透条件，应按本规则进行穿透计量","满足豁免穿透条件，直接按豁免后的简化方法计量","可直接认定为无法穿透的非基础资产","无需计量市场风险和信用风险最低资本"],"answer":"A","explanation":"豁免穿透的条件之一是最大一笔底层资产账面价值不超过底层资产账面价值总和的20%，本例为25%，不满足条件，应穿透计量。","difficulty":2,"type":"scenario","source":"extra"},{"id":"07-X-S06","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"某保险公司因客观条件限制，本季度无法获取某非基础资产的相关穿透信息，下列处理正确的是？","options":["直接认定为无法穿透的非基础资产","可使用上季度投后报告等信息进行穿透计量","暂停该资产的最低资本计量，待信息获取后补计","按基础资产类别采用综合因子法计量"],"answer":"B","explanation":"因客观条件限制无法获取本季度信息的，可使用上季度投后报告等信息；本季度和上季度信息均无法获取的，才作为无法穿透的非基础资产。","difficulty":3,"type":"scenario","source":"extra"},{"id":"07-X-S07","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"single","q":"某人身保险公司通过信托计划投资于境内债券，穿透后的底层固定收益类基础资产是否计量利率风险最低资本？","options":["不计量利率风险最低资本","应计量利率风险最低资本","按0.6的因子计量利率风险","由公司自行选择是否计量"],"answer":"A","explanation":"人身保险公司穿透后底层固定收益类基础资产不计量利率风险最低资本（该利率风险已在负债端情景法中反映）；财产保险公司穿透后底层境内债券等则应计量利率风险。","difficulty":3,"type":"cross","source":"extra"},{"id":"07-X-M01","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"根据第7号规则，下列属于非基础资产的有？","options":["信托计划","银行理财产品","公募REITs","境内上市公司股票"],"answer":["A","B","C"],"explanation":"非基础资产包括信托计划、保险资管产品、银行理财、资产支持计划、公募REITs等；境内上市公司股票属于基础资产。","difficulty":1,"type":"concept","source":"extra"},{"id":"07-X-M02","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"根据第7号规则，非基础资产属于无法穿透的情形包括？","options":["无法识别底层资产","底层资产分散度不足","无法确定在底层资产中持有的份额","无法可靠计量底层资产风险暴露"],"answer":["A","C","D"],"explanation":"无法穿透的情形包括无法识别底层资产、无法确定持有份额、无法可靠计量风险暴露三种；分散度不足是豁免穿透的条件问题，不是无法穿透的情形。","difficulty":2,"type":"concept","source":"extra"},{"id":"07-X-M03","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"关于穿透计量的参数与规则，下列说法正确的有？","options":["公募REITs计算底层资产最低资本时特征系数k1为−0.2","债权类资产的Kp=（n−1）×0.1","其他非基础资产的Kp=n×0.1","底层资产风险因子RF超过1时无需处理"],"answer":["A","B","C"],"explanation":"RF底层资产超过1时取值为1（并非无需处理）；A、B、C均为规则规定，n为交易结构层数（包括表层，不包括底层）。","difficulty":2,"type":"calc","source":"extra"},{"id":"07-X-M04","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"某财产保险公司持有豁免穿透的固定收益类组合保险资管产品和AAA级资产支持计划，下列说法正确的有？","options":["固定收益类组合产品计量权益价格风险，基础因子为0.06","资产支持计划计量交易对手违约风险，AAA级基础因子为0.1","豁免穿透后仍按0.6的基础因子计量交易对手违约风险","资产支持计划适用豁免穿透还要求底层资产大于100笔"],"answer":["A","B","D"],"explanation":"豁免穿透的固定收益类组合产品按0.06计量权益价格风险；资产支持计划按评级计量交易对手违约风险（AAA为0.1），且豁免须底层资产大于100笔；0.6是无法穿透情形下的因子。","difficulty":3,"type":"scenario","source":"extra"},{"id":"07-X-M05","rule_no":7,"rule_title":"市场风险和信用风险的穿透计量","qtype":"multi","q":"关于穿透计量的监管细节，下列说法正确的有？","options":["政府债券受豁免穿透20%集中度条件的限制","无法穿透的部分占90%以上的，可直接将其认定为无法穿透的非基础资产","保险公司可以选择放弃豁免权，对保险资管产品和银行理财进行穿透计量","债权投资计划作为无法穿透资产计量交易对手违约风险时基础因子为0.6"],"answer":["B","C","D"],"explanation":"现金及流动性管理工具、政府债券、政策性银行金融债券和政府支持机构债券不受20%集中度限制，A错误；B、C、D均为规则规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"08-S01","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"本规则所称市场风险是指由于下列哪些因素的不利变动导致保险公司遭受非预期损失的风险？","options":["利率、权益价格、房地产价格、汇率等","赔付率、费用率、退保率","交易对手违约、信用评级下调","巨灾事件发生"],"answer":"A","explanation":"第三条规定，市场风险是指由于利率、权益价格、房地产价格、汇率等不利变动导致保险公司遭受非预期损失的风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S02","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"保险公司的市场风险不包括下列哪一类？","options":["利率风险","权益价格风险","保险风险","集中度风险"],"answer":"C","explanation":"第四条规定市场风险包括利率风险、权益价格风险、房地产价格风险、境外资产价格风险、汇率风险和集中度风险六类，保险风险属于另一大类风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S03","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"除人身保险公司的利率风险最低资本外，市场风险最低资本采用的计量方法是：","options":["情景法","综合因子法","压力测试法","蒙特卡洛模拟法"],"answer":"B","explanation":"第六条规定，除人身保险公司的利率风险最低资本外，市场风险最低资本采用综合因子法计量，计算公式为MC市场＝EX×RF。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S04","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"综合因子法中，风险暴露EX的取值规则为：","options":["等于该项资产（负债）的认可价值，EX≤0时取值为0","等于该项资产（负债）的账面价值","等于该项资产（负债）的市场价值","等于该项资产（负债）的公允价值"],"answer":"A","explanation":"第六条规定，EX为风险暴露，等于该项资产（负债）的认可价值，另有规定除外；EX≤0时，EX取值为0。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S05","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"综合因子法中，风险因子RF超过或等于1时的处理方式是：","options":["按实际值计量","取值为1","取值为0","报银保监会核定"],"answer":"B","explanation":"第六条规定，RF=RF0×(1+K)，RF≥1时，RF取值为1。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S06","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"综合因子法中特征因子K的取值区间为：","options":["[−0.25, 0.25]","[−0.5, 0.5]","[0, 1]","[−1, 1]"],"answer":"A","explanation":"第六条规定，K = k1+k2+…+kn，K∈[−0.25, 0.25]，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S07","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"保险公司计量某类资产（负债）的市场风险最低资本时，应当：","options":["对该类别的各项资产（负债）分别计量，不得按类别合并计量","按类别合并计量","只计量金额最大的前10项资产","按行业平均水平计量"],"answer":"A","explanation":"第七条规定，应对该类别的各项资产（负债）分别计量，不得按类别合并计量。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S08","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"财产保险公司债券资产利率风险的计量范围中，下列说法正确的是：","options":["包含可转债（可交换债）","不含可转债（可交换债）","包含所有衍生品","不含同业存单"],"answer":"B","explanation":"第十一条规定，计量利率风险的债券资产含央行票据和短期融资券，不含可转债（可交换债）；可转债计入权益价格风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S09","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"财产保险公司债券资产利率风险基础因子RF0的计算公式中，当修正久期D>10时，RF0等于：","options":["D×（−0.001×D+0.0217）","D×（−0.00106×D+0.022）","D×0.0114","0.0114"],"answer":"C","explanation":"第十四条规定，D>10时RF0 = D×0.0114；0<D≤5和5<D≤10分别适用不同的分段公式。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S10","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"对于永续债，如存续期内没有赎回安排，其修正久期D应按照什么计算？","options":["下一赎回日","永续期限","5年","10年"],"answer":"B","explanation":"第十四条规定，永续债存续期内有赎回安排的，D按到期日为下一赎回日计算；没有赎回安排的，D按永续期限计算。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S11","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"利率互换的利率风险暴露EX为：","options":["合约公允价值","合约名义本金","合约市值变动额","合约保证金"],"answer":"B","explanation":"第十五条规定，利率互换的利率风险暴露EX为合约名义本金。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S12","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"人身保险公司利率风险最低资本的计算公式为：","options":["MC = EX × RF","MC = Max[PV(NCF)不利情景 − PV(NCF)基础情景，0]","MC = PV(NCF)基础情景 × SF","MC = Max[PV(NCF)基础情景 − PV(NCF)不利情景，0]"],"answer":"B","explanation":"第十八条规定，人身保险公司利率风险最低资本采用情景法计量，公式为Max[PV(NCF)不利情景−PV(NCF)基础情景，0]。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S13","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"人身保险公司计量利率风险最低资本时，下列哪项资产不在计量范围内？","options":["定期存款","保单质押贷款","境内上市普通股票","利率互换"],"answer":"C","explanation":"第十三条规定人身险公司利率风险计量范围包括存款、债券、其他固定收益类投资资产、利率类金融衍生品、保单质押贷款等；上市普通股票属于权益价格风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S14","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"同时经营财产险和人身险业务的再保险公司，其利率风险最低资本的计量方法是：","options":["全部按财产保险公司规则计量","全部按人身保险公司规则计量","对非寿险业务和寿险业务分别使用综合因子法和情景法计量后算术加总","取两类方法计算结果的较大者"],"answer":"C","explanation":"第二十三条规定，同时经营两类业务的再保险公司应对非寿险业务和寿险业务分别使用综合因子法和情景法计量，经算术加总得到利率风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S15","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"上市普通股票中，创业板股和科创板股的基础因子RF0为：","options":["0.35","0.41","0.45","0.28"],"answer":"C","explanation":"第二十六条规定，沪深主板股基础因子为0.35，创业板股、科创板股为0.45。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S16","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"根据股票是否为沪深300指数成份股设定的特征系数k2，沪深300指数成份股的赋值为：","options":["−0.05","0","0.05","−0.1"],"answer":"A","explanation":"第二十六条规定，k2为−0.05时对应沪深300指数成份股，其他股票为0。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S17","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"货币市场基金的权益价格风险基础因子RF0为：","options":["0.01","0.06","0.23","0.28"],"answer":"A","explanation":"第三十三条规定，货币市场基金的权益价格风险暴露为其认可价值，基础因子RF0赋值为0.01。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S18","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"保险公司以物权形式持有的境内投资性房地产，其房地产价格风险基础因子RF0为：","options":["0.08","0.15","0.23","0.28"],"answer":"B","explanation":"第四十条规定，以物权形式持有的投资性房地产基础因子RF0赋值为0.15。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S19","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"汇率风险最低资本的基础因子RF0，对美元和汇率跟美元挂钩的货币赋值为：","options":["0.05","0.08","0.15",0.25],"answer":"A","explanation":"第五十七条规定，美元和汇率跟美元挂钩的货币RF0=0.05，欧元、英镑为0.08，其他货币为0.15。","difficulty":2,"type":"concept","source":"core"},{"id":"08-S20","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"保险公司直接持有的投资性房地产账面价值占总资产的比例超过多少时，应当计量房地产集中度风险？","options":["15%","20%","25%","30%"],"answer":"C","explanation":"第六十七条规定，投资性房地产账面价值占保险公司总资产的比例超过25%时应当计量房地产集中度风险，特征系数k集中度3赋值为0.5。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M01","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"保险公司的市场风险包括下列哪些类别？","options":["利率风险","权益价格风险","房地产价格风险","保险风险"],"answer":["A","B","C"],"explanation":"第四条规定市场风险包括利率风险、权益价格风险、房地产价格风险、境外资产价格风险、汇率风险和集中度风险六类，不包括保险风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M02","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于人身保险公司利率风险最低资本，下列说法正确的有：","options":["采用情景法计量","应反映无风险利率不利变动对资产、负债的综合影响","NCF为净现金流，等于预期未来现金流出减去预期未来现金流入的差额","基础资产与非基础资产穿透后的底层固定收益类资产均需计量"],"answer":["A","B","C"],"explanation":"第十二、十八条规定情景法计量并反映资产负债综合影响，NCF为流出减流入的差额；根据第7号规则第二十条，人身保险公司非基础资产穿透后底层固定收益类基础资产不计量利率风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M03","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于折现率曲线的构成，下列说法正确的有：","options":["折现率曲线由基础利率曲线加综合溢价形成","基础利率曲线由期望无风险收益率曲线、终极利率过渡曲线和终极利率水平三段组成","终极利率水平由保险公司自行确定","综合溢价由银保监会综合考虑行业资产配置、国债收益率税收效应等因素设定"],"answer":["A","B","D"],"explanation":"第十九条规定，折现率曲线由基础利率曲线加综合溢价形成，基础利率曲线分三段，均由银保监会确定而非公司自行确定。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M04","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于国债期货套期保值的利率风险计量，下列说法正确的有：","options":["符合套期有效性要求且套期期限不低于1个月的，国债期货空头与被套期债券组合合并计算","符合套期有效性要求但套期期限低于1个月的，国债期货空头最低资本等于0","不符合套期有效性要求的，国债期货空头单独计量利率风险最低资本","多头套保的国债期货多头不单独计量最低资本"],"answer":["A","B","C"],"explanation":"第十六条规定了前三种情形的处理；第（四）项明确规定国债期货多头应单独计量最低资本，公式为合约价值×风险因子。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M05","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于权益价格风险的基础因子，下列赋值正确的有：","options":["未上市股权RF0=0.41","债券基金RF0=0.06","股票基金RF0=0.28","对子公司、合营企业和联营企业的长期股权投资一律RF0=0.35"],"answer":["A","B","C"],"explanation":"第二十七至三十一条规定了前三个赋值；第二十八条规定对子公司、合营和联营企业长期股权投资基础因子为1，仅保险类子公司及保险主业范围内子公司为0.35等例外。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M06","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于优先股和无固定期限资本债券的基础因子，下列说法正确的有：","options":["银行发行的不带强制转换为普通股或减记条款的为0.15","银行发行的带强制转换条款且资本充足率未全部达标的为0.45","非金融机构发行的不带强制转换条款的优先股为0.10","保险公司发行的带有强制转换或减记条款且偿付能力充足率全部达标的为0.15"],"answer":["A","B","C","D"],"explanation":"第三十六条规定了上述赋值：不带条款0.15、未达标0.45、非金融机构不带强转0.10、带强转0.25、保险公司带条款且偿付能力达标0.15。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M07","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于境外资产价格风险，下列说法正确的有：","options":["境外固收中同业存单、短期融资券基础因子为0.03","境外上市股票基础因子为0.39","发达市场特征系数k1为0，新兴市场为0.25","境外固收发达与新兴市场间相关系数为0.375"],"answer":["A","B","C"],"explanation":"第四十六至四十八条规定：同业存单短期融资券0.03、境外上市股票0.39、发达市场k1=0新兴市场k1=0.25；第四十七条规定境外固收相关系数ρ=0.1365，0.375是境外权益的相关系数。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M08","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于汇率风险的计量，下列说法正确的有：","options":["应区分币种进行对冲汇总","风险暴露为同币种资产认可价值减去同币种负债认可价值的净额绝对值","美元和汇率跟美元挂钩的货币之间可视为同币种计算金额","欧元、英镑的基础因子为0.15"],"answer":["A","B","C"],"explanation":"第五十六至五十七条规定，汇率风险区分币种对冲汇总，风险暴露为净额绝对值，美元及挂钩货币视为同币种；欧元、英镑RF0=0.08，其他货币才为0.15。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M09","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"下列资产中不需计量交易对手集中度风险最低资本的有：","options":["政府债券","国有大型商业银行存款和发行的股票、债券等金融产品","货币市场类保险资产管理产品","投资性房地产"],"answer":["A","B","C","D"],"explanation":"第六十四条规定，政府债券、政策性银行和政府支持机构金融产品、国有大型商业银行存款和金融产品、货币市场类保险资管产品、外国再保分公司转分保资产、集团内规定可不计量的资管产品、投资性房地产均不计量交易对手集中度风险。","difficulty":2,"type":"concept","source":"core"},{"id":"08-M10","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于交易对手集中度风险阈值，下列说法正确的有：","options":["人身险公司总资产100亿元（含）以下部分阈值为8%","财产险公司总资产20亿元（含）以下部分阈值为8%","总资产5亿元以下的保险公司不计提交易对手集中度风险最低资本","超阈值时设置的特征系数k集中度1赋值为0.4"],"answer":["A","B","C","D"],"explanation":"第六十五条规定了按总资产规模超额累退的阈值表（人身险100亿以下8%、财产险20亿以下8%等），总资产5亿元以下不计提，k集中度1=0.4。","difficulty":2,"type":"concept","source":"core"},{"id":"08-X-S01","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"根据第8号规则，下列哪项不属于市场风险的类别？","options":["利率风险","集中度风险","信用风险","汇率风险"],"answer":"C","explanation":"市场风险包括利率风险、权益价格风险、房地产价格风险、境外资产价格风险、汇率风险和集中度风险六类；信用风险不在此列。","difficulty":1,"type":"concept","source":"extra"},{"id":"08-X-S02","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"根据第8号规则，人身保险公司的利率风险最低资本采用何种方法计量？","options":["综合因子法","情景法","穿透法","压力测试法"],"answer":"B","explanation":"除人身保险公司的利率风险最低资本采用情景法外，其他市场风险最低资本均采用综合因子法计量。","difficulty":1,"type":"concept","source":"extra"},{"id":"08-X-S03","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"某财产险公司持有修正久期D=8的债券，其利率风险基础因子为多少？","options":["0.1082","0.1140","0.0938","0.1760"],"answer":"A","explanation":"D=8位于（5,10]区间，RF0=D×（−0.00106×D+0.022）=8×0.01352=0.1082。","difficulty":2,"type":"calc","source":"extra"},{"id":"08-X-S04","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"某保险公司持有沪深主板上市股票，认可价值2000万元，该股票为沪深300指数成份股（k2=−0.05），则其权益价格风险最低资本为多少？","options":["665万元","700万元","900万元","630万元"],"answer":"A","explanation":"RF=0.35×（1−0.05）=0.3325，MC=2000万×0.3325=665万元；沪深主板基础因子0.35，沪深300成份股k2=−0.05。","difficulty":2,"type":"calc","source":"extra"},{"id":"08-X-S05","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"某财产险公司以物权方式持有位于境内三线城市（非直辖市、省会及计划单列市）的投资性房地产，认可价值1亿元，则其房地产价格风险最低资本为多少？","options":["1800万元","1500万元","1200万元","2100万元"],"answer":"A","explanation":"RF=0.15×（1+0.2）=0.18，MC=10000万×0.18=1800万元；境内其他地区位置特征系数k1=0.2，物权基础因子0.15。","difficulty":2,"type":"scenario","source":"extra"},{"id":"08-X-S06","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"某保险公司美元资产认可价值8000万元、美元负债3000万元，与美元挂钩的港币资产2000万元、港币负债1000万元，美元汇率基础因子为0.05，则其汇率风险最低资本为多少？","options":["300万元","250万元","400万元","550万元"],"answer":"A","explanation":"美元与挂钩货币视为同币种，风险暴露=|（8000+2000）−（3000+1000）|=6000万元，MC=6000万×0.05=300万元。","difficulty":3,"type":"scenario","source":"extra"},{"id":"08-X-S07","rule_no":8,"rule_title":"市场风险最低资本","qtype":"single","q":"某人身保险公司投资一款股权投资基金（非基础资产），其市场风险最低资本应如何计量？","options":["按第7号规则穿透计量","直接按第8号规则综合因子法计量","免于计量市场风险","按第5号规则计量"],"answer":"A","explanation":"第8号规则规范基础资产的市场风险，非基础资产（如股权投资基金）的市场风险应按第7号规则（穿透计量）计量。","difficulty":3,"type":"cross","source":"extra"},{"id":"08-X-M01","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"根据第8号规则，市场风险包括下列哪些类别？","options":["利率风险","权益价格风险","房地产价格风险","保险风险"],"answer":["A","B","C"],"explanation":"市场风险包括利率、权益价格、房地产价格、境外资产价格、汇率和集中度风险六类；保险风险是独立的偿付能力风险类别。","difficulty":1,"type":"concept","source":"extra"},{"id":"08-X-M02","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于证券投资基金（及可转债）的市场风险基础因子，下列数值正确的有？","options":["债券基金为0.06","股票基金为0.25","混合基金及商品金融衍生品基金为0.23","货币市场基金为0.01"],"answer":["A","C","D"],"explanation":"股票基金基础因子为0.28（0.25错误），债券基金0.06、混合及商品金融衍生品基金0.23、货币市场基金0.01均正确；可转债（可交换债）为0.23。","difficulty":2,"type":"calc","source":"extra"},{"id":"08-X-M03","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"某大型财产险公司投资性房地产占总资产比例达30%，且持有同一交易对手的资产超过规定阈值，关于其集中度风险，下列说法正确的有？","options":["房地产集中度风险特征系数为0.5","交易对手集中度风险特征系数为0.2","大类资产集中度风险特征系数为0.2","投资性房地产占总资产比例超过25%的触发房地产集中度风险计量"],"answer":["A","C","D"],"explanation":"交易对手集中度k=0.4（0.2错误）；大类资产集中度k=0.2、房地产集中度k=0.5，且投资性房地产占总资产比例超过25%触发房地产集中度。","difficulty":3,"type":"scenario","source":"extra"},{"id":"08-X-M04","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于市场风险最低资本的计量要求，下列说法正确的有？","options":["应对类别内各项资产（负债）分别计量，不得按类别合并计量","套期保值须符合套期有效性要求且套期期限不低于1个月，方可将衍生品空头与被套期组合合并计算","套期期限不低于3个月方可合并计算","表外业务的市场风险计量标准由银保监会另行规定"],"answer":["A","B","D"],"explanation":"套期有效性要求对应的套期期限门槛为1个月（不是3个月）；A、B、D均为第8号规则的明确规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"08-X-M05","rule_no":8,"rule_title":"市场风险最低资本","qtype":"multi","q":"关于利率风险最低资本的计量，下列说法正确的有？","options":["财产保险公司采用综合因子法计量","人身保险公司采用情景法计量","同时经营财产险和人身险的再保险公司，对非寿险、寿险业务分别计量后算术加总","人身险公司利率风险的资产范围不包括保单质押贷款"],"answer":["A","B","C"],"explanation":"人身险公司利率风险的资产范围包括存款、债券、其他固定收益类资产、利率衍生品和保单质押贷款，D错误；A、B、C均正确。","difficulty":2,"type":"concept","source":"extra"},{"id":"09-S01","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"根据第9号规则，保险公司信用风险包括以下哪几类风险？","options":["利差风险、交易对手违约风险和集中度风险","利率风险、汇率风险和集中度风险","利差风险、市场风险和流动性风险","违约风险、操作风险和声誉风险"],"answer":"A","explanation":"第三条规定，保险公司信用风险包括利差风险、交易对手违约风险和集中度风险。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S02","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"信用风险最低资本基本公式MC信用=EX×RF中，风险因子RF的计算方法为：","options":["RF=RF0×(1+K)，RF≥1时取值为1","RF=RF0+K，RF≥1时取值为1","RF=RF0×(1+K)，无上限限制","RF=RF0÷(1+K)，RF≥1时取值为1"],"answer":"A","explanation":"第六条规定RF=RF0×(1+K)，当RF≥1时取值为1。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S03","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"特征系数K的取值范围是：","options":["K∈[-0.25, 0.25]","K∈[-0.5, 0.5]","K∈[0, 0.25]","K∈[-0.25, 0]"],"answer":"A","explanation":"第六条规定K=k1+k2+k3+……+kn，K∈[-0.25,0.25]，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S04","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"关于资产的信用评级，下列说法正确的是：","options":["有项目评级的资产应采用项目评级，无项目评级的资产应采用交易对手评级","一律采用交易对手评级","一律采用项目评级","由保险公司自行选择采用项目评级或交易对手评级"],"answer":"A","explanation":"第五条规定，资产的信用评级指项目评级和交易对手评级，有项目评级用项目评级，无项目评级用交易对手评级。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S05","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司计量某类资产（负债）的信用风险最低资本时，正确做法是：","options":["对该类别的各项资产（负债）分别计量，不得按类别合并计量","按类别合并计量以简化计算","同类资产可以合并计量，不同类资产分别计量","由保险公司根据重要性原则自行选择计量方式"],"answer":"A","explanation":"第七条规定，应对该类别的各项资产（负债）分别计量，不得按类别合并计量。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S06","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司持有的政府债券和央行票据，其信用风险最低资本的处理方式是：","options":["不计量信用风险最低资本","适用零风险因子计量","按最低档基础因子计量","按公允价值的0.5%计量"],"answer":"A","explanation":"第十条规定，政府债券和央行票据不计量信用风险最低资本，银保监会另有规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S07","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"政策性银行发行的金融债券，资产修正久期D＞5年时，利差风险基础因子RF0为：","options":["D×0.001+0.025","D×0.001+0.03","D×(−0.0012×D＋0.012)","D×0.015"],"answer":"A","explanation":"第十三条规定，政策性银行金融债券D＞5时RF0=D×0.001+0.025。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S08","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"属于支持碳减排项目绿色债券的境内标准化债权类资产，其调控性特征系数k1的赋值为：","options":["−0.1","−0.15","−0.25","0.1"],"answer":"A","explanation":"第十六条规定，支持碳减排项目绿色债券的调控性特征系数k1赋值为−0.1。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S09","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司存放在第三方支付机构账户的资金，交易对手违约风险基础因子RF0为：","options":["0.05","0.03","0","0.1"],"answer":"A","explanation":"第二十条规定，现金RF0=0，拆出资金0.03，存放在第三方支付机构账户的资金0.05。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S10","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司存放在国有大型商业银行的定期存款，交易对手违约风险基础因子RF0为：","options":["0.005","0.01","0.03","0.04"],"answer":"A","explanation":"第二十一条规定，国有大型商业银行、政策性银行的定期存款、协议存款、大额存单RF0为0.005。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S11","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司持有的非保本结构性存款，交易对手违约风险基础因子RF0为：","options":["0.5","0.1","0.23","0.055"],"answer":"A","explanation":"第二十一条规定，非保本结构性存款（各类银行）RF0为0.5。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S12","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"财产保险公司和人身保险公司再保分出业务中，境内再保险分入人综合偿付能力充足率达到200%或以上的，应收分保款项基础因子RF0为：","options":["0.008","0.013","0.047","0.261"],"answer":"A","explanation":"第二十二条规定，境内再保险分入人综合偿付能力充足率200%或以上RF0为0.008。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S13","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"财产保险公司和人身保险公司再保分出业务中，境外再保险分入人偿付能力达标但无担保措施的部分，基础因子RF0为：","options":["0.499","0.077","0.867","0.3"],"answer":"A","explanation":"第二十二条规定，境外再保险分入人各级偿付能力充足率全部达到监管要求时，有担保措施部分0.077，无担保措施部分0.499。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S14","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保单质押贷款的交易对手违约风险基础因子RF0为：","options":["0.05","0.03","0.08","0"],"answer":"A","explanation":"第三十二条规定，保单质押贷款的交易对手违约风险RF0赋值为0.05。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S15","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"分入业务再保险资产的交易对手违约风险，账龄在（6个月，12个月]区间的，基础因子RF0为：","options":["0.7","0","0.5","1"],"answer":"A","explanation":"第三十条规定，账龄不大于6个月RF0=0，（6个月，12个月]为0.7，12个月以上为1。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S16","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司应收保费（非政府补贴类其他业务）账龄在（6个月，12个月]区间的，交易对手违约风险基础因子RF0为：","options":["0.5","0.2","0.7","0"],"answer":"A","explanation":"第三十四条规定，其他业务账龄不大于6个月RF0=0，（6个月，12个月]为0.5，12个月以上为1。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S17","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司对外提供债务担保，交易对手违约风险的风险暴露EX和基础因子RF0分别为：","options":["担保金额；0.3","担保金额；0.5","账面价值；0.3","认可价值；0.45"],"answer":"A","explanation":"第三十八条规定，债务担保风险暴露EX为担保金额，RF0赋值为0.3。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S18","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"非基础资产穿透后底层资产为贷款资产，风险分类等级为次级类的，基础因子RF0为：","options":["0.3","0.135","0.5","0.085"],"answer":"A","explanation":"第三十七条规定，贷款资产正常类0.085、关注类0.135、次级类0.3、可疑类0.5、损失类1。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S19","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"信用风险最低资本汇总公式中，MC利差与MC交易对手违约之间的相关系数ρ为：","options":["0.25","0.5","0.15","0.45"],"answer":"A","explanation":"第四十三条规定，汇总公式中ρ=0.25。","difficulty":2,"type":"concept","source":"core"},{"id":"09-S20","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"保险公司无法获取境外再保险分入人最近一年内信用评级的，最低资本计算方式为：","options":["按照CCC+以下信用评级对应的RF0计算","按照BBB级对应的RF0计算","基础因子取0.5","暂不计提交易对手违约风险最低资本"],"answer":"A","explanation":"第二十九条规定，无法获取境外再保险分入人最近一年内信用评级的，按CCC+以下信用评级对应的RF0计算。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M01","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"根据第9号规则总则，保险公司信用风险包括以下哪些风险？","options":["利差风险","交易对手违约风险","集中度风险","市场风险"],"answer":["A","B","C"],"explanation":"第三条规定信用风险包括利差风险、交易对手违约风险和集中度风险，市场风险属于另一类量化风险。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M02","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"保险公司持有的下列资产中，应按第9号规则计量交易对手违约风险最低资本的有哪些？","options":["再保险资产（应收分保准备金、应收分保款项）","保单质押贷款","应收保费","央行票据"],"answer":["A","B","C"],"explanation":"第十九条规定前三项均需计量交易对手违约风险；第十条规定央行票据不计信用风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M03","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"关于保险公司使用外部信用评级，下列说法正确的有：","options":["境内信用评级原则上按境内评级机构的评级结果确定","境外信用评级原则上按国际公认评级机构的评级结果确定","多家符合条件的评级机构给予评级的，从低适用","编报偿付能力报告时应采用最近一期符合要求的评级结果"],"answer":["A","B","C","D"],"explanation":"第五条对信用评级使用作出上述四项规定，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M04","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"保险公司直接持有的下列境内标准化债权类资产中，应计量利差风险最低资本的有哪些？","options":["政府支持机构债券","同业存单","信贷资产支持证券","可转债（可交换债）"],"answer":["A","B","C"],"explanation":"第十二条规定利差风险计量范围包括前三项，但明确不含可转债（可交换债）。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M05","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"关于利差风险计量中修正久期D的确定，下列说法正确的有：","options":["修正久期的计算可参照中央国债登记结算有限责任公司公布的方法","对于浮息债，D为利率久期","存续期内有赎回安排的，D按照到期日为下一赎回日计算","存续期内没有赎回安排的，D按照永续期限计算"],"answer":["A","B","C","D"],"explanation":"第十六条对修正久期的确定作出上述四项规定，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M06","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"农业保险、与各级政府合作的城乡居民大病保险等享受各级政府保费补贴的业务，其应收保费交易对手违约风险基础因子RF0的赋值正确的有：","options":["账龄不大于9个月，RF0=0","账龄在（9个月，12个月]，RF0=0.2","账龄在（12个月，18个月]，RF0=0.7","账龄18个月以上，RF0=1"],"answer":["A","B","C","D"],"explanation":"第三十四条规定政府补贴业务四个账龄区间的RF0分别为0、0.2、0.7、1，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M07","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"境内再保险分入人综合偿付能力充足率与应收分保款项基础因子RF0的对应关系，正确的有：","options":["充足率200%或以上，RF0=0.008","充足率在[150%,200%)，RF0=0.013","充足率在[100%,150%)，RF0=0.047","充足率在[50%,100%)，RF0=0.261"],"answer":["A","B","C","D"],"explanation":"第二十二条对境内再保险分入人按综合偿付能力充足率分档赋值，四项对应关系均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M08","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"再保险公司再保分出业务中，根据再保险分入人风险特征设定的特征系数，正确的有：","options":["有担保措施部分k1=−0.25","再保险分入人为直保公司的k2=0.1","境内非独立法人机构k3=0.05","采取透明度增强措施的境外分入人k4=−0.15"],"answer":["A","B","C","D"],"explanation":"第二十三条至第二十五条规定：k1有担保−0.25、k2直保公司0.1、k3境内非独立法人0.05、k4透明度增强措施−0.15，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M09","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"关于信用风险缓释工具或信用保护工具的使用，下列说法正确的有：","options":["标的资产及缓释（保护）工具的最低资本应合并计算","应以缓释工具创设机构主体信用评级与标的资产信用评级孰高的原则确定调整后评级","缓释（保护）工具的风险暴露为其账面价值","使用缓释工具后一律免于计量信用风险最低资本"],"answer":["A","B","C"],"explanation":"第八条规定合并计算、评级孰高确定RF调整后、缓释工具风险暴露为账面价值；D项错误，使用缓释工具仍需计量。","difficulty":2,"type":"concept","source":"core"},{"id":"09-M10","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"下列资产或款项中，交易对手违约风险基础因子RF0为0的有哪些？","options":["现金","预付赔款、待抵扣的预交税费","账龄不大于6个月的分入业务再保险资产","拆出资金"],"answer":["A","B","C"],"explanation":"第二十条现金RF0=0；第三十六条预付赔款等RF0=0；第三十条账龄不大于6个月的分入业务RF0=0；拆出资金RF0为0.03，D错误。","difficulty":2,"type":"concept","source":"core"},{"id":"09-X-S01","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某基础资产信用风险暴露EX为1000万元，基础因子RF0为0.5，特征系数K为0.2，根据第9号规则，其风险因子RF为多少？","options":["0.5","0.6","0.7","1"],"answer":"B","explanation":"RF=RF0×(1+K)=0.5×1.2=0.6，小于1故直接取0.6；只有RF≥1时才取值为1。依据第9号规则第一章信用风险最低资本基本公式。","difficulty":1,"type":"calc","source":"extra"},{"id":"09-X-S02","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某保险公司持有的政策性银行金融债修正久期D为4，其利差风险基础因子RF0为多少？","options":["0.0192","0.024","0.0288","0.029"],"answer":"C","explanation":"政策性银行金融债在0＜D≤5时RF0=D×(−0.0012×D＋0.012)=4×(−0.0048+0.012)=4×0.0072=0.0288。依据第9号规则第二章利差风险因子规定。","difficulty":2,"type":"calc","source":"extra"},{"id":"09-X-S03","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某保险公司利差风险最低资本为8亿元，交易对手违约风险最低资本为6亿元，两者相关系数ρ=0.25，则信用风险最低资本合计约为多少？","options":["10.00亿元","11.14亿元","12.00亿元","14.00亿元"],"answer":"B","explanation":"MC信用=√(8²+2×0.25×8×6+6²)=√(64+24+36)=√124≈11.14亿元，不能简单相加。依据第9号规则第五章汇总公式。","difficulty":2,"type":"calc","source":"extra"},{"id":"09-X-S04","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"根据第9号规则，下列资产中不计量信用风险最低资本的是？","options":["政策性银行金融债","央行票据","保单质押贷款","拆出资金"],"answer":"B","explanation":"政府债券和央行票据不计量信用风险最低资本（银保监会另有规定的除外）。依据第9号规则监管要求条款。","difficulty":1,"type":"concept","source":"extra"},{"id":"09-X-S05","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某债券同时获得两家境内评级机构AA级和A+级的评级结果，计量信用风险最低资本时应如何采用评级？","options":["采用AA级","采用A+级（从低适用）","按孰高原则确定","取两家评级平均值"],"answer":"B","explanation":"同一家机构对同一资产给出多家评级机构结果的，应从低适用评级结果。依据第9号规则第一章外部评级使用规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"09-X-S06","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某保险公司持有主体评级为AA的企业债券，并通过信用风险缓释工具缓释其信用风险，缓释工具创设机构的主体评级为A。根据第9号规则，计算调整后风险暴露的风险因子时应采用的评级为？","options":["A级（按创设机构评级）","AA级（按标的资产评级与创设机构评级孰高确定）","A+级（取两者平均）","由公司自行选择其一"],"answer":"B","explanation":"使用缓释或保护工具合并计算时，调整后评级按缓释工具创设机构主体评级与标的资产评级的孰高原则确定，即AA级。依据第9号规则第一章缓释工具处理规定。","difficulty":3,"type":"scenario","source":"extra"},{"id":"09-X-S07","rule_no":9,"rule_title":"信用风险最低资本","qtype":"single","q":"某保险公司将业务分出给一家境内再保险分入人，该分入人最近一年度综合偿付能力充足率为180%，无特征系数调整，风险暴露为5000万元。该再保险资产的交易对手违约风险最低资本为多少？","options":["25万元","40万元","65万元","235万元"],"answer":"C","explanation":"境内再保险分入人综合偿付能力充足率处于[150%,200%)区间，RF0=0.013，MC=5000万×0.013=65万元。依据第9号规则第三章境内再保险资产基础因子规定。","difficulty":3,"type":"scenario","source":"extra"},{"id":"09-X-M01","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"根据第9号规则，信用风险的成因包括下列哪些情形？","options":["市场利率的不利变动","利差的不利变动","交易对手不能履行或不能按时履行合同义务","交易对手信用状况的不利变动"],"answer":["B","C","D"],"explanation":"信用风险是由于利差的不利变动、交易对手不能履行或不能按时履行合同义务、或交易对手信用状况不利变动导致非预期损失的风险；市场利率变动属于市场风险范畴。依据第9号规则第一章信用风险定义。","difficulty":1,"type":"concept","source":"extra"},{"id":"09-X-M02","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"根据第9号规则，下列资产中基础因子RF0为0的包括哪些？","options":["现金","拆出资金","预付赔款","待抵扣预交税费"],"answer":["A","C","D"],"explanation":"现金、预付赔款、待抵扣预交税费的RF0均为0；拆出资金RF0为0.03。依据第9号规则第三章交易对手违约风险基础因子规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"09-X-M03","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"某再保险公司计量再保险分出业务的信用风险最低资本，关于其特征系数的设置，下列正确的有？","options":["有担保措施的部分k1为−0.25","直保公司作为交易对手时k2为0.1","境内非独立法人交易对手k3为−0.05","采用透明度增强措施k4为−0.15"],"answer":["A","B","D"],"explanation":"再保险分出业务特征系数：k1有担保−0.25、k2直保公司0.1、k3境内非独立法人0.05（而非−0.05）、k4透明度增强措施−0.15。依据第9号规则第三章易考细节。","difficulty":2,"type":"scenario","source":"extra"},{"id":"09-X-M04","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"关于浮动利率债券利差风险计量中久期D的确定，下列说法正确的有？","options":["浮息债利差风险中D为利率久期","有赎回安排的按下一赎回日计算","无赎回安排的按永续期限计算","浮息债不计量利差风险"],"answer":["A","B","C"],"explanation":"对浮息债，利差风险中D为利率久期；有赎回安排的按下一赎回日计算，无赎回安排的按永续期限计算；浮息债仍需计量利差风险。依据第9号规则第二章利差风险规定。","difficulty":2,"type":"concept","source":"extra"},{"id":"09-X-M05","rule_no":9,"rule_title":"信用风险最低资本","qtype":"multi","q":"某保险公司计量信用风险最低资本时涉及多项规则衔接，下列说法正确的有？","options":["集中度风险按第8号规则第七章计量","非基础资产信用风险按第7号规则（穿透计量）计量","利差风险与交易对手违约风险最低资本按相关系数0.25汇总","政府债券应计量交易对手违约风险最低资本"],"answer":["A","B","C"],"explanation":"集中度风险按第8号规则第七章计量；非基础资产按第7号规则穿透计量；利差风险与交易对手违约风险按ρ=0.25汇总；政府债券和央行票据不计量信用风险最低资本。依据第9号规则第一、四、五章。","difficulty":3,"type":"cross","source":"extra"},{"id":"10-S01","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"根据第10号规则，保险公司压力测试分为哪三类？","options":["情景法测试、敏感性测试和反向压力测试","基本情景测试、压力情景测试和极端情景测试","定性测试、定量测试和综合测试","季度测试、年度测试和专项测试"],"answer":"A","explanation":"第四条规定，压力测试分为情景法测试、敏感性测试和反向压力测试三类。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S02","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"评估多种风险因素同时联动变化情景下对公司偿付能力充足率影响的测试类型是：","options":["情景法测试","敏感性测试","反向压力测试","动态测试"],"answer":"A","explanation":"第四条规定，情景法测试评估多种风险因素同时联动变化情景下对偿付能力充足率的影响。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S03","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"季度压力测试的类型是：","options":["动态单因素敏感性测试","情景法测试","反向压力测试","情景法测试与反向压力测试"],"answer":"A","explanation":"第七条规定季度压力测试为敏感性测试，第九条明确其为动态单因素敏感性测试。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S04","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"年度压力测试包括的测试类型是：","options":["情景法测试、敏感性测试和反向压力测试","仅情景法测试","仅敏感性测试","情景法测试和反向压力测试"],"answer":"A","explanation":"第七条规定，年度压力测试包括情景法测试、敏感性测试和反向压力测试。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S05","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"季度压力测试中的必测风险因素由谁确定发布？","options":["银保监会统一确定发布","保险公司自行确定","行业协会统一确定","各保险公司董事会确定"],"answer":"A","explanation":"第十条规定，必测风险因素由银保监会综合考虑宏观经济金融形势、行业风险状况、监管要求等统一确定发布。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S06","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"基本情景下，保险公司应预测报告年度后多长期限的偿付能力指标？","options":["未来两个会计年度末","未来一个会计年度末","未来三个会计年度末","下一个季度末"],"answer":"A","explanation":"第十四条规定，基本情景下应预测报告年度后未来两个会计年度末的偿付能力指标。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S07","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"压力情景下，保险公司应测试的偿付能力指标期间为：","options":["未来一个会计年度末","未来两个会计年度末","未来三个会计年度末","下一季度末"],"answer":"A","explanation":"第二十三条规定，压力情景下应测试未来一个会计年度末的偿付能力指标。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S08","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"保险公司设置自测压力情景时，应选择的风险因素数量至少为：","options":["两个重大风险因素","一个重大风险因素","三个重大风险因素","不限定数量"],"answer":"A","explanation":"第二十五条规定，设置自测压力情景应选择至少两个重大风险因素。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S09","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"开展反向压力测试的适用条件是：","options":["基本情景下报告年度后未来一个会计年度末综合偿付能力充足率处于100%～150%之间","综合偿付能力充足率低于100%","核心偿付能力充足率低于50%","所有保险公司均须开展"],"answer":"A","explanation":"第三十条规定，基本情景下未来一个会计年度末综合偿付能力充足率处于100%～150%之间的保险公司应开展反向压力测试。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S10","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"反向压力测试中，假设公司下一个会计年度末综合偿付能力充足率降低至什么水平时计算最主要风险因素的变化水平？","options":["100%","150%","50%","120%"],"answer":"A","explanation":"第三十一条规定，假设综合偿付能力充足率降低至100%的水平时计算该风险因素的变化水平。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S11","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"保险公司应每年评估和校验的对象是：","options":["压力测试模型、预测方法和关键假设","仅压力测试模型","仅关键假设","偿付能力充足率计算结果"],"answer":"A","explanation":"第三十四条规定，应每年评估和校验压力测试模型、预测方法和关键假设。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S12","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"保险公司向银保监会报送年度压力测试报告的截止时间为：","options":["每年5月31日前","每年4月30日前","每年6月30日前","每年12月31日前"],"answer":"A","explanation":"第三十六条规定，保险公司应在每年5月31日前向银保监会报送年度压力测试报告。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S13","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"年度压力测试报告的批准和最终责任安排是：","options":["经董事会批准，董事会对压力测试的合规性和合理性承担最终责任","经总经理批准，总经理承担最终责任","经总精算师批准，总精算师承担最终责任","经股东大会批准，股东大会承担最终责任"],"answer":"A","explanation":"第三十七条规定，年度压力测试报告应经董事会批准，董事会对压力测试的合规性和合理性承担最终责任。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S14","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"关于独立第三方机构审核年度压力测试报告，下列说法正确的是：","options":["独立第三方机构包括符合要求的会计师事务所、精算咨询顾问公司等，除会计师事务所外其他机构应报银保监会备案","仅会计师事务所可以从事审核业务","所有审核机构均须报银保监会备案","审核机构由银保监会指定"],"answer":"A","explanation":"第三十八条规定，独立第三方机构指符合独立性要求和具备专业胜任能力的会计师事务所、精算咨询顾问公司等，除会计师事务所外其他机构从事审核业务应报银保监会备案。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S15","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"基本情景下，季度或年度压力测试中综合偿付能力充足率低于多少时，保险公司应详细说明拟采取的管理措施及实施计划并提供实施后的预测值？","options":["100%","120%","150%","50%"],"answer":"A","explanation":"第三十九条规定，综合偿付能力充足率低于100%或核心偿付能力充足率低于50%的，应详细说明管理措施及实施计划并提供预测值。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S16","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"基本情景下的预测对资本补充事项的处理，正确的是：","options":["反映银保监会已批准（认可）的增资和资本补充工具发行，不考虑未获批准（认可）的资本补充行为","反映所有计划中的资本补充行为","仅反映已完成的增资，不考虑资本补充工具","不考虑任何资本补充行为"],"answer":"A","explanation":"第十六条规定，预测应反映已批准（认可）的资本补充事项，不应考虑测试期间内未获批准（认可）的资本补充行为。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S17","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"基本情景下的预测对股利分配计划的处理，正确的是：","options":["应反映公司的股利分配计划，即使股利分配计划尚未得到批准","仅反映已获批准的股利分配计划","不考虑任何股利分配计划","按上年实际分配金额的一半反映"],"answer":"A","explanation":"第十七条规定，基本情景下的预测应反映公司的股利分配计划，即使尚未得到批准。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S18","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"采用与评估日相同的原则和方法计量最低资本时，对特征因子的简化处理原则是：","options":["报告期特征因子大于0的，假设预测期维持不变；小于等于0的，假设预测期为0","一律假设预测期特征因子为0","一律假设预测期特征因子维持不变","取报告期特征因子的绝对值"],"answer":"A","explanation":"附件1、附件2均规定：报告期特征因子大于0的假设预测期维持不变，小于等于0的假设预测期为0。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S19","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"人身保险公司可以采用风险载体因子法简化计算寿险业务某子类风险保险风险最低资本的条件是：","options":["该风险在评估时点占风险分散效应前寿险业务保险风险最低资本的比例不大于15%","该风险在评估时点占风险分散效应前寿险业务保险风险最低资本的比例大于15%","该风险占比不大于10%","该风险占比不大于20%"],"answer":"A","explanation":"附件2规定，若某二级或三级风险占风险分散效应前寿险业务保险风险最低资本的比例不大于15%，可以采用风险载体因子法简化计算。","difficulty":2,"type":"concept","source":"core"},{"id":"10-S20","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"除会计师事务所外的其他独立第三方机构出具压力测试审核报告，签名盖章人员的资格要求是：","options":["两名在中国从事保险精算及相关工作3年以上、熟悉中国保险监管法规并具有精算师资格的精算师","两名注册会计师","一名精算师和一名注册会计师","两名从事保险工作5年以上的专业人员"],"answer":"A","explanation":"附件3规定，其他独立第三方机构的审核报告应由两名在中国从事保险精算及相关工作3年以上、熟悉中国保险监管法规并具有精算师资格的精算师签名并盖章。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M01","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于三类压力测试的含义，下列说法正确的有：","options":["情景法测试评估多种风险因素同时联动变化情景下对偿付能力充足率的影响","敏感性测试评估某一特定风险因素的变动对偿付能力充足率的影响","反向压力测试针对特定风险因素，反向评估偿付能力充足率不达标时该风险因素的不利变动幅度","敏感性测试评估多种风险因素同时联动变化的影响"],"answer":["A","B","C"],"explanation":"第四条规定前三项正确；敏感性测试针对单一风险因素，D错误。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M02","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"压力测试对象应涵盖的保险公司业务范围包括：","options":["有效业务","测试期间内的新业务","保险业务","非保险业务"],"answer":["A","B","C","D"],"explanation":"第六条及附件规定，测试对象应涵盖全部业务，包括有效业务和新业务，保险业务与非保险业务。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M03","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"年度压力测试报告的内容包括但不限于以下哪些事项？","options":["基本情景预测，包括基本情景假设、预测结果等","情景法测试，包括压力情景及测试结果等","敏感性测试，包括风险因素及测试结果等","公司拟采取的风险管理措施和实施计划"],"answer":["A","B","C","D"],"explanation":"第三十六条规定年度压力测试报告包括基本情景预测、情景法测试、敏感性测试、反向压力测试、主要预测方法、拟采取的风险管理措施和实施计划等，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M04","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"下列关于保险公司应报送或列报压力测试信息的说法，正确的有：","options":["应在季度偿付能力报告中列报季度压力测试结果及相关信息","应在每年5月31日前向银保监会报送年度压力测试报告","年度压力测试报告应经董事会批准","年度压力测试报告须经独立第三方机构审核"],"answer":["A","B","C","D"],"explanation":"第三十五条至第三十八条对季度报告列报、5月31日前报送、董事会批准和第三方审核均作了规定。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M05","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"基本情景下，下列哪些情形出现时保险公司应在报告中详细说明拟采取的管理措施及实施计划并提供预测值？","options":["下一季度末综合偿付能力充足率低于100%","下一季度末核心偿付能力充足率低于50%","年度压力测试中任一会计年度末综合偿付能力充足率低于100%","年度压力测试中任一会计年度末核心偿付能力充足率低于50%"],"answer":["A","B","C","D"],"explanation":"第三十九条规定，季度或年度测试中出现综合偿付能力充足率低于100%或核心偿付能力充足率低于50%的，均应详细说明管理措施及实施计划并提供预测值。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M06","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"基本情景下的预测假设应符合的要求，正确的有：","options":["新业务假设应与经董事会或管理层批准的公司业务规划一致","费用假设应与经董事会或管理层批准的公司业务规划和财务预算一致","投资假设应与经董事会或管理层批准的公司战略资产配置规划保持一致","再保险假设应符合公司再保险管理策略"],"answer":["A","B","C","D"],"explanation":"第十九条规定了新业务、费用、再保险、投资等假设的一致性要求，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M07","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于人身保险公司测试对象的分类，下列说法正确的有：","options":["销售渠道至少划分为个险、银邮、团体、网销及其他共5类","产品类型至少划分为1999年（含）之前签发的高利率产品和非高利率产品","非高利率产品进一步划分为长期传统保险产品、长期分红保险产品、万能保险产品等共10种类型","测试对象分类依据《保险公司偿付能力监管规则第3号：寿险合同负债评估》规定的业务类别"],"answer":["A","B","C","D"],"explanation":"附件2规定，人身保险公司按销售渠道（至少5类）和第3号规则业务类别对测试对象分类，产品类型划分包括高利率产品和非高利率产品（10种类型）。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M08","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"独立第三方机构对保险公司压力测试的审核范围包括以下哪些事项？","options":["实际资本、最低资本和偿付能力充足率的预测方法和程序的合规性、合理性","涵盖业务的全面性与业务类别分类的合规性、合理性","必测压力情景（因素）与监管规定的一致性，以及自测压力情景（因素）的合理性与充分性","年度压力测试报告中披露的有关信息的真实性、合规性和完整性"],"answer":["A","B","C","D"],"explanation":"附件3第三部分规定了审核范围共九项，上述四项均在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M09","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"独立第三方审核机构应对下列哪些事项发表审核意见？","options":["预测假设是否为压力测试提供合理基础","年度压力测试报告是否依据这些预测假设编制和列报","年度压力测试报告是否按照适用的偿付能力监管规则的规定编制和列报","公司偿付能力充足率是否达标"],"answer":["A","B","C"],"explanation":"附件3第四部分规定审核意见针对预测假设是否提供合理基础、报告是否依据假设并按监管规则编制列报两项；充足率是否达标不属于审核意见事项。","difficulty":2,"type":"concept","source":"core"},{"id":"10-M10","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于再保险公司、自保公司和相互保险组织适用本规则，下列说法正确的有：","options":["再保险公司应参照本规则原则自主设计和开展压力测试","自保公司应向银保监会报送年度压力测试报告","再保险公司应在季度偿付能力报告中披露压力测试相关信息","相互保险组织直接适用本规则"],"answer":["A","B","C","D"],"explanation":"第四十三条规定再保险公司、自保公司参照执行并报送报告、披露信息；第四十四条规定相互保险组织适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"10-X-S01","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"根据第10号规则，保险公司年度压力测试报告应于什么时间前报送银保监会？","options":["每年4月30日前","每年5月31日前","每年6月30日前","次年1月31日前"],"answer":"B","explanation":"年度压力测试报告应于每年5月31日前报送银保监会。依据第10号规则第四章报告报送要求。","difficulty":1,"type":"concept","source":"extra"},{"id":"10-X-S02","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"根据第10号规则，季度压力测试属于下列哪类测试？","options":["情景法测试","动态单因素敏感性测试","反向压力测试","三类测试均包括"],"answer":"B","explanation":"季度压力测试为动态单因素敏感性测试，评估下一季度末各项偿付能力指标变化；年度压力测试才包括全部三类。依据第10号规则第二章。","difficulty":1,"type":"concept","source":"extra"},{"id":"10-X-S03","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"某资产报告期风险因子RF0为0.15，特征系数K为−0.2。根据第10号规则特征因子简化原则，预测期该资产的风险因子RF为多少？","options":["0.15","0.12","0.18","0.03"],"answer":"A","explanation":"特征因子简化原则：报告期特征系数大于0的假设预测期维持不变，小于等于0的假设预测期为0。K=−0.2≤0，预测期K按0处理，故RF=0.15×(1+0)=0.15。依据第10号规则第三章。","difficulty":2,"type":"calc","source":"extra"},{"id":"10-X-S04","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"根据第10号规则，修正久期区间划分中，某资产的修正久期为4年，应归入哪个区间？","options":["1及以下","1-3","3-5","5-7"],"answer":"C","explanation":"修正久期区间至少包括1及以下、1-3、3-5、5-7、7-10、10-15、15以上，久期4年属于3-5区间。依据第10号规则附件实施指引。","difficulty":2,"type":"calc","source":"extra"},{"id":"10-X-S05","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"某保险公司在编制年度压力测试基本情景预测时，关于资本事项的下列处理，正确的是？","options":["只反映已获批准（认可）的增资和资本补充事项，不反映未获批准的资本补充行为，但股利分配计划即使尚未获批准也应反映","反映所有拟议中的资本补充行为","不考虑任何股利分配计划","股利分配计划未获批准的不予反映"],"answer":"A","explanation":"基本情景预测应反映银保监会已批准（认可）的增资和资本补充事项，不应考虑未获批准（认可）的资本补充行为；应反映股利分配计划，即使尚未获批准。依据第10号规则第三章基本情景预测要求。","difficulty":2,"type":"scenario","source":"extra"},{"id":"10-X-S06","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"某公司开展反向压力测试，基本情景下报告年度后未来一个会计年度末综合偿付能力充足率为140%。根据第10号规则，测试应假设下一会计年度末综合偿付能力充足率降至100%的水平，则需测算最主要风险因素导致充足率下降的幅度为？","options":["30个百分点","40个百分点","50个百分点","60个百分点"],"answer":"B","explanation":"反向压力测试假设下一会计年度末综合偿付能力充足率降低至100%，即需测算最主要风险因素导致充足率下降140%−100%=40个百分点的变化水平。依据第10号规则第三章反向压力测试规定。","difficulty":3,"type":"calc","source":"extra"},{"id":"10-X-S07","rule_no":10,"rule_title":"压力测试","qtype":"single","q":"某财产保险公司开展年度压力测试，关于其测试对象的业务类别划分，正确做法是？","options":["按第4号规则非寿险业务类别划分为十个类别","按人身险产品类型划分为10种以上","按个险、银邮、团体、网销及其他5类渠道划分","由公司根据管理习惯自行任意划分"],"answer":"A","explanation":"财产保险公司测试对象按第4号规则（非寿险业务）业务类别分为十个类别；渠道和产品类型的划分要求适用于人身保险公司。依据第10号规则附件1及易考细节。","difficulty":3,"type":"cross","source":"extra"},{"id":"10-X-M01","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"根据第10号规则，年度压力测试包括下列哪些测试类型？","options":["情景法测试","敏感性测试","反向压力测试","仅包括动态单因素敏感性测试"],"answer":["A","B","C"],"explanation":"年度压力测试包括情景法测试、敏感性测试和反向压力测试三类；动态单因素敏感性测试是季度压力测试的内容。依据第10号规则第三章。","difficulty":1,"type":"concept","source":"extra"},{"id":"10-X-M02","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于压力测试对象和风险因素的选取，下列说法正确的有？","options":["测试对象应涵盖保险公司全部业务","保险业务包括报告期末的有效业务和测试期间内的新业务","必测风险因素和必测压力情景由公司自行确定","自选风险因素由公司基于自身风险状况选取"],"answer":["A","B","D"],"explanation":"必测风险因素和必测压力情景由银保监会统一确定发布并适时调整，而非公司自行确定；自选风险因素由公司基于自身风险状况选取。依据第10号规则第一、三章。","difficulty":2,"type":"concept","source":"extra"},{"id":"10-X-M03","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"某公司在年度压力测试基本情景下，预测未来第二年末综合偿付能力充足率为95%、核心偿付能力充足率为48%。根据第10号规则，下列做法正确的有？","options":["应详细说明拟采取的管理措施","应提供管理措施实施后的偿付能力预测值","仅需在报表附注中作风险提示即可","年度压力测试报告应经董事会批准"],"answer":["A","B","D"],"explanation":"基本情景下任一期末综合偿付能力充足率低于100%或核心偿付能力充足率低于50%的，应详细说明管理措施并提供实施后的预测值；年度压力测试报告均须经董事会批准。依据第10号规则第三、四章。","difficulty":2,"type":"scenario","source":"extra"},{"id":"10-X-M04","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于年度压力测试报告的审批与审核要求，下列说法正确的有？","options":["年度压力测试报告应经董事会批准","董事会对压力测试的合规性和合理性承担最终责任","承担审核业务的独立第三方机构只能是会计师事务所","除会计师事务所外，其他机构从事审核业务应报银保监会备案"],"answer":["A","B","D"],"explanation":"报告须经独立第三方机构（会计师事务所、精算咨询顾问公司等）审核，并非只能是会计师事务所；除会计师事务所外的其他机构从事审核业务应报银保监会备案。依据第10号规则第四章。","difficulty":3,"type":"concept","source":"extra"},{"id":"10-X-M05","rule_no":10,"rule_title":"压力测试","qtype":"multi","q":"关于不同类型保险公司压力测试对象的划分，下列说法正确的有？","options":["人身保险公司测试对象销售渠道至少划分为个险、银邮、团体、网销及其他共5类","财产保险公司测试对象按第4号规则业务类别分为十个类别","季度压力测试属于情景法测试","会计利润预测中的投资收益率假设包括可供出售金融资产公允价值变动"],"answer":["A","B"],"explanation":"人身险公司渠道至少划分5类、财险公司按第4号规则分十个类别均正确；季度压力测试为动态单因素敏感性测试而非情景法测试；投资收益率假设不包括可供出售金融资产公允价值变动。依据第10号规则第二、三章及附件。","difficulty":2,"type":"cross","source":"extra"},{"id":"11-S01","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据第11号规则，保险公司偿付能力风险由哪两类风险组成？","options":["固有风险和控制风险","可资本化风险和难以资本化风险","保险风险和市场风险","量化风险和定性风险"],"answer":"A","explanation":"第三条规定，保险公司偿付能力风险由固有风险和控制风险组成。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S02","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"可资本化风险包括以下哪些风险？","options":["保险风险、市场风险和信用风险","操作风险、战略风险和声誉风险","保险风险、操作风险和流动性风险","信用风险、声誉风险和战略风险"],"answer":"A","explanation":"第三条规定，可资本化风险包括保险风险、市场风险和信用风险。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S03","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"难以资本化风险包括以下哪些风险？","options":["操作风险、战略风险、声誉风险和流动性风险","保险风险、市场风险、信用风险和操作风险","战略风险、市场风险和流动性风险","保险风险、声誉风险和信用风险"],"answer":"A","explanation":"第三条规定，难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S04","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"关于难以资本化的固有风险的评估方式，正确的是：","options":["纳入风险综合评级予以评估","通过最低资本进行计量","通过压力测试进行计量","不纳入偿付能力监管"],"answer":"A","explanation":"第三条规定，可资本化的固有风险和控制风险通过最低资本计量，难以资本化的固有风险纳入风险综合评级评估。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S05","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据本规则，操作风险的定义是：","options":["由于不完善的内部操作流程、人员、系统或外部事件而导致直接或间接损失的风险，包括法律及监管合规风险","由于战略制定和实施的流程无效导致的风险","导致利益相关方产生负面评价的风险","无法及时获得充足资金支付到期债务的风险"],"answer":"A","explanation":"第七条规定，操作风险包括法律及监管合规风险（不包括战略风险和声誉风险）。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S06","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"在分类监管中，操作风险划分为几类？","options":["六类","四类","五类","七类"],"answer":"A","explanation":"第八条规定，操作风险划分为保险业务线、资金运用业务线、公司治理、信息系统、案件管理和其他操作风险共六类。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S07","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"战略风险是指：","options":["由于战略制定和实施的流程无效或经营环境的变化，导致公司战略与市场环境、公司能力不匹配的风险","由于内部操作流程不完善导致损失的风险","利益相关方产生负面评价造成损失的风险","无法以合理成本获得资金的风险"],"answer":"A","explanation":"第十条明确了战略风险的定义。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S08","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"银保监会评估保险公司流动性风险的依据是：","options":["《保险公司偿付能力监管规则第13号：流动性风险》","《保险公司偿付能力监管规则第8号：市场风险最低资本》","《保险公司偿付能力监管规则第9号：信用风险最低资本》","《保险公司偿付能力管理规定》"],"answer":"A","explanation":"第十六条规定，银保监会根据第13号规则通过流动性风险监管指标、监测指标、现金流压力测试结果等评估流动性风险。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S09","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"分类监管评价采用加权平均法，其中可资本化风险评分所占权重为：","options":["50%","60%","40%","70%"],"answer":"A","explanation":"第二十条规定，可资本化风险评分权重50%，难以资本化风险评分权重50%。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S10","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"银保监会按照偿付能力风险大小将保险公司分为几个监管类别？","options":["四个（A、B、C、D）","三个（A、B、C）","五个（A、B、C、D、E）","两个（达标、不达标）"],"answer":"A","explanation":"第十九条规定，按偿付能力风险大小分为A、B、C、D四个监管类别。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S11","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"A类公司根据风险由小到大进一步细分为：","options":["AAA类、AA类、A类","A+类、A类、A-类","AA类、A类、B类","AAA类、AA类、A类、A-类"],"answer":"A","explanation":"第十九条规定，A类公司细分为AAA类、AA类、A类。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S12","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"B类公司根据风险由小到大进一步细分为：","options":["BBB类、BB类、B类","B+类、B类、B-类","BBB类、BB类、B类、B-类","BBB类、BBB-类、BB类"],"answer":"A","explanation":"第十九条规定，B类公司细分为BBB类、BB类、B类。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S13","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"关于C类公司的界定，正确的是：","options":["偿付能力充足率不达标，或者偿付能力充足率虽然达标，但操作风险、战略风险、声誉风险和流动性风险中某一类或几类风险较大的公司","偿付能力充足率达标且四类风险小的公司","偿付能力充足率达标且四类风险较小的公司","偿付能力充足率不达标且风险严重的公司"],"answer":"A","explanation":"第十九条规定，C类公司为充足率不达标，或达标但某一类或几类风险较大的公司。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S14","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"对D类公司，银保监会除可采取对C类公司的监管措施外，还可采取的监管措施是：","options":["接管以及银保监会认为必要的其他监管措施","仅风险提示","仅监管谈话","吊销营业执照"],"answer":"A","explanation":"第二十七条规定，对D类公司可采取接管以及银保监会认为必要的其他监管措施。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S15","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"银保监会和银保监局对保险公司法人机构进行分类监管评价的频率是：","options":["每季度结束后进行一次","每月进行一次","每半年进行一次","每年进行一次"],"answer":"A","explanation":"第二十八条规定，每季度结束后对保险公司法人机构进行一次分类监管评价。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S16","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"分类监管指标的计算方式是：","options":["偿付能力监管信息系统按照预设的统一计算规则自动计算","保险公司自行计算并报监管部门确认","银保监会手工计算","聘请第三方机构计算"],"answer":"A","explanation":"第二十九条规定，偿付能力监管信息系统按预设统一计算规则自动计算各项分类监管指标，得到综合评价分数和评级结果。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S17","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"银保监会认为偿付能力监管信息系统自动得分没有准确反映直接监管保险公司风险状况的，可以：","options":["调整评级结果","要求保险公司重新报送数据","宣布评级结果无效","不予披露评级结果"],"answer":"A","explanation":"第三十条规定，银保监会根据日常监管信息认为自动得分未准确反映风险状况的，可以调整评级结果。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S18","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"负责对属地监管的保险公司法人机构实施分类监管的部门是：","options":["银保监局","银保监会","保险行业协会","地方金融监管局"],"answer":"A","explanation":"第五条规定，银保监会负责直接监管的法人机构，银保监局负责属地监管的法人机构。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S19","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"对B类公司，银保监会可采取的针对性监管措施不包括以下哪项？","options":["接管","风险提示","监管谈话","进行专项现场检查"],"answer":"A","explanation":"第二十四条规定B类公司措施包括风险提示、监管谈话、限期整改、专项现场检查、要求提交和实施计划；接管是对D类公司的措施。","difficulty":2,"type":"concept","source":"core"},{"id":"11-S20","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"声誉风险评估中，银保监会统筹评估的内容是：","options":["保险风险、市场风险、信用风险、操作风险、战略风险、流动性风险等引发声誉风险的可能性","仅公司自身的舆论报道","仅合作伙伴和利益相关方的情况","仅行业声誉风险的总体水平"],"answer":"A","explanation":"第十四条规定，银保监会考虑声誉风险与其他风险关联度较强的特点，统筹评估各类风险引发声誉风险的可能性。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M01","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于保险公司偿付能力风险的构成，下列说法正确的有：","options":["偿付能力风险由固有风险和控制风险组成","固有风险由可资本化风险和难以资本化风险组成","可资本化风险包括保险风险、市场风险和信用风险","难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险"],"answer":["A","B","C","D"],"explanation":"第三条对偿付能力风险的构成作了完整规定，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M02","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"在分类监管中，操作风险划分为以下哪几类？","options":["保险业务线的操作风险","资金运用业务线的操作风险","公司治理相关的操作风险","信息系统相关的操作风险"],"answer":["A","B","C","D"],"explanation":"第八条规定操作风险分为六类，包括保险业务线、资金运用业务线、公司治理、信息系统、案件管理及其他操作风险，四项均在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M03","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"银保监会主要从以下哪些方面评估保险公司的操作风险？","options":["评估公司操作风险的外部环境，包括行业操作风险的总体水平和趋势","评估各业务线的内部控制程序和流程、操作风险的历史数据、经验分布和发展趋势","评估公司可能导致操作风险的人员因素，包括人员的专业能力、离职率、绩效管理等","评估公司信息系统存在的问题和风险，包括系统设计缺陷、软硬件故障、信息安全和数据质量等"],"answer":["A","B","C","D"],"explanation":"第九条规定了操作风险评估的五个方面，上述四项均在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M04","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于四个监管类别的界定，下列说法正确的有：","options":["A类公司是偿付能力充足率达标且四类难以资本化风险小的公司","B类公司是偿付能力充足率达标且四类难以资本化风险较小的公司","C类公司是偿付能力充足率不达标，或达标但某一类或几类风险较大的公司","D类公司是偿付能力充足率不达标，或达标但某一类或几类风险严重的公司"],"answer":["A","B","C","D"],"explanation":"第十九条对A、B、C、D四类公司的界定标准作了规定，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M05","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"对B类公司可采取的监管措施包括：","options":["风险提示","监管谈话","要求限期整改存在的问题","要求提交和实施预防偿付能力充足率不达标或完善风险管理的计划"],"answer":["A","B","C","D"],"explanation":"第二十四条规定B类公司监管措施包括风险提示、监管谈话、限期整改、专项现场检查、要求提交和实施计划等，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M06","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于分类监管的评价内容，下列说法正确的有：","options":["对操作风险、战略风险、声誉风险和流动性风险四类难以资本化的固有风险进行评价","综合可资本化风险及四类难以资本化风险的评价结果，评价整体偿付能力风险","分类监管评价结果综合反映资本充足状况和其他偿付能力风险状况","分类监管评价采用加权平均法"],"answer":["A","B","C","D"],"explanation":"第六条、第十八条、第二十条规定了评价内容、结果含义和加权平均法，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M07","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"银保监会主要从以下哪些方面评估保险公司的声誉风险？","options":["评估公司声誉风险的外部环境，包括行业声誉风险的总体水平和趋势","评估公司声誉风险的历史数据、当前舆论报道、潜在风险因素","评估可能导致公司声誉风险的外部因素，包括合作伙伴、利益相关方、信用评级、不可抗力等","评估公司战略与市场环境的匹配情况"],"answer":["A","B","C"],"explanation":"第十三条规定声誉风险评估的三个方面；D项属于战略风险评估内容（第十一条）。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M08","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于对C类公司的监管措施，下列说法正确的有：","options":["对核心或综合偿付能力充足率不达标的C类公司，可按《保险公司偿付能力管理规定》采取针对性监管措施","对操作风险较大的C类公司，可对公司治理、内控流程、人员管理、信息系统等采取相应监管措施","对流动性风险较大的C类公司，根据第13号规则有关规定采取相应监管措施","C类公司不可采取对B类公司的监管措施"],"answer":["A","B","C"],"explanation":"第二十五、二十六条规定C类公司除可采取对B类公司的监管措施外还可采取进一步措施，D项错误。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M09","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于分类监管的运行机制，下列说法正确的有：","options":["银保监会和银保监局每季度结束后对保险公司法人机构进行一次分类监管评价","在每季度结束后的规定期限内，保险公司和银保监局应向偿付能力监管信息系统报送分类监管指标有关信息和数据","偿付能力监管信息系统自动计算各项分类监管指标，得到综合评价分数和评级结果","监管部门向保险公司通报风险综合评级结果并对外披露相关信息"],"answer":["A","B","C","D"],"explanation":"第二十八条至第三十一条对运行机制作了规定，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"11-M10","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"下列哪些机构适用第11号规则开展风险综合评级？","options":["财产保险公司","人身保险公司（含健康保险公司、养老保险公司）","再保险公司","保险集团"],"answer":["A","B","C"],"explanation":"第二条和第三十二条规定财险、人身险、再保险公司适用本规则；保险集团的分类监管规则由银保监会另行制定，D不适用。","difficulty":2,"type":"concept","source":"core"},{"id":"11-X-S01","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据第11号规则，分类监管评价采用加权平均法，可资本化风险评分与难以资本化风险评分的权重分别为？","options":["各占50%","60%和40%","70%和30%","40%和60%"],"answer":"A","explanation":"分类监管评价采用加权平均法，可资本化风险评分与难以资本化风险评分各占50%权重。依据第11号规则第四章评价方法。","difficulty":1,"type":"concept","source":"extra"},{"id":"11-X-S02","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据第11号规则，B类公司按偿付能力风险由小到大细分为？","options":["BBB类、BB类、B类","B类、BB类、BBB类","BB类、B类、BBB类","BBB类、B类、BB类"],"answer":"A","explanation":"B类公司细分为BBB类、BB类、B类，风险由小到大；A类公司细分为AAA类、AA类、A类。依据第11号规则第三章评价类别。","difficulty":1,"type":"concept","source":"extra"},{"id":"11-X-S03","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"某保险公司在分类监管评价中，可资本化风险评分为90分，难以资本化风险评分为60分，其综合评价分数为多少？","options":["70分","75分","80分","85分"],"answer":"B","explanation":"综合评价分数=90×50%+60×50%=45+30=75分。依据第11号规则第四章加权平均法。","difficulty":2,"type":"calc","source":"extra"},{"id":"11-X-S04","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据第11号规则，关于操作风险的范围，下列说法正确的是？","options":["包括法律及监管合规风险，不包括战略风险和声誉风险","包括战略风险","包括声誉风险","不包括法律及监管合规风险"],"answer":"A","explanation":"操作风险包括法律及监管合规风险，但不包括战略风险和声誉风险。依据第11号规则第二章操作风险定义。","difficulty":2,"type":"concept","source":"extra"},{"id":"11-X-S05","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"某保险公司偿付能力充足率达标，但监管部门评估认为其声誉风险较大。根据第11号规则，该公司应评定的监管类别为？","options":["A类","B类","C类","无法评定"],"answer":"C","explanation":"C类公司指偿付能力充足率不达标，或达标但某一类或几类风险较大的公司；声誉风险较大对应C类，严重才对应D类。依据第11号规则第三章评价类别。","difficulty":2,"type":"scenario","source":"extra"},{"id":"11-X-S06","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"某保险公司综合偿付能力充足率为105%，核心偿付能力充足率为48%，四类难以资本化风险均较小。根据第11号规则，关于其监管类别的判断，正确的是？","options":["一定为C类","一定为D类","为C类或D类，不可能是A类或B类","仍可能为B类"],"answer":"C","explanation":"核心偿付能力充足率低于50%属于偿付能力不达标，而A类、B类公司均须偿付能力充足率达标，故只能评定为C类或D类（视风险严重程度而定）。依据第11号规则第三章评价类别定义。","difficulty":3,"type":"calc","source":"extra"},{"id":"11-X-S07","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"single","q":"根据第11号规则，在偿付能力风险构成中，下列风险通过最低资本计量（而非纳入风险综合评级评估）的是？","options":["操作风险","声誉风险","信用风险","流动性风险"],"answer":"C","explanation":"可资本化的固有风险和控制风险通过最低资本计量，可资本化风险包括保险风险、市场风险和信用风险；操作、战略、声誉、流动性等难以资本化风险纳入风险综合评级评估。依据第11号规则第一、二章。","difficulty":3,"type":"cross","source":"extra"},{"id":"11-X-M01","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"根据第11号规则，难以资本化风险包括下列哪些风险？","options":["操作风险","保险风险","声誉风险","流动性风险"],"answer":["A","C","D"],"explanation":"难以资本化风险包括操作风险、战略风险、声誉风险和流动性风险；保险风险属于可资本化风险。依据第11号规则第一章关键定义。","difficulty":1,"type":"concept","source":"extra"},{"id":"11-X-M02","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于保险公司监管类别的细分，下列说法正确的有？","options":["A类公司细分为AAA类、AA类、A类，风险由小到大","B类公司细分为BBB类、BB类、B类","AAA类公司风险最大","C类公司细分为CCC类、CC类、C类"],"answer":["A","B"],"explanation":"A类细分AAA、AA、A，B类细分BBB、BB、B，风险均由小到大排列，AAA类风险最小；C类、D类不再细分。依据第11号规则第三章评价类别。","difficulty":2,"type":"concept","source":"extra"},{"id":"11-X-M03","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"根据第11号规则监管类别定义，下列公司中应评定为C类或D类的有？","options":["综合偿付能力充足率为95%的公司","核心偿付能力充足率为45%的公司","偿付能力充足率达标但流动性风险严重的公司","偿付能力充足率达标且四类难以资本化风险均较小的公司"],"answer":["A","B","C"],"explanation":"综合充足率低于100%或核心充足率低于50%均属不达标，只能评为C类或D类；达标但某类风险严重的公司应评为D类；达标且风险较小的公司应评为B类（风险小的为A类）。依据第11号规则第三章。","difficulty":2,"type":"calc","source":"extra"},{"id":"11-X-M04","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"某公司被评定为B类，根据第11号规则，监管部门可对其采取的监管措施包括？","options":["风险提示","要求提交和实施预防偿付能力充足率不达标或完善风险管理的计划","接管","专项现场检查"],"answer":["A","B","D"],"explanation":"B类公司监管措施包括风险提示、监管谈话、要求限期整改、专项现场检查、要求提交和实施预防偿付能力充足率不达标或完善风险管理的计划；接管是针对D类公司的措施。依据第11号规则第五章。","difficulty":2,"type":"scenario","source":"extra"},{"id":"11-X-M05","rule_no":11,"rule_title":"风险综合评级（分类监管）","qtype":"multi","q":"关于风险综合评级的运行机制，下列说法正确的有？","options":["银保监会和银保监局每季度结束后对保险公司法人机构进行一次分类监管评价","依托偿付能力监管信息系统按预设统一计算规则自动计算各项指标","系统自动生成的评级结果一经确定不得调整","监管部门认为系统自动得分未准确反映公司风险状况的，可以调整评级结果"],"answer":["A","B","D"],"explanation":"每季度评价一次，由偿付能力监管信息系统自动计算综合评价分数和评级结果；银保监会或属地监管局认为系统得分未准确反映风险状况的，可以调整评级结果。依据第11号规则第六章运行机制。","difficulty":3,"type":"scenario","source":"extra"},{"id":"12-S01","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"根据第12号规则，制定本规则的目的不包括以下哪项？","options":["确定保险公司流动性风险最低资本的计量标准","明确保险公司偿付能力风险管理的监管要求","规范监管机构对保险公司风险管理能力的评估","确定保险公司控制风险最低资本的计量标准"],"answer":"A","explanation":"第一条规定目的为明确监管要求、规范评估、确定控制风险最低资本计量标准；流动性风险最低资本计量不在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S02","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"满足下列任意两个标准即为Ⅰ类保险公司，其中关于公司成立年限的标准是：","options":["公司成立超过5年","公司成立超过3年","公司成立超过10年","公司成立超过8年"],"answer":"A","explanation":"第六条规定，Ⅰ类保险公司标准之一为公司成立超过5年。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S03","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"关于Ⅰ类保险公司的规模标准，正确的是：","options":["财产保险公司、再保险公司最近会计年度签单保费超过50亿元或总资产超过200亿元","财产保险公司签单保费超过20亿元或总资产超过100亿元","人身保险公司签单保费超过50亿元或总资产超过200亿元","所有保险公司签单保费超过100亿元"],"answer":"A","explanation":"第六条规定，财险、再保签单保费超50亿或总资产超200亿；人身险签单保费超200亿或总资产超300亿。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S04","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"Ⅰ类保险公司划分标准中，省级分支机构数量的标准是：","options":["超过15家","超过10家","超过20家","超过5家"],"answer":"A","explanation":"第六条规定，省级分支机构数量超过15家为标准之一。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S05","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"对保险公司偿付能力风险管理体系的完整性和有效性承担最终责任的是：","options":["董事会","高级管理层","首席风险官","监事会"],"answer":"A","explanation":"第十二条规定，董事会对偿付能力风险管理体系的完整性和有效性承担最终责任。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S06","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"关于风险管理委员会的设立，下列说法正确的是：","options":["Ⅰ类保险公司应当在董事会下设立风险管理委员会，Ⅱ类保险公司可以不设立","所有保险公司均必须设立风险管理委员会","Ⅰ类保险公司可以不设立风险管理委员会","Ⅱ类保险公司必须在董事会下设立风险管理委员会"],"answer":"A","explanation":"第十三条规定Ⅰ类公司应设立；第十六条规定Ⅱ类公司可以不设立，未设立的由审计委员会履行相应职责。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S07","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"Ⅱ类保险公司未设立风险管理委员会的，相应职责由谁履行？","options":["审计委员会","董事会","监事会","总经理办公会"],"answer":"A","explanation":"第十六条规定，Ⅱ类保险公司可以不设立风险管理委员会，未设立的由审计委员会履行相应职责。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S08","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"风险管理委员会主任应当由下列哪类人员担任？","options":["具有风险管理经验的董事","高级管理人员","首席风险官","独立董事"],"answer":"A","explanation":"第十七条规定，风险管理委员会主任应当由具有风险管理经验的董事担任。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S09","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"高级管理层向风险管理委员会汇报公司偿付能力风险水平及风险管理状况的最低频率是：","options":["至少每年一次","至少每季度一次","至少每半年一次","至少每月一次"],"answer":"A","explanation":"第二十条规定，高级管理层应当至少每年向风险管理委员会汇报一次。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S10","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"关于首席风险官的任职条件，下列说法正确的是：","options":["具有三年以上风险管理工作经验，或五年以上法律合规、投资、精算、财务、会计等相关领域管理经验","具有五年以上风险管理工作经验","具有十年以上保险行业工作经验","具有两年以上风险管理工作经验"],"answer":"A","explanation":"第二十一条规定，首席风险官应具有三年以上风险管理工作经验或五年以上相关领域管理经验，并取得高管任职资格。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S11","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"Ⅰ类保险公司独立风险管理部门的人员配备要求是：","options":["至少8名风险管理人员，且至少5人具有3年以上相关工作经验","至少5名风险管理人员，且至少3人具有相关经验","至少10名风险管理人员","至少2名具有3年以上经验的专业人员"],"answer":"A","explanation":"第二十二条规定，Ⅰ类公司应配备至少8名专业人员，其中至少5人具有3年以上相关工作经验。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S12","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"Ⅱ类保险公司未设立独立风险管理部门的，牵头部门的人员要求是：","options":["至少有两名具有3年以上风险管理、财会、精算、投资、法律或相关工作经验的专业人员","至少有八名专业人员","至少有一名精算师","无人员要求"],"answer":"A","explanation":"第二十二条规定，Ⅱ类公司未设立独立风险管理部门的，牵头部门至少应有两名具有3年以上相关工作经验的专业人员。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S13","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"保险公司内部审计部门检查、评估公司偿付能力风险管理体系运行情况的最低频率是：","options":["每年至少一次","每季度至少一次","每半年至少一次","每三年至少一次"],"answer":"A","explanation":"第二十五条规定，内部审计部门每年至少应当检查、评估一次并向董事会报告。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S14","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"Ⅰ类保险公司风险管理部门及分管该部门的公司高级管理人员的考核指标中，风险管理制度健全性、遵循有效性相关指标的权重不应低于：","options":["50%","30%","20%","15%"],"answer":"A","explanation":"第二十八条规定，风险管理部门及分管高管考核权重不低于50%。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S15","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"在售产品管理中，对当期签单保费占比在5%以上且上市两年以内的产品，评估销售情况、现金流、资本占用、利润等的最低频率是：","options":["至少每半年评估一次","至少每年评估一次","至少每季度评估一次","至少每月评估一次"],"answer":"A","explanation":"第四十九条规定，上市两年以内的产品至少每半年评估一次，上市超过两年的至少每年评估一次。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S16","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"银保监会对保险公司偿付能力风险管理能力进行现场评估的频率是：","options":["每三年一次","每年一次","每两年一次","每五年一次"],"answer":"A","explanation":"第一百零八条规定，银保监会每三年对保险公司偿付能力风险管理能力进行一次现场评估。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S17","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"保险公司开展偿付能力风险管理自评估的频率是：","options":["每年一次","每半年一次","每三年一次","每季度一次"],"answer":"A","explanation":"第一百一十条规定，保险公司应当每年开展一次偿付能力风险管理自评估。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S18","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"偿付能力风险管理评估中，制度健全性和遵循有效性在评估结果中的权重分配是：","options":["各占50%","制度健全性占60%，遵循有效性占40%","制度健全性占40%，遵循有效性占60%","各占30%"],"answer":"A","explanation":"第一百零六条规定，制度健全性和遵循有效性在评估结果中各占50%权重。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S19","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"偿付能力风险管理评估最终得分S的计算公式为：","options":["S=S1×50%+S2×50%","S=S1×60%+S2×40%","S=S1+S2","S=S1×50%+S2×50%+S3"],"answer":"A","explanation":"第一百一十七条规定，S=S1×50%+S2×50%，其中S1为现场评估绝对分，S2为相对分。","difficulty":2,"type":"concept","source":"core"},{"id":"12-S20","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"相对分计算S2=S1×K中，标准分m的取值为：","options":["80","70","60","100"],"answer":"A","explanation":"第一百一十八条规定，m为标准分，m=80；M为当期公司所处行业评估绝对分排名前15%的公司的平均分。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M01","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"下列哪些机构适用或参照适用第12号规则？","options":["相互保险组织","经营保险业务的保险集团公司","自保公司（参照执行）","不经营保险业务的保险集团公司"],"answer":["A","B","C"],"explanation":"第一百二十五条规定相互保险组织、经营保险业务的保险集团公司适用本规则；第一百二十六条规定自保公司参照执行；不经营保险业务的保险集团不属于本规则适用范围。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M02","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"关于Ⅰ类保险公司的划分标准，满足任意两个即为Ⅰ类的标准包括：","options":["公司成立超过5年","财产保险公司、再保险公司最近会计年度签单保费超过50亿元或总资产超过200亿元","人身保险公司最近会计年度签单保费超过200亿元或总资产超过300亿元","省级分支机构数量超过15家"],"answer":["A","B","C","D"],"explanation":"第六条规定了三个标准，满足任意两个即为Ⅰ类公司，四项表述均属于该三个标准。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M03","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"董事会在偿付能力风险管理中的具体职责包括：","options":["审批公司偿付能力风险管理的总体目标、风险偏好、风险容忍度和风险管理政策","审批公司偿付能力风险管理组织架构和职责","持续关注公司偿付能力风险状况","审批公司偿付能力报告"],"answer":["A","B","C","D"],"explanation":"第十二条列举了董事会的具体职责，四项均在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M04","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"首席风险官应当符合的条件包括：","options":["具有风险管理、法律、投资、精算、财务、会计、金融等与工作要求相适应的专业背景","具有三年以上风险管理工作经验，或五年以上法律合规、投资、精算、财务、会计等相关领域管理经验","取得保险公司高级管理人员任职资格","不得同时负责销售、投资等与风险管理有利益冲突的工作"],"answer":["A","B","C","D"],"explanation":"第二十一条规定了首席风险官的四项任职条件，全部正确。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M05","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"Ⅰ类保险公司风险管理制度健全性、遵循有效性相关指标的考核权重要求，正确的有：","options":["产品销售、产品管理等业务部门及分管高管不低于20%","财会、投资、精算等职能部门及分管高管不低于30%","风险管理部门及分管高管不低于50%","其他与风险管理有关的职能部门及分管高管不低于15%"],"answer":["A","B","C","D"],"explanation":"第二十八条对Ⅰ类公司四类部门及分管高管的考核权重分别规定为20%、30%、50%、15%。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M06","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"保险公司应当运用的风险管理工具包括但不限于：","options":["全面预算","资产负债管理","资本规划与配置","压力测试"],"answer":["A","B","C","D"],"explanation":"第三十二条规定风险管理工具包括全面预算、资产负债管理、资本规划与配置、压力测试和风险管理信息系统。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M07","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"关于各类风险管理报告的频率，正确的有：","options":["市场风险定量监测标准下，至少每季度向高级管理层报告一次","保险风险管理牵头部门或风险管理部门至少每半年向高级管理层报告一次","战略风险由高级管理层至少每年向董事会报告一次","声誉风险、流动性风险管理情况至少每半年向高级管理层报告一次"],"answer":["A","B","C","D"],"explanation":"第五十六条、第五十三条、第九十七条、第一百条、第一百零三条分别规定了上述报告频率，均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M08","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"偿付能力风险管理评估应当遵循的原则包括：","options":["自上而下原则","管理实效原则","成本效益原则","独立性原则"],"answer":["A","B"],"explanation":"第一百零五条规定评估遵循自上而下原则和管理实效原则，未规定成本效益原则和独立性原则。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M09","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"制度健全性评估结果的分类及其含义，正确的有：","options":["完全符合是指建立了全面的风险管理制度，且内容和要素完全达到监管要求","大部分符合是指符合监管要求的程度在80%到100%之间","部分符合是指符合监管要求的程度在50%到80%之间","不符合是指未建立相关风险管理制度，或符合程度在50%以下"],"answer":["A","B","C","D"],"explanation":"第一百零七条规定了制度健全性评估结果的分类标准，四项均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"12-M10","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"存在下列情形之一的，保险公司偿付能力风险管理现场评估绝对分S1不得高于70分：","options":["保险公司股权结构不清晰或存在重大股权纠纷","风险管理基础与环境部分得分低于12分","公司治理评估得分低于60分","出现重大风险事件"],"answer":["A","B","C","D"],"explanation":"第一百一十九条规定了S1不得高于70分的八种情形，上述四项均在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"12-X-S01","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"根据第12号规则，银保监会对保险公司偿付能力风险管理能力开展现场评估的频率为？","options":["每三年一次","每年一次","每两年一次","每季度一次"],"answer":"A","explanation":"银保监会每三年对保险公司进行一次现场评估；当年未被评估的公司以最近一次现场评估结果计算控制风险最低资本，公司自身应每年开展一次自评估。依据第12号规则第十一章。","difficulty":1,"type":"concept","source":"extra"},{"id":"12-X-S02","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"根据第12号规则，偿付能力风险管理评估中制度健全性与遵循有效性所占权重分别为？","options":["各占50%","60%和40%","70%和30%","40%和60%"],"answer":"A","explanation":"偿付能力风险管理评估中，制度健全性和遵循有效性各占50%权重。依据第12号规则第十一章评分方法。","difficulty":1,"type":"concept","source":"extra"},{"id":"12-X-S03","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"某财产保险公司成立6年，最近会计年度签单保费40亿元，总资产180亿元，省级分支机构18家。根据第12号规则，该公司属于？","options":["Ⅰ类保险公司","Ⅱ类保险公司","不满足任何划分标准","由公司自行确定类别"],"answer":"A","explanation":"Ⅰ类公司须满足任意两个标准：该公司满足成立超过5年、省级分支机构超过15家两项（签单保费未超50亿、总资产未超200亿），故为Ⅰ类公司。依据第12号规则第一章Ⅰ类公司划分标准。","difficulty":2,"type":"calc","source":"extra"},{"id":"12-X-S04","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"某保险公司量化风险中可资本化风险最低资本为20亿元，控制风险调整系数Q为0.05，则其控制风险最低资本为多少？","options":["0.5亿元","1亿元","1.5亿元","2亿元"],"answer":"B","explanation":"MC控制风险=Q×MC可资本化风险=0.05×20亿=1亿元。依据第12号规则第十一章控制风险最低资本计算公式。","difficulty":2,"type":"calc","source":"extra"},{"id":"12-X-S05","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"根据第12号规则，担任保险公司首席风险官应具备的条件是？","options":["具有三年以上风险管理工作经验，或五年以上法律合规、投资、精算、财务、会计等相关领域管理经验","具有五年以上风险管理工作经验，或三年以上相关领域管理经验","具有十年以上保险从业经验","必须取得精算师资格"],"answer":"A","explanation":"首席风险官应具有三年以上风险管理工作经验，或五年以上法律合规、投资、精算、财务、会计等相关领域管理经验。依据第12号规则第二章首席风险官任职条件。","difficulty":2,"type":"concept","source":"extra"},{"id":"12-X-S06","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"某保险公司偿付能力风险管理评估现场评估绝对分S1为85分，当期行业评估绝对分排名前15%公司的平均分M为100分（标准分m=80），则其最终得分S为多少？","options":["68分","76.5分","80分","85分"],"answer":"B","explanation":"K=m/M=80/100=0.8，相对分S2=S1×K=85×0.8=68，最终得分S=85×50%+68×50%=42.5+34=76.5分。依据第12号规则第十一章评分方法。","difficulty":3,"type":"calc","source":"extra"},{"id":"12-X-S07","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"single","q":"在偿二代整体框架下，监管机构依据第12号规则对保险公司偿付能力风险管理能力评估所确定的控制风险水平，主要用于计算下列哪项？","options":["实际资本","核心资本","控制风险最低资本","风险综合评级得分"],"answer":"C","explanation":"第12号规则评估的结果用于确定控制风险水平并计算控制风险最低资本（MC控制风险=Q×MC可资本化风险），控制风险与可资本化的固有风险一同通过最低资本计量。依据第12号规则第十一章。","difficulty":3,"type":"cross","source":"extra"},{"id":"12-X-M01","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"根据第12号规则，偿付能力风险管理目标与工具包括下列哪些？","options":["风险偏好体系及全面预算","内部审计","压力测试","风险管理信息系统"],"answer":["A","C","D"],"explanation":"五大工具为风险偏好体系及全面预算、资产负债管理、资本规划与配置、压力测试、风险管理信息系统；内部审计属于监督机制而非五大工具。依据第12号规则第三章。","difficulty":1,"type":"concept","source":"extra"},{"id":"12-X-M02","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"某Ⅰ类保险公司风险管理部门现有专业人员7名，其中4名具有3年以上相关工作经验。根据第12号规则，下列说法正确的有？","options":["专业人员总数应至少达到8名","具有3年以上相关工作经验的人员应至少达到5名","现有配置已完全符合监管要求","风险管理部门及分管高管考核权重不低于50%"],"answer":["A","B","D"],"explanation":"Ⅰ类公司风险管理部门至少配备8名专业人员，其中至少5人具有3年以上相关工作经验，现有7名（4名符合经验要求）未达标；考核权重上风险管理部门及分管高管不低于50%。依据第12号规则第二章。","difficulty":2,"type":"scenario","source":"extra"},{"id":"12-X-M03","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"某保险公司梳理风险管理报告频率，下列符合第12号规则要求的有？","options":["市场风险监测至少每季度一次","保险风险管理情况至少每半年向高级管理层报告一次","战略风险每两年向董事会报告一次即可","内部审计部门每年至少检查、评估一次偿付能力风险管理体系运行情况并向董事会报告"],"answer":["A","B","D"],"explanation":"市场风险监测至少每季度一次；保险、信用、操作、声誉、流动性风险管理情况至少每半年向高级管理层报告一次；战略风险应由高级管理层至少每年向董事会报告一次；内部审计每年至少检查评估一次并向董事会报告。依据第12号规则易考细节。","difficulty":2,"type":"scenario","source":"extra"},{"id":"12-X-M04","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"根据第12号规则，下列哪些情形下，偿付能力风险管理评估的现场评估绝对分S1不得高于70分？","options":["股权结构不清晰","风险管理基础与环境得分低于12分","公司治理评估结果低于60分","公司当年未发生重大风险事件"],"answer":["A","B","C"],"explanation":"股权不清晰、基础与环境得分低于12分、公司治理评估低于60分等八种情形下，S1不得高于70分；未发生重大风险事件不属于该类情形。依据第12号规则第十一章评分方法。","difficulty":3,"type":"scenario","source":"extra"},{"id":"12-X-M05","rule_no":12,"rule_title":"偿付能力风险管理要求与评估","qtype":"multi","q":"关于偿付能力风险管理评估结果的分类，下列说法正确的有？","options":["评估结果分为完全符合、大部分符合、部分符合、不符合、不适用五类","制度健全性与遵循有效性各占50%权重","评估结果分为四类","大部分符合指健全性得分为80%～100%"],"answer":["A","B","D"],"explanation":"评估结果分为五类；大部分符合为健全性80%～100%或有效性80%以上未达100%；制度健全性和遵循有效性各占50%权重。依据第12号规则第十一章评估内容与结果分类。","difficulty":2,"type":"concept","source":"extra"},{"id":"13-S01","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"根据第13号规则，本规则的制定目的是规范保险公司流动性风险管理的（），建立流动性监管指标和压力测试制度，防范流动性风险。","options":["最高监管要求","最低监管要求","指导性要求","参考性标准"],"answer":"B","explanation":"依据第13号规则第一条，本规则旨在规范流动性风险管理的最低监管要求。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S02","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"下列关于第13号规则适用范围的说法，正确的是（）。","options":["保险集团直接适用本规则","相互保险组织不适用本规则","保险集团的流动性风险监管规则另行规定","外国保险公司分公司不适用本规则"],"answer":"C","explanation":"依据第四十三条、第四十四条，相互保险组织适用本规则，保险集团的流动性风险监管规则另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S03","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"本规则所称流动性风险，是指保险公司无法及时获得充足资金或无法及时以（）获得充足资金，以支付到期债务或履行其他支付义务的风险。","options":["合理成本","市场公允价格","最低成本","账面价值"],"answer":"A","explanation":"依据第三条，流动性风险指无法及时获得充足资金或无法及时以合理成本获得充足资金的风险。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S04","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司流动性风险管理体系的基本要素不包括（）。","options":["流动性风险管理的治理结构","流动性风险管理的策略、政策和程序","流动性风险的识别、计量、监测和控制","流动性风险的公众信息披露安排"],"answer":"D","explanation":"依据第六条，体系基本要素包括治理结构、策略政策程序、识别计量监测控制三项，不含公众信息披露安排。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S05","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司（）承担流动性风险管理的最终责任。","options":["总经理","风险管理部","董事会","精算责任人"],"answer":"C","explanation":"依据第八条，董事会承担流动性风险管理的最终责任。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S06","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司董事会应当审批并至少（）审议一次流动性风险偏好和容忍度、流动性风险管理策略、重要的政策和流程。","options":["每半年","每年","每两年","每季度"],"answer":"B","explanation":"依据第八条，董事会审批并至少每年审议一次上述事项。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S07","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"未设置董事会的外国保险公司分公司，应由（）履行董事会的流动性风险管理职责并承担相应责任。","options":["高级管理层","总公司风险管理委员会","指定的高级管理人员","当地监管联络人"],"answer":"A","explanation":"依据第九条，未设置董事会的外国保险公司分公司由高级管理层履行董事会职责并承担责任。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S08","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司应当指定（）负责流动性风险管理工作。","options":["一名董事","一名高级管理人员","一个独立部门","一名精算师"],"answer":"B","explanation":"依据第十一条，公司应指定一名高级管理人员负责流动性风险管理工作。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S09","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司可能引发流动性风险的重大事件中，重要交易对手出现违约风险或外部信用评级下调至（）及以下属于重大事件。","options":["A-","BBB","BB+","B+"],"answer":"C","explanation":"依据第十七条第（七）项，重要交易对手违约风险或外部信用评级下调至BB+及以下属于重大事件。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S10","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司流动性风险监管指标不包括（）。","options":["流动性覆盖率","经营活动净现金流回溯不利偏差率","净现金流","综合退保率"],"answer":"D","explanation":"依据第三十三条，监管指标包括流动性覆盖率、经营活动净现金流回溯不利偏差率、净现金流；综合退保率是人身公司监测指标。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S11","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司应当以（）为基础计算流动性风险监管指标。","options":["合并财务报表","母公司财务报表","监管报表","管理会计报表"],"answer":"B","explanation":"依据第三十四条，应以母公司财务报表（而不是合并财务报表）为基础计算。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S12","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"根据附件2，LCR1的计算公式为（）。","options":["（基本情景下公司现金流入+现金及现金等价物评估时点账面价值）÷基本情景下公司现金流出×100%","基本情景下公司现金流入÷基本情景下公司现金流出×100%","（基本情景下公司现金流入+流动性资产储备变现金额）÷基本情景下公司现金流出×100%","（基本情景下公司现金流入-现金流出）÷期末总资产×100%"],"answer":"A","explanation":"依据附件2，LCR1=（基本情景下公司现金流入+现金及现金等价物评估时点账面价值）÷基本情景下公司现金流出×100%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S13","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"流动性覆盖率的达标要求为：LCR1、LCR2不低于100%，LCR3不低于（）。","options":["30%","50%","80%","100%"],"answer":"B","explanation":"依据附件2第三部分，LCR1、LCR2不低于100%，LCR3不低于50%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S14","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司应当计算未来（）的流动性覆盖率。","options":["1个月和6个月","3个月和6个月","3个月和12个月","6个月和12个月"],"answer":"C","explanation":"依据附件2，保险公司应当计算未来3个月和未来12个月的流动性覆盖率。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S15","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"经营活动净现金流回溯不利偏差率的达标要求是：保险公司最近两个季度的经营活动净现金流回溯不利偏差率不得连续低于（）。","options":["-20%","-30%","-40%","-50%"],"answer":"B","explanation":"依据附件2，最近两个季度的RDR不得连续低于-30%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S16","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"净现金流指标反映保险公司过去（）整体净现金流状况，其不得连续小于零。","options":["一个季度","一个会计年度","两个会计年度及当年累计","三个会计年度"],"answer":"C","explanation":"依据第三十七条及附件2，净现金流反映过去两个会计年度及当年累计的净现金流状况，不得连续小于零。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S17","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"下列资产的流动性资产储备折算系数为100%的是（）。","options":["可提前支取的定期存款","交易类及可供出售类国债","境内债券型基金（开放式）","上市股票"],"answer":"B","explanation":"依据附件2折算系数表，货币市场基金和交易类及可供出售类国债折算系数为100%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S18","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"下列资产的流动性资产储备折算系数为50%的是（）。","options":["可转债","境内混合型基金（开放式）","上市股票","组合类保险资产管理产品（开放式）"],"answer":"C","explanation":"依据附件2折算系数表，上市股票折算系数为50%，可转债和混合型基金为65%，组合类产品为60%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S19","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"下列各项中，属于流动性资产储备的是（）。","options":["非标准化债权资产","长期股权投资","AAA级以下债券","可提前支取的定期存款"],"answer":"D","explanation":"依据附件2，流动性资产储备不包括非标准化债权资产、长期股权投资、AAA级以下债券等；可提前支取的定期存款折算系数90%，属于储备。","difficulty":2,"type":"concept","source":"core"},{"id":"13-S20","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"保险公司应当至少每个季度进行一次现金流测试，测试区间为报告期末起未来（）。","options":["6个月","12个月","2年","3年"],"answer":"B","explanation":"依据附件1，测试区间为报告期末起未来12个月，按季度划分为四个季度。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M01","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"根据第13号规则，保险公司流动性风险管理体系的基本要素包括（）。","options":["流动性风险管理的治理结构","流动性风险管理的策略、政策和程序","流动性风险的识别、计量、监测和控制","流动性风险的经济资本计量"],"answer":["A","B","C"],"explanation":"依据第六条，体系包括治理结构、策略政策程序、识别计量监测控制三项基本要素。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M02","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"保险公司董事会承担流动性风险管理最终责任，应履行的职责包括（）。","options":["审批并至少每年审议一次流动性风险偏好和容忍度","监督高级管理层对流动性风险进行有效管理和控制","持续关注流动性风险状况，及时了解流动性风险水平及其重大变化","直接执行流动性风险应急计划"],"answer":["A","B","C"],"explanation":"依据第八条，董事会职责包括审批并至少每年审议一次偏好和容忍度、监督高管层、持续关注风险状况；制定和组织实施应急计划是高管层职责。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M03","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"根据第十七条，保险公司应当识别和关注的可能引发流动性风险的重大事件包括（）。","options":["非正常的集中退保","重大理赔事件","失去关键销售渠道","重要交易对手外部信用评级下调至BB+及以下"],"answer":["A","B","C","D"],"explanation":"依据第十七条，上述事件均属于应识别和关注的重大事件。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M04","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"根据第三十八条，人身保险公司的流动性风险监测指标包括（）。","options":["综合退保率","分红/万能账户业务净现金流","百元保费经营活动净现金流","应收分保账款率"],"answer":["A","B"],"explanation":"依据第三十八条第（二）项，人身险公司监测指标含综合退保率、分红/万能账户业务净现金流；百元保费净现金流为财险指标，应收分保账款率为再保险指标。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M05","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"下列关于再保险公司流动性风险监测指标的说法，正确的有（）。","options":["包括经营活动净现金流","包括特定业务现金流支出占比","包括应收分保账款率","包括综合退保率"],"answer":["A","B","C"],"explanation":"依据第三十八条第（三）项，再保险公司指标含经营活动净现金流、特定业务现金流支出占比、应收分保账款率等；综合退保率是人身险指标。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M06","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"下列资产中，不属于流动性资产储备的有（）。","options":["非标准化债权资产","另类投资资产","AAA级以下债券","货币市场基金"],"answer":["A","B","C"],"explanation":"依据附件2，流动性资产储备不包括非标债权、另类投资资产、AAA级以下债券等；货币市场基金折算系数100%，属于储备。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M07","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"下列关于流动性资产储备折算系数的说法，正确的有（）。","options":["境内债券型基金（开放式）为85%","AAA级非金融企业（公司）债为80%","境内股票型基金（开放式）为60%","可转债为70%"],"answer":["A","B","C"],"explanation":"依据附件2折算系数表，境内债基85%、AAA级非金融债80%、境内股基60%；可转债折算系数为65%而非70%。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M08","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"根据附件1，下列关于现金流测试的说法，正确的有（）。","options":["测试情景包括基本情景和压力情景","压力情景包括自测情景和必测情景","必测情景由保险公司根据行业情况自行统一发布","保险公司预测压力情景下的未来现金流时应考虑管理层为改善流动性采取的紧急措施"],"answer":["A","B"],"explanation":"依据附件1，测试含基本情景和压力情景，压力情景含自测和必测情景，必测情景由银保监会统一发布；压力情景下不考虑管理层行为。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M09","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"根据附件1，压力情景下预测现金流时，下列说法正确的有（）。","options":["不应考虑通过股东增资产生的现金流入","不应考虑管理层为改善现金流而出售资产产生的现金流入","可考虑正回购、拆入资金等短期筹资现金流入","未来各期末短期筹资业务余额可以超过报告日已有短期筹资余额"],"answer":["A","B","C"],"explanation":"依据附件1第七部分，压力情景下不考虑股东增资、资本补充债等流入和出售资产流入；可考虑短期筹资但余额以报告日已有余额为限。","difficulty":2,"type":"concept","source":"core"},{"id":"13-M10","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"对于流动性风险监管指标异常、存在重大流动性风险隐患或未按本规则建立和执行流动性风险管理体系的保险公司，银保监会可采取的监管措施包括（）。","options":["要求保险公司提交改善流动性水平的计划","要求保险公司完善流动性管理机制和制度","监管谈话","责令停止开展新业务"],"answer":["A","B","C"],"explanation":"依据第四十二条，监管措施包括要求提交改善计划、完善机制制度、监管谈话及其他必要措施；责令停办新业务不在列举之中。","difficulty":2,"type":"concept","source":"core"},{"id":"13-X-S01","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"依据《保险公司偿付能力监管规则第13号：流动性风险》，公司整体流动性覆盖率LCR1的达标标准是？","options":["不低于50%","不低于100%","不低于150%","不低于200%"],"answer":"B","explanation":"依据附件2，LCR1（基本情景公司整体流动性覆盖率）达标标准为不低于100%；LCR3（压力情景不考虑资产变现）达标标准为不低于50%。","difficulty":1,"type":"concept","source":"extra"},{"id":"13-X-S02","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"流动性资产储备应当具备的三项基本特征是？","options":["收益稳定、易于估值、无变现障碍","易于交易、易于变现、无变现障碍","高信用评级、易于交易、可质押","易于变现、信用等级AA级以上、无变现障碍"],"answer":"B","explanation":"流动性资产储备须同时具备易于交易、易于变现、无变现障碍三项特征，且未作为任何交易的质押、抵押或信用增级工具。","difficulty":1,"type":"concept","source":"extra"},{"id":"13-X-S03","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"依据第13号规则，保险公司现金流测试的频率和测试区间要求是？","options":["每半年一次，未来6个月","每季度一次，未来12个月","每季度一次，未来24个月","每年一次，未来12个月"],"answer":"B","explanation":"现金流测试应当至少每个季度进行一次，测试区间为报告期末起未来12个月，并以季度为单位划分为测试时点后第一个季度至第四个季度。","difficulty":2,"type":"concept","source":"extra"},{"id":"13-X-S04","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"某财产险公司基本情景下未来12个月公司现金流入预测值为80亿元，现金流出预测值为100亿元，评估时点现金及现金等价物账面价值为30亿元，则该公司基本情景LCR1为？","options":["90%","100%","110%","130%"],"answer":"C","explanation":"LCR1=（基本情景下公司现金流入+现金及现金等价物评估时点账面价值）÷基本情景下公司现金流出×100% =（80+30）÷100×100%=110%。","difficulty":2,"type":"calc","source":"extra"},{"id":"13-X-S05","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"依据第13号规则附件2规定的折算系数，以下资产类别中折算系数为100%的是？","options":["AAA级金融企业（公司）债","上市股票","货币市场基金、交易类及可供出售类国债","可提前支取的定期存款或协议存款"],"answer":"C","explanation":"货币市场基金、交易类及可供出售类国债折算系数为100%；AAA级金融企业（公司）债为85%；上市股票为50%；可提前支取的定期存款或协议存款为90%。","difficulty":2,"type":"calc","source":"extra"},{"id":"13-X-S06","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"某寿险公司发现自身面临重大流动性风险，依据第13号规则，其向银保监会报告的最迟时限是？","options":["自发现之日起24小时内","自发现之日起3日内","自发现之日起5个工作日内","自发现之日起10日内"],"answer":"B","explanation":"保险公司出现重大流动性风险时，应当自发现之日起3日内向银保监会报告，说明当前流动性水平、风险状况以及已采取和拟采取的应急措施等。","difficulty":2,"type":"scenario","source":"extra"},{"id":"13-X-S07","rule_no":13,"rule_title":"流动性风险","qtype":"single","q":"某财产险公司经营活动净现金流预测值为-5亿元，实际值为-7亿元，则其RDR为-40%。若该数值与上一季度RDR值均低于-30%，依据第13号规则，下列处理符合规定的是？","options":["公司应立即启动资本补充工具发行","连续两个季度低于-30%已触发监管关注，银保监会可要求公司提交改善计划并采取监管谈话等措施","RDR连续低于-30%属于正常波动，无需特别处理","公司应在下一季度披露年度财务报告即可"],"answer":"B","explanation":"RDR最近两个季度不得连续低于-30%。对指标异常、存在重大流动性风险隐患的公司，银保监会可采取要求提交改善计划、完善管理机制、监管谈话及其他必要措施。","difficulty":3,"type":"scenario","source":"extra"},{"id":"13-X-M01","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"依据第13号规则，流动性风险监管指标包括下列哪三项？","options":["流动性覆盖率（LCR）","经营活动净现金流回溯不利偏差率（RDR）","净现金流","综合退保率"],"answer":["A","B","C"],"explanation":"第三章规定的三项监管指标为流动性覆盖率、经营活动净现金流回溯不利偏差率、净现金流；综合退保率为人身险公司监测指标，不属于监管指标。","difficulty":1,"type":"concept","source":"extra"},{"id":"13-X-M02","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"依据第13号规则附件2，下列哪些资产类别属于流动性资产储备的合格范围？","options":["货币市场基金","AAA级金融企业（公司）债","持有至到期类债券资产","交易类及可供出售类国债"],"answer":["A","B","D"],"explanation":"持有至到期类债券资产明确列入排除项，不得纳入流动性资产储备；货币市场基金、AAA级金融企业（公司）债、交易类及可供出售类国债均在合格范围内。","difficulty":2,"type":"concept","source":"extra"},{"id":"13-X-M03","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"依据第13号规则附件2规定的折算系数，下列折算系数对应关系正确的有？","options":["地方政府债、政府支持机构债券、政策性金融债—90%","AAA级非金融企业（公司）债—80%","境内债券型基金（开放式）—85%","境内股票型基金（开放式）—50%"],"answer":["A","B","C"],"explanation":"境内股票型基金（开放式）折算系数为60%，而非50%；上市股票折算系数才为50%。其他三项折算系数对应均正确。","difficulty":2,"type":"calc","source":"extra"},{"id":"13-X-M04","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"某财险公司在压力情景下开展未来12个月现金流测试时，下列处理方式符合第13号规则的有？","options":["不考虑管理层行为的临时银行贷款紧急措施","假设原计划持有至到期的金融资产提前变现以缓解现金缺口","假设股东增资以弥补未来现金缺口","筹资活动只考虑已履行完决策程序、符合章程、有明确安排的筹资"],"answer":["A","D"],"explanation":"依据附件1，压力情景现金流测试不考虑管理层行为（如临时银行贷款等紧急措施），且不考虑股东增资、发行资本补充债等资本工具现金流入；也不应假设原计划持有至到期的金融资产提前变现。","difficulty":3,"type":"scenario","source":"extra"},{"id":"13-X-M05","rule_no":13,"rule_title":"流动性风险","qtype":"multi","q":"依据第13号与第18号规则，关于保险公司流动性风险监管指标的披露要求，下列说法正确的有？","options":["应当在偿付能力季度报告中披露LCR1、LCR2、LCR3结果","应当在偿付能力季度报告中披露现金流测试相关信息","流动性指标以合并财务报表为基础计算","应当在偿付能力季度报告中披露流动性风险监测指标"],"answer":["A","B","D"],"explanation":"流动性指标应当以母公司财务报表（而非合并财务报表）为基础计算；其余各项均符合第13号与第18号规则的披露要求。","difficulty":3,"type":"cross","source":"extra"},{"id":"14-S01","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"制定第14号规则的主要目的是（）。","options":["强化保险公司资本刚性约束，提升资本管理水平，明确资本规划监管标准","规范保险公司的投资行为","建立偿付能力报告编报规则","规范保险公司的信息披露行为"],"answer":"A","explanation":"依据第一条，本规则旨在强化资本刚性约束、提升资本管理水平、明确资本规划监管标准。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S02","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"本规则所称资本规划，指保险公司基于（），对资本规模、资本结构、资本来源和运用等进行的计划和安排。","options":["业务发展规划","偿付能力充足率目标","风险偏好","股东回报要求"],"answer":"B","explanation":"依据第三条，资本规划是基于偿付能力充足率目标对资本规模、结构、来源和运用的计划安排。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S03","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司资本规划应遵循的原则不包括（）。","options":["充足性原则","审慎性原则","前瞻性原则","收益性原则"],"answer":"D","explanation":"依据第四条，原则包括充足性、审慎性、前瞻性、可行性四项，无收益性原则。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S04","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司资本规划的（）原则要求规划目标、资本补充措施等应与公司实际情况和市场环境相符。","options":["充足性原则","审慎性原则","前瞻性原则","可行性原则"],"answer":"D","explanation":"依据第四条第（四）项，可行性原则要求目标、补充措施与实际情况和市场环境相符，具有可行性。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S05","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司的资本规划应当经（）。","options":["总经理办公会批准","董事会批准并经股东（大）会审议","银保监会审批","精算责任人签字确认"],"answer":"B","explanation":"依据第五条，资本规划应当经董事会批准并经股东（大）会审议。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S06","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司每年应当滚动编制未来（）的资本规划。","options":["一年","两年","三年","五年"],"answer":"C","explanation":"依据第七条，保险公司每年应当滚动编制未来三年的资本规划。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S07","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"下列各项中，不属于保险公司资本规划必须包括的内容的是（）。","options":["资本管理目标","资本需求评估","上一年度资本规划执行情况分析","下一年度投资组合明细"],"answer":"D","explanation":"依据第八条，资本规划至少包括资本管理目标、制定依据、资本需求评估、资本补充方案、上年度执行情况分析、应急预案六项内容。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S08","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司资本规划的管理目标，至少应当包括（）未来三年的目标。","options":["净利润和净资产","综合偿付能力充足率和核心偿付能力充足率","保费收入和市场份额","总资产和投资收益率"],"answer":"B","explanation":"依据第九条，管理目标至少包括综合偿付能力充足率、核心偿付能力充足率未来三年的目标。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S09","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"资本规划基本情景的相关参数和假设，应当与（）保持一致。","options":["《保险公司偿付能力监管规则第10号：压力测试》","《保险公司偿付能力监管规则第12号：偿付能力风险管理要求与评估》","《保险公司偿付能力监管规则第18号：偿付能力报告》","《企业会计准则》"],"answer":"A","explanation":"依据第十二条，基本情景参数和假设应与第10号规则保持一致，不利情景由公司合理设定。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S10","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"下列关于资本规划不利情景的说法，正确的是（）。","options":["不利情景由银保监会统一设定并发布","不利情景的参数由银保监会每季度更新","不利情景由保险公司结合具体实际合理设定","不利情景必须等同于第10号规则的压力情景"],"answer":"C","explanation":"依据第十二条，不利情景由保险公司结合具体实际合理设定。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S11","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司设定资本规划不利情景时，应考虑的因素不包括（）。","options":["业务发展的不利变化","投资收益率的不利波动","责任准备金评估折现率曲线的不利变化","股东增资计划的不利变化"],"answer":"D","explanation":"依据第十四条，至少应考虑业务发展、资产配置调整、投资收益率波动、费用假设变化、折现率曲线变化五项因素。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S12","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司应当优先考虑使用的资本补充措施是（）。","options":["增资扩股","发行资本补充债券","保单责任证券化","内源性资本补充措施"],"answer":"D","explanation":"依据第十七条，保险公司应当优先考虑使用内源性资本补充措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S13","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"下列各项中，属于外源性资本补充措施的是（）。","options":["提升盈利能力","优化产品结构","保单责任证券化","制定合理的利润分配政策"],"answer":"C","explanation":"依据第十八条，外源性措施包括增资扩股、发行资本补充工具、保单责任证券化、再保险等；其余三项为内源性措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S14","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司应当依据监管要求和资本管理目标，（），持续优化资本结构，提高资本质量。","options":["优先补充附属资本，合理补充核心资本","优先补充核心资本，合理补充附属资本","只补充核心资本","核心资本与附属资本均衡补充，比例相同"],"answer":"B","explanation":"依据第十九条，应优先补充核心资本，合理补充附属资本。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S15","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司应当在资本规划中建立资本应急预案，设定（）。","options":["最低注册资本预警线","偿付能力充足率预警值","净利润预警值","保费规模预警值"],"answer":"B","explanation":"依据第二十一条，应急预案应设定偿付能力充足率预警值，明确极端不利情景下的资本补充安排和应对措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S16","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"资本规划实施过程中出现重大变化的，保险公司应当提交（）审议。","options":["股东（大）会","董事会","银保监会","总经理办公会"],"answer":"B","explanation":"依据第二十二条，实施过程中出现重大变化的，应当提交董事会审议。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S17","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司应当于每年（）前，向银保监会报送资本规划。","options":["4月30日","5月31日","6月30日","12月31日"],"answer":"B","explanation":"依据第二十八条，保险公司应当于每年5月31日前报送资本规划。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S18","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"保险公司按第二十七条规定调整资本规划的，应当经董事会审议批准后（）内，向银保监会报送调整后的资本规划。","options":["5个工作日","10个工作日","15个工作日","1个月"],"answer":"B","explanation":"依据第二十九条，调整后应经董事会审议批准后10个工作日内报送。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S19","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"银保监会对保险公司发行资本补充工具进行审批时，将（）作为重要依据之一。","options":["公司的投资收益水平","公司的偿付能力报告评分","其资本规划","公司的市场份额排名"],"answer":"C","explanation":"依据第三十一条，银保监会审批资本补充工具发行时，将资本规划作为重要依据之一；发行与规划不一致的审慎考虑其申请。","difficulty":2,"type":"concept","source":"core"},{"id":"14-S20","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"本规则的施行日期（）。","options":["自2021年12月30日起立即施行","自2022年1月1日起施行","自发布之日起满6个月后施行","另行规定"],"answer":"D","explanation":"依据第三十五条，本规则于2021年12月30日第一次发布，施行日期另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M01","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"保险公司资本规划应遵循的原则包括（）。","options":["充足性原则","审慎性原则","前瞻性原则","可行性原则"],"answer":["A","B","C","D"],"explanation":"依据第四条，资本规划应遵循充足性、审慎性、前瞻性、可行性四项原则。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M02","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"保险公司资本规划至少应当包括的内容有（）。","options":["资本管理目标","资本规划制定依据","资本需求评估","资本补充方案"],"answer":["A","B","C","D"],"explanation":"依据第八条，还包括上一年度资本规划执行情况分析和应急预案，共六项。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M03","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"保险公司设定资本管理目标应当至少考虑的因素包括（）。","options":["外部环境，包括外部经济环境、法律政策环境","公司发展战略，包括业务发展规划、风险管理状况、风险偏好","资本补充的可行性和可持续性","同业公司的资本充足水平"],"answer":["A","B","C"],"explanation":"依据第十条，应至少考虑外部环境、公司发展战略、资本补充可行性和可持续性三项因素。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M04","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"资本规划不利情景的设置至少应当考虑的因素包括（）。","options":["业务发展的不利变化","资产配置的调整","投资收益率的不利波动","费用假设的不利变化"],"answer":["A","B","C","D"],"explanation":"依据第十四条，还包括责任准备金评估折现率曲线的不利变化，共五项因素。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M05","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"下列属于内源性资本补充措施的有（）。","options":["提升盈利能力","制定合理的利润分配政策","优化产品结构","发行资本补充工具"],"answer":["A","B","C"],"explanation":"依据第十七条，内源性措施包括提升盈利能力、合理利润分配政策、优化产品结构、优化资产结构、提升风险管理能力；发行资本补充工具属外源性措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M06","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"下列属于外源性资本补充措施的有（）。","options":["增资扩股","保单责任证券化","再保险","优化资产结构"],"answer":["A","B","C"],"explanation":"依据第十八条，外源性措施包括增资扩股、发行资本补充工具、保单责任证券化、再保险及其他资本工具；优化资产结构为内源性措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M07","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"资本规划中应急预案应当包括的内容有（）。","options":["触发条件","紧急资本补充措施","偿付能力充足率预警值","未来三年业务发展规划"],"answer":["A","B","C"],"explanation":"依据第八条第（六）项和第二十一条，应急预案包括触发条件和紧急资本补充措施等，并应设定偿付能力充足率预警值。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M08","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"下列情形中，保险公司应当对资本规划进行及时调整的有（）。","options":["监管要求发生重大变化","经营环境发生重大变化","公司战略发生重大变化","资本需求、补充和使用情况与资本规划发生重大偏离"],"answer":["A","B","C","D"],"explanation":"依据第二十七条，因监管要求、经营环境、公司战略等发生重大变化，导致资本需求、补充和使用情况与规划发生重大偏离的，应及时调整。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M09","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"保险公司未按本规则报送资本规划、资本规划编制不符合规定或实施过程中存在重大偏离且未及时调整的，银保监会可采取的监管措施包括（）。","options":["监管谈话","责令限期整改","扣减偿付能力风险管理评估得分，并限制最高得分","限制或停止资本补充工具发行"],"answer":["A","B","C","D"],"explanation":"依据第三十二条，可采取上述四项措施及其他必要的监管措施。","difficulty":2,"type":"concept","source":"core"},{"id":"14-M10","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"下列关于资本规划实施和运用的说法，正确的有（）。","options":["保险公司应按照资本规划进行资本补充、资本运用，加强资本管理，提高资本使用效率","公司战略目标、发展规划应当与资本规划相协调","应将资本规划作为风险管理的重要工具","应将资本规划的制定和执行情况作为公司考核体系的重要组成部分"],"answer":["A","B","C","D"],"explanation":"依据第二十二条至第二十五条，四项说法均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"14-X-S01","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"依据《保险公司偿付能力监管规则第14号：资本规划》，保险公司应当于每年何时之前向银保监会报送资本规划？","options":["3月31日","5月31日","6月30日","12月31日"],"answer":"B","explanation":"保险公司应当于每年5月31日前向银保监会报送资本规划。","difficulty":1,"type":"concept","source":"extra"},{"id":"14-X-S02","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"依据第14号规则，保险公司资本规划的编制周期要求是？","options":["每年滚动编制未来一年资本规划","每年滚动编制未来三年资本规划","每年滚动编制未来五年资本规划","每三年滚动编制一次未来三年规划"],"answer":"B","explanation":"保险公司每年应当滚动编制未来三年的资本规划。","difficulty":1,"type":"concept","source":"extra"},{"id":"14-X-S03","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"某保险公司因董事会审议通过调整资本规划，依据第14号规则，调整后的资本规划应当在何时报送银保监会？","options":["经董事会审议批准后5个工作日内","经董事会审议批准后10个工作日内","经董事会审议批准后15个工作日内","经股东（大）会审议批准后10个工作日内"],"answer":"B","explanation":"第二十七条规定调整资本规划的，应当经董事会审议批准后10个工作日内向银保监会报送调整后的资本规划。","difficulty":2,"type":"scenario","source":"extra"},{"id":"14-X-S04","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"某财产险公司在制定下年度资本规划时，依据第14号规则，下列哪项措施属于外源性资本补充？","options":["优化产品结构","发行资本补充工具","提升盈利能力","制定合理的利润分配政策"],"answer":"B","explanation":"外源性资本补充措施包括增资扩股、发行资本补充工具、保单责任证券化、再保险、符合监管规定的其他资本工具等；其余三项均属于内源性资本补充措施。","difficulty":2,"type":"scenario","source":"extra"},{"id":"14-X-S05","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"依据第14号规则，保险公司设定资本规划的不利情景时，至少应当考虑的不利变化因素有（  ）项。","options":["3项","4项","5项","6项"],"answer":"C","explanation":"不利情景设置至少考虑五项因素：业务发展的不利变化、资产配置的调整、投资收益率的不利波动、费用假设的不利变化、责任准备金评估折现率曲线的不利变化。","difficulty":2,"type":"calc","source":"extra"},{"id":"14-X-S06","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"依据第14号规则，保险公司设定资本管理目标时至少应当考虑（  ）方面因素。","options":["2方面","3方面","4方面","5方面"],"answer":"B","explanation":"设定资本管理目标应当至少考虑三方面因素：外部环境（外部经济环境、法律政策环境）、公司发展战略（业务发展规划、风险管理状况、风险偏好）、资本补充的可行性和可持续性。","difficulty":2,"type":"calc","source":"extra"},{"id":"14-X-S07","rule_no":14,"rule_title":"资本规划","qtype":"single","q":"依据第14号规则，关于资本规划的审议批准程序，下列说法正确的是？","options":["经高级管理层批准即可","仅需董事会审议批准","经董事会批准并经股东（大）会审议","经股东（大）会审议批准即可"],"answer":"C","explanation":"资本规划应当经董事会批准并经股东（大）会审议，并报送银保监会。","difficulty":3,"type":"concept","source":"extra"},{"id":"14-X-M01","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"依据第14号规则，下列属于内源性资本补充措施的有？","options":["提升盈利能力","制定合理的利润分配政策","增资扩股","优化产品结构"],"answer":["A","B","D"],"explanation":"内源性资本补充措施包括提升盈利能力、制定合理的利润分配政策、优化产品结构、优化资产结构、提升风险管理能力等；增资扩股属于外源性资本补充措施。","difficulty":2,"type":"concept","source":"extra"},{"id":"14-X-M02","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"依据第14号规则，保险公司在设定不利情景时，至少应当考虑下列哪些不利变化因素？","options":["投资收益率的不利波动","业务发展的不利变化","资产配置的调整","费用假设的不利变化"],"answer":["A","B","C","D"],"explanation":"不利情景设置至少考虑五项因素：业务发展的不利变化、资产配置的调整、投资收益率的不利波动、费用假设的不利变化、责任准备金评估折现率曲线的不利变化。题中所列四项均为规定内容。","difficulty":2,"type":"scenario","source":"extra"},{"id":"14-X-M03","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"关于资本规划与第10号（压力测试）、第12号（风险管理要求与评估）规则的关系，下列说法符合第14号规则的有？","options":["基本情景参数和假设应当与第10号规则保持一致","不利情景可参照第10号规则的测试程序评估未来三年偿付能力","银保监会依据第12号规则和本规则对资本规划的编制、报送和实施进行评估","资本规划评估完全独立于偿付能力风险管理要求与评估"],"answer":["A","B","C"],"explanation":"银保监会依据《保险公司偿付能力监管规则第12号：偿付能力风险管理要求与评估》和本规则对资本规划进行评估，因此D项错误；其余各项均符合第14号规则。","difficulty":3,"type":"cross","source":"extra"},{"id":"14-X-M04","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"依据第14号规则，对未按规定报送资本规划、编制不符合规定或实施过程中重大偏离且未及时调整的保险公司，银保监会可采取的监管措施包括？","options":["监管谈话","责令限期整改","限制或停止资本补充工具发行","扣减偿付能力风险管理评估得分并限制最高得分"],"answer":["A","B","C","D"],"explanation":"第14号规则规定的监管措施包括监管谈话、责令限期整改、扣减偿付能力风险管理评估得分并限制最高得分、限制或停止资本补充工具发行等措施，四项均为规定内容。","difficulty":3,"type":"concept","source":"extra"},{"id":"14-X-M05","rule_no":14,"rule_title":"资本规划","qtype":"multi","q":"依据第14号规则，资本规划至少应当包括（  ）项内容，下列选项中数字与内容对应关系正确的有？","options":["资本管理目标","资本需求评估","资本补充方案","应急预案"],"answer":["A","B","C","D"],"explanation":"资本规划至少包括六项内容：资本管理目标、资本规划制定依据、资本需求评估、资本补充方案、上一年度资本规划执行情况分析、应急预案。题中所列四项均为其中内容。","difficulty":1,"type":"calc","source":"extra"},{"id":"15-S01","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"制定保险公司偿付能力监管规则第15号的目的是（）。","options":["规范保险公司偿付能力信息公开披露行为，建立健全偿付能力市场约束机制","加强偿付能力信息交流，发挥相关方的监督作用","规范保险公司偿付能力报告的编制和报送","明确保险公司风险综合评级的分类标准"],"answer":"A","explanation":"依据第15号规则第一条，为规范保险公司偿付能力信息公开披露行为，建立健全保险公司偿付能力市场约束机制，制定本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S02","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"本规则所称保险公司不包括（）。","options":["依法在境内设立的经营商业保险业务的保险公司","外国保险公司分公司","相互保险组织","政策性保险公司"],"answer":"D","explanation":"依据第三条，保险公司指依法在境内设立的经营商业保险业务的保险公司和外国保险公司分公司，不包括政策性保险公司。相互保险组织依第二十九条适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S03","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司董事会对偿付能力信息公开披露承担的责任是（）。","options":["主要责任","最终责任","连带责任","监督管理责任"],"answer":"B","explanation":"依据第五条，保险公司董事会对偿付能力信息公开披露负最终责任。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S04","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"下列哪项不属于保险公司公开披露偿付能力信息应遵循的原则？（）","options":["充分性原则","谨慎性原则","公平性原则","可理解性原则"],"answer":"B","explanation":"依据第四条，披露原则为充分性、及时性、真实性、可理解性和公平性五项，不包括谨慎性原则。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S05","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司偿付能力季度报告摘要中，保险公司应当按照第18号规则披露的内容是第（）项至第（九）项。","options":["（一）","（二）","（三）","（四）"],"answer":"A","explanation":"依据第八条，保险公司应当按照《保险公司偿付能力监管规则第18号：偿付能力报告》披露第（一）项至第（九）项的内容。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S06","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司在披露董事会和管理层声明信息时，不需披露第18号规则第十三条所要求的（）。","options":["公司基本信息","签字、盖章等内容","财务数据","重大事项说明"],"answer":"B","explanation":"依据第八条，披露董事会和管理层声明时，不需披露第18号规则第十三条所要求的签字、盖章等内容。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S07","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"自保公司披露偿付能力季度报告摘要时，不须披露的部分是（）。","options":["公司信息","基本情况","重大事项","实际资本"],"answer":"C","explanation":"依据第八条，自保公司应披露第（一）至（四）项、第（六）项、第（十）项、第（十一）项，即不含重大事项（第七项）、风险管理能力（第五项）等内容。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S08","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"非上市保险公司应当在每季度结束后（）日内披露偿付能力季度报告摘要。","options":["15日","25日","30日","45日"],"answer":"C","explanation":"依据第十一条，非上市保险公司应当在每季度结束后30日内披露偿付能力季度报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S09","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"上市保险公司及其子公司披露第2季度偿付能力季度报告摘要的时间是（）。","options":["第2季度结束后30日内","与半年度财务报告同时","第2季度结束后15日内","与年度财务报告同时"],"answer":"B","explanation":"依据第十一条，上市保险公司及其子公司在披露半年度财务报告和年度财务报告的同时，分别披露第2季度和第4季度的偿付能力季度报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S10","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司应当披露偿付能力季度报告摘要的法定网站是（）。","options":["公司官方网站和银保监会网站","公司官方网站和中国保险行业协会网站","仅公司官方网站","公司官方网站和证券交易所网站"],"answer":"B","explanation":"依据第十二条，保险公司应当在公司官方网站和中国保险行业协会网站上披露偿付能力季度报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S11","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"统一披露保险公司偿付能力季度报告摘要的专栏设立在（）。","options":["银保监会官方网站上","中国保险行业协会官方网站上","中国银保行业协会官方网站上","各公司官方网站上"],"answer":"B","explanation":"依据第十二条，中国保险行业协会应当在官方网站上设立专栏，统一披露保险公司偿付能力季度报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S12","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司经审计的第4季度偿付能力信息存在重大变动的，应当自审计报告出具之日起（）日内发布补充信息。","options":["5日","10日","15日","30日"],"answer":"B","explanation":"依据第十三条，存在重大变动等情况的，应当自审计报告出具之日起10日内发布补充信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S13","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"审计后的核心偿付能力充足率或综合偿付能力充足率变动超过（）个百分点时，保险公司应发布补充信息。","options":["1个","2个","3个","5个"],"answer":"C","explanation":"依据第十三条第（三）项，审计后的核心或综合偿付能力充足率变动超过3个百分点的，应当发布补充信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S14","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"审计后的实际资本或最低资本的变动比例超过（）时，保险公司应发布补充信息。","options":["0.5%","1%","3%","5%"],"answer":"B","explanation":"依据第十三条第（四）项，审计后实际资本或最低资本的变动比例（审计后金额－审计前金额）÷审计前金额超过1%的，应发布补充信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S15","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司不能按时公开披露偿付能力信息的，延迟披露的时间不得超过（）。","options":["10日","15日","30日","60日"],"answer":"B","explanation":"依据第十四条，延迟披露的时间不得超过15日。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S16","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"偿付能力季度报告摘要在保险公司网站上应当保留至少（）。","options":["3年","5年","10年","永久"],"answer":"C","explanation":"依据第十五条，偿付能力季度报告摘要在保险公司网站上应当保留至少10年。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S17","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"在可能影响保险消费者首次投保或续保决策的场景下，保险公司应在投保提示书等文件的显著位置披露公司最近季度的（）。","options":["核心偿付能力充足率和风险综合评级","综合偿付能力充足率和风险综合评级","实际资本和最低资本","核心偿付能力充足率和综合偿付能力充足率"],"answer":"B","explanation":"依据第十六条，应披露公司最近季度的综合偿付能力充足率、风险综合评级等信息，并说明充足率是否达到监管要求。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S18","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司为开展保险业务参加投标时，应列示公司最近（）个季度的核心偿付能力充足率和综合偿付能力充足率。","options":["一","二","四","十二"],"answer":"C","explanation":"依据第十七条，应单独列示公司最近四个季度的核心偿付能力充足率和综合偿付能力充足率、最近一期的风险综合评级等信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S19","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"关于向股东发送偿付能力季度报告摘要，下列说法正确的是（）。","options":["所有保险公司均只需向持股5%以上的股东发送","非上市保险公司应当向所有股东发送","上市保险公司应当向所有股东发送","保险公司可选择是否向股东发送"],"answer":"B","explanation":"依据第十八条，在官网发布摘要的同时，非上市保险公司应当向所有股东、上市保险公司应当向持股占5%以上的股东发送偿付能力季度报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"15-S20","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"保险公司进行业绩发布、证券发行等路演活动时，应当设置（）。","options":["偿付能力信息应询环节","专家答疑环节","媒体问答环节","投资者接待环节"],"answer":"A","explanation":"依据第二十一条，保险公司进行业绩发布、证券发行等路演活动时，应当设置偿付能力信息的应询环节。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M01","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司公开披露偿付能力信息应当遵循的原则包括（）。","options":["充分性原则","及时性原则","真实性原则","公平性原则"],"answer":["A","B","C","D"],"explanation":"依据第四条，披露原则包括充分性、及时性、真实性、可理解性、公平性五项原则。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M02","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司偿付能力季度报告摘要的组成部分包括（）。","options":["公司信息","风险管理能力","管理层分析与讨论","外部机构意见"],"answer":["A","B","C","D"],"explanation":"依据第八条，摘要由公司信息、董事会和管理层声明、基本情况、主要指标、风险管理能力、风险综合评级、重大事项、管理层分析与讨论、外部机构意见、实际资本、最低资本十一部分组成。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M03","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司在偿付能力季度报告摘要的实际资本部分应披露的项目包括（）。","options":["核心一级、核心二级、附属一级、附属二级资本金额","核心一级资本调整表及各调整项目","认可资产","认可负债"],"answer":["A","B","C","D"],"explanation":"依据第九条，实际资本部分应披露各级资本金额及核心一级资本调整表、认可资产、认可负债的本季度（末）数和上季度（末）数。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M04","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司在偿付能力季度报告摘要的最低资本部分应披露的项目包括（）。","options":["保险风险最低资本及各子类风险的最低资本","市场风险最低资本及各子类风险的最低资本","信用风险最低资本及各子类风险的最低资本","控制风险最低资本"],"answer":["A","B","C","D"],"explanation":"依据第十条，最低资本部分应披露最低资本、保险风险、市场风险、信用风险各子类最低资本、可资本化风险最低资本、控制风险最低资本及附加资本等内容。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M05","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司在经审计的第4季度偿付能力信息存在下列哪些情况时，应当自审计报告出具之日起10日内发布补充信息？（）","options":["审计机构出具了除无保留意见外的审计报告","审计后的核心或综合偿付能力充足率不达标","审计后的核心或综合偿付能力充足率变动超过3个百分点","审计后的实际资本或最低资本变动比例超过1%"],"answer":["A","B","C","D"],"explanation":"依据第十三条，上述四项及银保监会认为需要披露的其他情况，均应在审计报告出具之日起10日内发布补充信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M06","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"关于保险公司日常披露义务，下列说法正确的有（）。","options":["向保险消费者提交的分红保险红利通知书应披露最近季度综合偿付能力充足率","可通过在显著位置设置二维码、网址链接等形式披露偿付能力信息","向股东公布利润分配方案时应同时公布该方案对公司偿付能力充足率的影响","年度股东大会应当设置偿付能力说明环节"],"answer":["A","B","C","D"],"explanation":"依据第十六条、第十八条，投保提示书、红利通知书、保单状态报告等应披露偿付能力信息，可设二维码或网址链接；公布利润分配方案时同时公布影响；年度股东大会设置偿付能力说明环节。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M07","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"保险公司进行增资、股权变更、债券发行等交易时，下列说法正确的有（）。","options":["非上市公司应向所有股东书面说明交易前四个季度的偿付能力充足率","上市公司应向持股占比5%以上的股东书面说明交易对偿付能力充足率的潜在影响","应向潜在投资方书面说明最近四个季度的偿付能力充足率","应向债权人书面说明该项交易对偿付能力充足率的潜在影响"],"answer":["A","B","C","D"],"explanation":"依据第十八条、第十九条，进行增资、股权变更、债券发行等交易时，应向股东（非上市为所有股东、上市为持股5%以上股东）及潜在投资方或债权人书面说明最近四个季度偿付能力充足率及交易潜在影响。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M08","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"关于保险公司信息披露的管理与监督，下列说法正确的有（）。","options":["应建立覆盖信息生成、采集、审核和披露各环节的内部控制制度","所披露信息仅限于本公司信息，不得与其他保险公司的信息进行对比","应建立舆情监测机制和应急预案，防范声誉风险","银保监会认为信息可能存在问题的，应要求公司进行复核"],"answer":["A","B","C","D"],"explanation":"依据第二十二条至第二十五条，内控制度覆盖生成、采集、审核、披露环节；不得与其他公司对比；建立舆情监测和应急预案；监管认为信息可能存在问题的应要求复核。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M09","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"截至规定披露时限未完成复核或复核结果未获得银保监会认可的，保险公司应采取的措施包括（）。","options":["暂缓披露偿付能力季度报告摘要","在官方网站上发布暂缓披露的信息","立即停止一切信息披露活动","说明本公司正根据监管部门要求对偿付能力信息进行复核"],"answer":["A","B","D"],"explanation":"依据第二十五条，应暂缓披露并在官网发布本公司正根据监管部门要求对偿付能力信息进行复核、暂缓披露偿付能力季度报告摘要的信息。","difficulty":2,"type":"concept","source":"core"},{"id":"15-M10","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"关于本规则的适用与其他规定，下列说法正确的有（）。","options":["相互保险组织适用本规则","本规则由银保监会负责解释和修订","本规则是对偿付能力信息公开披露的最低要求","银保监会可以根据审慎监管和金融稳定需要豁免保险公司的披露义务"],"answer":["A","B","C","D"],"explanation":"依据第二十七条至第三十条，本规则是最低要求，鼓励更高标准披露；银保监会可豁免披露义务或调整内容、频率和形式；相互保险组织适用；本规则由银保监会负责解释和修订。","difficulty":2,"type":"concept","source":"core"},{"id":"15-X-S01","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据《保险公司偿付能力监管规则第15号：偿付能力信息公开披露》，非上市保险公司应当在每季度结束后多少日内披露偿付能力季度报告摘要？","options":["10日","15日","30日","60日"],"answer":"C","explanation":"非上市保险公司应当在每季度结束后30日内披露偿付能力季度报告摘要。","difficulty":1,"type":"concept","source":"extra"},{"id":"15-X-S02","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据第15号规则，偿付能力季度报告摘要在保险公司网站上应当至少保留多少年？","options":["3年","5年","10年","15年"],"answer":"C","explanation":"偿付能力季度报告摘要在保险公司网站上应当保留至少10年。","difficulty":1,"type":"concept","source":"extra"},{"id":"15-X-S03","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据第15号规则，保险公司不能按时披露偿付能力季度报告摘要的，延迟披露时间最长不得超过多少日？","options":["5日","10日","15日","30日"],"answer":"C","explanation":"不能按时披露的，延迟披露时间不得超过15日；并应在规定披露期限之前在公司官网首页公布原因及预计披露时间。","difficulty":2,"type":"calc","source":"extra"},{"id":"15-X-S04","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"某保险公司审计前实际资本为100亿元，审计后实际资本为101.5亿元，则实际资本变动比例为多少？是否触发补充信息披露？","options":["1.5%，触发","1.5%，不触发","1.0%，不触发","1.2%，触发"],"answer":"A","explanation":"变动比例=（审计后金额-审计前金额）÷审计前金额=（101.5-100）÷100=1.5%，超过1%，依据规则应当发布补充信息。","difficulty":2,"type":"calc","source":"extra"},{"id":"15-X-S05","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据第15号规则，某上市保险公司在第2季度结束后披露偿付能力季度报告摘要的时限是？","options":["第2季度结束后30日内","与半年度财务报告同时披露","第2季度结束后60日内","与年度报告同时披露"],"answer":"B","explanation":"上市保险公司第2、4季度摘要应与半年度、年度财务报告同时披露；第1、3季度则在结束后30日内披露。","difficulty":2,"type":"scenario","source":"extra"},{"id":"15-X-S06","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据第15号规则，自保公司偿付能力季度报告摘要仅需披露的部分包括？","options":["第（一）至（四）项、第（六）项、第（十）项和第（十一）项","第（一）至（五）项、第（七）项","第（一）至（九）项全部内容","第（一）至（三）项、第（十）项"],"answer":"A","explanation":"自保公司仅披露第（一）至（四）项、第（六）项、第（十）项和第（十一）项，其他项目可豁免。","difficulty":2,"type":"scenario","source":"extra"},{"id":"15-X-S07","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"single","q":"依据第15号规则与第18号规则的衔接，保险公司披露董事会和管理层声明时，下列处理符合规定的是？","options":["需同时披露第18号规则第十三条所要求的签字、盖章等内容","不需披露第18号规则第十三条所要求的签字、盖章等内容","须由全体董事逐项签字","须由银保监会签字盖章确认"],"answer":"B","explanation":"披露董事会和管理层声明时，不需披露第18号规则第十三条所要求的签字、盖章等内容；其余签字盖章由公司按第18号规则要求另行留存。","difficulty":3,"type":"cross","source":"extra"},{"id":"15-X-M01","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"依据第15号规则，偿付能力信息公开披露的五项原则包括？","options":["充分性、及时性","真实性、可理解性","公平性","谨慎性、相关性"],"answer":["A","B","C"],"explanation":"披露五原则为充分性、及时性、真实性、可理解性、公平性；谨慎性、相关性为会计信息质量要求，并非本规则披露原则。","difficulty":1,"type":"concept","source":"extra"},{"id":"15-X-M02","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"依据第15号规则，偿付能力季度报告摘要的组成部分包括下列哪些？","options":["公司信息、董事会和管理层声明","基本情况、主要指标、风险管理能力","风险综合评级、重大事项","实际资本、最低资本"],"answer":["A","B","C","D"],"explanation":"摘要由十一部分组成：公司信息、董事会和管理层声明、基本情况、主要指标、风险管理能力、风险综合评级（分类监管）、重大事项、管理层分析与讨论、外部机构意见、实际资本、最低资本。题中所列均属其中。","difficulty":2,"type":"concept","source":"extra"},{"id":"15-X-M03","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"依据第15号规则，实际资本包括下列哪些级次？","options":["核心一级资本","核心二级资本","附属一级资本","附属二级资本"],"answer":["A","B","C","D"],"explanation":"实际资本包括核心一级资本、核心二级资本、附属一级资本、附属二级资本共四个级次。附加资本如不适用，则以零值披露。","difficulty":2,"type":"calc","source":"extra"},{"id":"15-X-M04","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"依据第15号规则，保险公司日常披露所适用的场景包括下列哪些？","options":["投保决策时","投标时","股东沟通时","路演活动时"],"answer":["A","B","C","D"],"explanation":"第三章规定的日常披露场景包括投保决策、投标、股东沟通、交易说明、信息应询、路演等；题中所列四项均属于规定场景。","difficulty":2,"type":"scenario","source":"extra"},{"id":"15-X-M05","rule_no":15,"rule_title":"偿付能力信息公开披露","qtype":"multi","q":"依据第15号规则，保险公司应当向股东发送偿付能力季度报告摘要的要求包括？","options":["上市公司向持股5%以上的股东发送","上市公司向所有股东发送","非上市公司向所有股东发送","非上市公司向持股5%以上的股东发送"],"answer":["A","C"],"explanation":"上市公司向持股占5%以上的股东发送季度报告摘要；非上市公司向所有股东发送。","difficulty":2,"type":"concept","source":"extra"},{"id":"16-S01","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"制定保险公司偿付能力监管规则第16号的主要目的不包括（）。","options":["建立健全偿付能力市场约束机制","加强偿付能力信息交流","有效防范风险","确定保险公司的最低资本要求"],"answer":"D","explanation":"依据第16号规则第一条，制定目的是建立健全偿付能力市场约束机制、加强信息交流、发挥相关方监督作用、有效防范风险，不含确定最低资本要求。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S02","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"本规则所称相关方不包括（）。","options":["保险消费者","信用评级机构","保险公司董事","新闻媒体"],"answer":"C","explanation":"依据第二条，相关方包括保险消费者、保险公司股东、审计机构、信用评级机构、行业分析师、研究机构、政府部门和新闻媒体等，不包括保险公司董事。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S03","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会与相关方建立的偿付能力信息交流机制的特征是（）。","options":["定期、单向、规范","持续、双向、互动","临时、随机、灵活","定期、双向、封闭"],"answer":"B","explanation":"依据第三条，银保监会与相关方建立持续、双向、互动的偿付能力信息交流机制。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S04","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会对外通报保险业偿付能力充足率和保险机构风险综合评级总体情况的频率是（）。","options":["每月","每季度","每半年","每年"],"answer":"B","explanation":"依据第四条，银保监会每季度对外通报保险业偿付能力充足率和保险机构风险综合评级的总体情况。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S05","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会发布偿付能力监管工作信息的频率是（）。","options":["每季度一次","每半年一次","每年一次","每两年一次"],"answer":"B","explanation":"依据第五条，银保监会每半年发布一次偿付能力监管工作信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S06","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"原则上，银保监会应当在每年（）前发布上半年的偿付能力监管工作信息。","options":["6月30日","9月30日","8月31日","7月31日"],"answer":"B","explanation":"依据第五条，原则上每年9月30日前发布上半年的偿付能力监管工作信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S07","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"原则上，银保监会应当在每年3月31日前发布（）的偿付能力监管工作信息。","options":["当年第一季度","上一年度","上一年下半年","当年上半年"],"answer":"B","explanation":"依据第五条，原则上每年3月31日前发布上一年度的偿付能力监管工作信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S08","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会发布的偿付能力监管工作信息中，关于保险业偿付能力总体状况的内容应当包括（）。","options":["各家公司的详细财务报表","风险综合评级情况","偿付能力报告全文","公司内部偿付能力管理信息"],"answer":"B","explanation":"依据第六条第（一）项，监管工作信息包括保险业偿付能力（包括风险综合评级）的总体状况。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S09","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"下列哪项不属于银保监会发布的偿付能力监管工作信息内容？（）","options":["保险业偿付能力的总体状况","偿付能力监管制度建设情况","采取的监管措施以及下一步工作重点","保险公司偿付能力季度报告摘要"],"answer":"D","explanation":"依据第六条，监管工作信息包括保险业偿付能力总体状况、监管工作情况（制度建设、监管措施、下一步工作重点）及需要发布的其他监管工作信息，季度报告摘要是保险公司披露的内容。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S10","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会定期发布偿付能力监管工作信息的主要渠道是（）。","options":["官方网站","电视广告","保险公司网站","行业协会网站"],"answer":"A","explanation":"依据第七条，银保监会在官方网站上定期发布偿付能力监管工作信息，也可通过官方公众号、新闻发布会、新闻通气会等方式发布。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S11","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会临时发布偿付能力监管工作信息的依据是（）。","options":["保险公司的申请","监管工作需要","行业协会的建议","相关方的一致要求"],"answer":"B","explanation":"依据第八条，银保监会根据监管工作需要，可以通过官方网站、官方公众号、新闻发布会、新闻通气会、接受采访等方式临时发布偿付能力监管工作信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S12","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会向保险消费者介绍偿付能力监管工作情况、听取意见和建议可采用的方式不包括（）。","options":["座谈会","问卷调查","访谈","强制信息披露"],"answer":"D","explanation":"依据第九条，银保监会可根据监管工作需要，通过座谈会、问卷调查、访谈等方式向保险消费者介绍监管工作情况。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S13","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会建立健全与保险公司股东之间的偿付能力信息交流机制的方式是（）。","options":["培训、情况通报","行政处罚、约谈","媒体曝光、公开批评","现场检查、接管"],"answer":"A","explanation":"依据第十条，银保监会通过培训、情况通报等方式建立健全与保险公司股东之间的偿付能力信息交流机制。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S14","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"对于存在重大偿付能力风险的公司，银保监会应当向（）通报有关情况。","options":["保险消费者","保险公司股东","新闻媒体","潜在投保人"],"answer":"B","explanation":"依据第十条第（三）项，对于存在重大偿付能力风险或风险管理存在重大缺陷的公司，银保监会向保险公司股东通报有关情况。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S15","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会与信用评级机构、行业分析师、研究机构建立的交流机制类型是（）。","options":["临时交流机制","定期交流机制","年度交流机制","单向交流机制"],"answer":"B","explanation":"依据第十一条，银保监会与信用评级机构、行业分析师、研究机构建立定期交流机制，通过座谈会、新闻发布会、访谈等方式进行交流。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S16","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会与财政部、人民银行、证监会等相关政府部门建立健全的机制是（）。","options":["偿付能力信息的交流共享和监管协作机制","联合检查机制","统一披露机制","责任追究机制"],"answer":"A","explanation":"依据第十三条，银保监会与财政部、人民银行、证监会等相关政府部门建立健全偿付能力信息的交流共享和监管协作机制。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S17","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监会与新闻媒体通报偿付能力监管工作情况、交换意见的频率至少是（）。","options":["每季度","每半年","每年","每两年"],"answer":"B","explanation":"依据第十四条，银保监会与新闻媒体建立交流机制，至少每半年通过新闻发布会、新闻通气会、媒体采访等方式通报偿付能力监管工作情况。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S18","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"本规则由（）负责解释和修订。","options":["中国人民银行","财政部","银保监会","国务院"],"answer":"C","explanation":"依据第十六条，本规则由银保监会负责解释和修订。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S19","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"本规则第一次发布的时间是（）。","options":["2015年2月13日","2016年2月13日","2021年12月30日","2015年12月30日"],"answer":"A","explanation":"依据第十七条，本规则于2015年2月13日第一次发布，于2021年12月30日修订发布。","difficulty":2,"type":"concept","source":"core"},{"id":"16-S20","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"银保监局建立与市场相关方的偿付能力信息交流机制时，可参照本规则的条款范围是（）。","options":["第一条至第八条","第九条至第十四条","第一条至第十七条","第十五条至第十七条"],"answer":"B","explanation":"依据第十五条，银保监局可参照本规则第九条至第十四条规定，结合辖区实际，建立与保险公司股东、中介机构和消费者等市场相关方的偿付能力信息交流机制。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M01","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"本规则所称相关方包括（）。","options":["保险消费者和保险公司股东","审计机构和信用评级机构","行业分析师和研究机构","政府部门和新闻媒体"],"answer":["A","B","C","D"],"explanation":"依据第二条，相关方包括保险消费者、保险公司股东、审计机构、信用评级机构、行业分析师、研究机构、政府部门和新闻媒体等。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M02","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会发布的偿付能力监管工作信息包括（）。","options":["保险业偿付能力（包括风险综合评级）的总体状况","偿付能力监管制度建设情况","采取的监管措施","下一步工作重点"],"answer":["A","B","C","D"],"explanation":"依据第六条，监管工作信息包括保险业偿付能力总体状况、监管工作情况（制度建设、监管措施、下一步工作重点）以及需要发布的其他监管工作信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M03","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会发布偿付能力监管工作信息的方式包括（）。","options":["官方网站","官方公众号","新闻发布会","新闻通气会"],"answer":["A","B","C","D"],"explanation":"依据第七条，银保监会在官方网站上定期发布偿付能力监管工作信息，也可通过官方公众号、新闻发布会、新闻通气会等方式发布。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M04","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"信用评级机构、行业分析师、研究机构发现下列哪些事项时，有权向银保监会报告？（）","options":["国内外宏观经济环境发生变化，可能对保险业偿付能力造成重大影响","保险公司存在重大偿付能力风险","保险公司风险管理存在重大缺陷","其他可能危及保险业、保险公司偿付能力的事项"],"answer":["A","B","C","D"],"explanation":"依据第十二条，上述四类事项均属于有权向银保监会报告的范围。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M05","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会通过培训、情况通报等方式与保险公司股东建立的偿付能力信息交流机制包括（）。","options":["对保险公司股东进行偿付能力相关的培训","不定期向保险公司股东通报偿付能力监管工作有关情况","对存在重大偿付能力风险的公司向股东通报有关情况","每周向股东公布偿付能力数据"],"answer":["A","B","C"],"explanation":"依据第十条，交流机制包括对股东培训、不定期通报监管工作情况、对重大风险或重大缺陷公司向股东通报；每周公布数据无此规定。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M06","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会与信用评级机构、行业分析师、研究机构进行偿付能力信息交流的方式包括（）。","options":["座谈会","新闻发布会","访谈","问卷调查"],"answer":["A","B","C"],"explanation":"依据第十一条，通过座谈会、新闻发布会、访谈等方式就偿付能力信息进行交流，问卷调查是面向保险消费者的方式。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M07","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会与新闻媒体交流的方式包括（）。","options":["新闻发布会","新闻通气会","媒体采访","接受采访"],"answer":["A","B","C"],"explanation":"依据第十四条，至少每半年通过新闻发布会、新闻通气会、媒体采访等方式通报偿付能力监管工作情况，交换意见。接受采访是银保监会临时发布信息的方式之一，而非与新闻媒体交流机制的方式。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M08","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监局可参照本规则建立偿付能力信息交流机制的市场相关方包括（）。","options":["保险公司股东","中介机构","消费者","外国保险监管机构"],"answer":["A","B","C"],"explanation":"依据第十五条，银保监局结合辖区实际，建立与保险公司股东、中介机构和消费者等市场相关方的偿付能力信息交流机制。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M09","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"关于偿付能力信息交流的时间要求，下列说法正确的有（）。","options":["每季度对外通报保险业偿付能力充足率总体情况","每半年发布一次偿付能力监管工作信息","每年9月30日前发布上半年的监管工作信息","每年3月31日前发布上一年度的监管工作信息"],"answer":["A","B","C","D"],"explanation":"依据第四条、第五条，季度通报充足率和风险综合评级总体情况；每半年发布一次监管工作信息，分别于9月30日、3月31日前发布上半年和上一年度信息。","difficulty":2,"type":"concept","source":"core"},{"id":"16-M10","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"银保监会可根据监管工作需要，向保险消费者介绍偿付能力监管工作情况的方式包括（）。","options":["座谈会","问卷调查","访谈","接管"],"answer":["A","B","C"],"explanation":"依据第九条，通过座谈会、问卷调查、访谈等方式向保险消费者介绍监管工作情况，听取意见和建议；接管属于监管措施而非信息交流方式。","difficulty":2,"type":"concept","source":"core"},{"id":"16-X-S01","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据《保险公司偿付能力监管规则第16号：偿付能力信息交流》，银保监会对保险业偿付能力充足率和风险综合评级总体情况的对外通报频率是？","options":["每月","每季度","每半年","每年"],"answer":"B","explanation":"银保监会每季度对外通报保险业偿付能力充足率和保险机构风险综合评级的总体情况；每半年发布一次偿付能力监管工作信息。","difficulty":1,"type":"concept","source":"extra"},{"id":"16-X-S02","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，下列哪一类主体不属于「相关方」范围？","options":["保险消费者和股东","审计机构和信用评级机构","行业分析师和研究机构","保险公司的客户和合作伙伴"],"answer":"D","explanation":"相关方包括八类主体：保险消费者、保险公司股东、审计机构、信用评级机构、行业分析师、研究机构、政府部门和新闻媒体等。保险公司的客户和合作伙伴不在此列。","difficulty":1,"type":"concept","source":"extra"},{"id":"16-X-S03","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，银保监会每年应当对外发布偿付能力监管工作信息的次数为？","options":["1次","2次","4次","12次"],"answer":"B","explanation":"银保监会每半年发布一次偿付能力监管工作信息，每年共2次。原则上3月31日前发布上一年度、9月30日前发布上半年。","difficulty":2,"type":"calc","source":"extra"},{"id":"16-X-S04","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，银保监会原则上应当于每年何时之前发布上一年度的偿付能力监管工作信息？","options":["3月31日","6月30日","9月30日","12月31日"],"answer":"A","explanation":"原则上每年3月31日前发布上一年度的偿付能力监管工作信息；9月30日前发布上半年的偿付能力监管工作信息。","difficulty":2,"type":"concept","source":"extra"},{"id":"16-X-S05","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，银保监会与新闻媒体通过新闻发布会、新闻通气会等方式通报偿付能力监管工作情况的最低频率是？","options":["每月","每季度","每半年","每年"],"answer":"C","explanation":"银保监会与新闻媒体至少每半年通过新闻发布会、新闻通气会、媒体采访等方式通报偿付能力监管工作情况。","difficulty":2,"type":"scenario","source":"extra"},{"id":"16-X-S06","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，银保监局可参照本规则建立与市场相关方交流机制的具体条款范围是？","options":["第七条至第十条","第八条至第十三条","第九条至第十四条","第十条至第十五条"],"answer":"C","explanation":"银保监局参照本规则第九条至第十四条规定，结合辖区实际建立与市场相关方的交流机制。","difficulty":2,"type":"calc","source":"extra"},{"id":"16-X-S07","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"single","q":"依据第16号规则，关于「偿付能力监管工作信息」与「季度通报」两类信息交流内容的区别，下列说法正确的是？","options":["季度通报的内容与监管工作信息完全一致","季度通报的是行业总体情况，监管工作信息包括监管制度建设等内容","监管工作信息每季度发布一次","季度通报内容须经保险公司同意"],"answer":"B","explanation":"季度通报的是行业偿付能力充足率和风险综合评级总体情况；监管工作信息每半年发布一次，包括监管制度建设、监管措施及下一步工作重点等内容。","difficulty":3,"type":"cross","source":"extra"},{"id":"16-X-M01","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"依据第16号规则，「相关方」范围包括下列哪些主体？","options":["保险消费者和股东","审计机构和信用评级机构","行业分析师、研究机构和政府部门","新闻媒体"],"answer":["A","B","C","D"],"explanation":"相关方包括八类主体：保险消费者、保险公司股东、审计机构、信用评级机构、行业分析师、研究机构、政府部门和新闻媒体等。","difficulty":1,"type":"concept","source":"extra"},{"id":"16-X-M02","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"依据第16号规则，银保监会发布偿付能力监管工作信息的渠道包括？","options":["官方网站","官方公众号","新闻发布会","新闻通气会"],"answer":["A","B","C","D"],"explanation":"监管工作信息发布渠道包括官方网站、官方公众号、新闻发布会、新闻通气会等。","difficulty":2,"type":"concept","source":"extra"},{"id":"16-X-M03","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"依据第16号规则，银保监会可根据监管工作需要采取的信息交流方式包括？","options":["座谈会","问卷调查","访谈","培训"],"answer":["A","B","C","D"],"explanation":"信息交流方式包括座谈会、问卷调查、访谈、培训、情况通报等方式。","difficulty":2,"type":"scenario","source":"extra"},{"id":"16-X-M04","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"依据第16号规则，银保监会向保险公司股东通报有关情况的情形包括？","options":["公司存在重大偿付能力风险","公司风险管理存在重大缺陷","公司正常经营且无重大事项","公司发生重大理赔案件"],"answer":["A","B"],"explanation":"对存在重大偿付能力风险或风险管理存在重大缺陷的公司，银保监会向保险公司股东通报有关情况；其他情形不属于本规则规定。","difficulty":3,"type":"scenario","source":"extra"},{"id":"16-X-M05","rule_no":16,"rule_title":"偿付能力信息交流","qtype":"multi","q":"依据第16号规则，关于季度通报与半年发布的对比，下列描述正确的有？","options":["季度通报每季度一次","半年度发布每半年一次","季度通报在9月30日发布","半年度发布包括监管工作信息内容"],"answer":["A","B","D"],"explanation":"9月30日发布的是上半年的监管工作信息，并非季度通报；季度通报每季度通报行业总体情况；半年度发布监管工作信息。","difficulty":2,"type":"calc","source":"extra"},{"id":"17-S01","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"制定《保险公司偿付能力监管规则第17号：保险公司信用评级》的主要目的是（ ）。","options":["规范信用评级机构对保险公司的信用评级行为，发挥信用评级对保险公司偿付能力的市场约束作用","规定保险公司必须每年进行主体信用评级","建立保险公司的内部信用风险评级体系","对信用评级机构实行牌照准入管理"],"answer":"A","explanation":"依据第17号规则第一条，制定本规则是为规范信用评级机构对保险公司的信用评级行为，发挥信用评级对保险公司偿付能力的市场约束作用。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S02","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"本规则所称保险公司是指（ ）。","options":["依法在中华人民共和国境内设立的经营商业保险业务的保险公司和外国保险公司分公司","仅指在境内设立的中资保险公司","境内保险公司及其境外子公司","所有在境内开展业务的保险机构包括保险经纪公司"],"answer":"A","explanation":"依据第二条，本规则所称保险公司是指依法在中华人民共和国境内设立的经营商业保险业务的保险公司和外国保险公司分公司。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S03","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司信用评级包括（ ）。","options":["主体评级和债项评级","主动评级和被动评级","内部评级和外部评级","综合评级和分类评级"],"answer":"A","explanation":"依据第五条，保险公司信用评级包括主体评级和债项评级。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S04","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构从事保险公司信用评级业务，应当遵循的原则是（ ）。","options":["独立、客观、公正","审慎、稳健、合规","公平、公开、诚实守信","自愿、有偿、保密"],"answer":"A","explanation":"依据第四条，信用评级机构从事保险公司信用评级业务，应当遵循独立、客观、公正的原则。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S05","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"境内信用评级机构从事保险公司信用评级业务，最近年度末实收资本和净资产均不低于（ ）。","options":["1000万元","2000万元","5000万元","1亿元"],"answer":"B","explanation":"依据第八条第（二）项，境内信用评级机构最近年度末实收资本和净资产均不低于2000万元。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S06","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"境内信用评级机构应具备3年以上信用评级业务经验的专业人员不少于（ ）人，其中从事保险公司信用评级业务的不少于（ ）人。","options":["10人；3人","20人；3人","20人；5人","30人；5人"],"answer":"B","explanation":"依据第八条第（三）项，具备3年以上信用评级业务经验的专业人员不少于20人，其中从事保险公司信用评级的不少于3人。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S07","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"境内信用评级机构从事保险公司信用评级业务，关于诚信记录的要求是（ ）。","options":["最近1年没有重大违法违规行为","最近3年没有重大违法违规行为","最近5年没有违法违规行为","自成立以来没有受到任何行政处罚"],"answer":"B","explanation":"依据第八条第（六）项，境内信用评级机构应具有良好的诚信记录，最近3年没有重大违法违规行为。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S08","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司选聘境内信用评级机构应当采用的方式是（ ）。","options":["公开招标或邀请招标","直接委托","银保监会指定","竞争性谈判或询价"],"answer":"A","explanation":"依据第十条，保险公司应当采用公开招标或邀请招标方式选聘境内信用评级机构。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S09","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司发出投标邀请的信用评级机构不得少于（ ）家，且其中至少有（ ）家中资信用评级机构。","options":["2家；1家","3家；1家","3家；2家","5家；2家"],"answer":"B","explanation":"依据第十条，保险公司发出投标邀请的信用评级机构不得少于3家，且其中至少有1家中资信用评级机构。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S10","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司与信用评级机构签订聘用合同之日起（ ）内，应当向银保监会书面报告。","options":["5个工作日","10个工作日","15个工作日","10日"],"answer":"B","explanation":"依据第十七条，保险公司与信用评级机构签订聘用合同之日起10个工作日内，应当向银保监会书面报告。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S11","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构开展保险公司债项评级业务时，除公司总体状况外，还应当综合考虑的因素不包括（ ）。","options":["该债项的发行协议、期限","清偿顺序、转股权利","增信措施","公司股价的历史波动率"],"answer":"D","explanation":"依据第十四条，债项评级应综合考虑发行协议、期限、清偿顺序、转股权利、增信措施等特点，公司股价波动率不属于规定的考量因素。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S12","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司在境内融资、开展保险业务等需要进行信用评级的，应当聘请（ ）。","options":["境内信用评级机构","境外信用评级机构","银保监会指定的评级机构","任意一家国际三大评级机构"],"answer":"A","explanation":"依据第七条，保险公司在境内融资、开展保险业务等行为需要信用评级的，应当聘请境内信用评级机构。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S13","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构对保险公司进行信用评级时，可以向（ ）提出访谈申请。","options":["银保监会","中国人民银行","保险行业协会","被评级公司的股东大会"],"answer":"A","explanation":"依据第十二条，信用评级机构对保险公司进行信用评级时，可以向银保监会提出访谈申请，银保监会在法律法规允许范围内提供监管信息和监管意见。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S14","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构应当在信用评级有效期内持续跟踪保险公司情况，及时更新和调整评级结果。持续跟踪的内容不包括（ ）。","options":["业务发展","偿付能力","风险管理","境外关联企业高管个人婚姻状况"],"answer":"D","explanation":"依据第十五条，跟踪内容包括保险公司业务发展、偿付能力、风险管理等情况，D项不属于规定内容。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S15","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"从事保险公司信用评级业务的信用评级机构，应当向银保监会书面报送（ ）。","options":["信用等级划分标准及其含义的说明","所有被评级保险公司的原始财务资料","评级收费标准的备案文件","评级模型的源代码"],"answer":"A","explanation":"依据第十六条，信用评级机构从事保险公司信用评级业务的，应当向银保监会书面报送信用等级划分标准及其含义的说明。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S16","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司进行信用评级的，应当按照第18号规则的要求，在（ ）中披露信用评级的有关信息。","options":["偿付能力季度报告","年度信息披露公告","公司官方网站","股东大会报告"],"answer":"A","explanation":"依据第十八条，保险公司进行信用评级的，应当按照《保险公司偿付能力监管规则第18号：偿付能力报告》的要求，在偿付能力季度报告中披露信用评级的有关信息。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S17","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构发现保险公司存在重大违法违规行为时，应当（ ）。","options":["向银保监会报告","直接下调该公司评级并向社会公布","先告知被评级公司再决定是否报告","在评级报告中注明即可"],"answer":"A","explanation":"依据第二十条，信用评级机构发现保险公司存在重大违法违规行为时，应当向银保监会报告。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S18","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构存在违规行为且情节严重的，银保监会的处理措施是（ ）。","options":["不认可其评估报告","对其处以罚款","吊销其营业执照","责令保险公司永久不得聘请该机构"],"answer":"A","explanation":"依据第二十一条，信用评级机构存在所列行为时，银保监会有权责令保险公司更换信用评级机构；情节严重的，银保监会不认可其评估报告。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S19","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"下列机构中，适用《保险公司偿付能力监管规则第17号：保险公司信用评级》的是（ ）。","options":["保险集团、相互保险组织","保险代理公司","保险经纪公司","保险资产管理公司"],"answer":"A","explanation":"依据第二十二条，保险集团、相互保险组织适用本规则。","difficulty":2,"type":"concept","source":"core"},{"id":"17-S20","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"本规则第一次发布和修订发布的时间分别是（ ）。","options":["2015年2月13日；2021年12月30日","2015年2月13日；2021年12月31日","2016年1月1日；2021年12月30日","2015年2月13日；2020年12月30日"],"answer":"A","explanation":"依据第二十四条，本规则于2015年2月13日第一次发布，于2021年12月30日修订发布，施行日期另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M01","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"境内信用评级机构从事保险公司信用评级业务，应当具备的条件包括（ ）。","options":["具有境内法人资格","最近年度末实收资本和净资产均不低于2000万元","具备3年以上信用评级业务经验的专业人员不少于20人，其中从事保险公司信用评级业务的不少于3人","已向银保监会递交《配合监管承诺函》，并且评级程序已向银保监会备案"],"answer":["A","B","C","D"],"explanation":"依据第八条，以上四项均为境内信用评级机构从事保险公司信用评级业务应具备的条件，此外还包括完善的组织结构和业务质量控制制度、健全的业务制度以及良好的诚信记录。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M02","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"下列属于银保监会有权责令保险公司更换信用评级机构的情形有（ ）。","options":["向银保监会、保险公司提供虚假材料","与被评价保险公司之间存在除评级业务以外的重大利益关系，不能确保自身独立性","未经保险公司同意，将评级过程中掌握的信息向社会公布或泄露给他人","同保险公司合谋篡改评级资料或歪曲评级结果"],"answer":["A","B","C","D"],"explanation":"依据第二十一条，以上情形均属于银保监会有权责令保险公司更换信用评级机构的行为；情节严重的，银保监会不认可其评估报告。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M03","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"信用评级机构开展保险公司债项评级业务时，除公司总体状况外，还应当综合考虑该债项的（ ）等特点。","options":["发行协议","期限和清偿顺序","转股权利","增信措施"],"answer":["A","B","C","D"],"explanation":"依据第十四条，债项评级应综合考虑债项的发行协议、期限、清偿顺序、转股权利、增信措施等方面的特点，确定评级结果。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M04","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"保险公司聘请信用评级机构开展评级业务，应当按照双方约定提供的材料包括（ ）。","options":["财务报告","偿付能力报告","业务发展规划","风险管理报告"],"answer":["A","B","C","D"],"explanation":"依据第十一条，保险公司应当按双方约定提供真实的财务报告、偿付能力报告、业务发展规划、风险管理报告等信用评级所必要的材料。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M05","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"保险公司聘请的境外信用评级机构应当符合的条件包括（ ）。","options":["符合机构所在地监管部门的相关监管要求","已向银保监会递交《配合监管承诺函》","评级程序已向银保监会备案","最近年度末实收资本和净资产均不低于2000万元"],"answer":["A","B","C"],"explanation":"依据第九条，境外评级机构只需符合所在地监管要求、递交承诺函且评级程序备案；2000万元资本要求仅适用于境内评级机构（第八条）。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M06","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"下列关于保险公司信用评级的说法，正确的有（ ）。","options":["保险公司发行债务工具或资本工具，法律法规和监管规定要求进行信用评级的，应当进行信用评级","银保监会鼓励保险公司主动聘请信用评级机构对本公司进行主体信用评级，并公开披露评级结果","保险公司在境外融资或开展国际业务等情况下，可以聘请境外信用评级机构","所有保险公司每年必须进行主体信用评级"],"answer":["A","B","C"],"explanation":"依据第六条和第七条，A、B、C均正确；D错误，主体评级是监管鼓励而非强制要求。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M07","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"境内信用评级机构应当具有健全的业务制度，包括（ ）等。","options":["信用等级划分及定义、评级标准、评级程序、评级方法","实地调查制度、评级跟踪制度、评级结果披露制度","评审委员会管理制度、确保独立性的制度","业务信息保密制度、档案管理制度"],"answer":["A","B","C","D"],"explanation":"依据第八条第（五）项，健全的业务制度包括信用等级划分及定义、评级标准、评级程序、评级方法、实地调查制度、评级跟踪制度、评级结果披露制度、评审委员会管理制度、确保独立性的制度、业务信息保密制度、档案管理制度等。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M08","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"信用评级机构以不正当竞争手段招揽业务的情形包括（ ）。","options":["压价竞争","诋毁同行","以级定价","以价定级"],"answer":["A","B","C","D"],"explanation":"依据第二十一条第（三）项，以压价竞争、诋毁同行、以级定价或以价定级等不正当竞争手段招揽业务的，银保监会有权责令保险公司更换信用评级机构。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M09","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"关于《配合监管承诺函》，下列说法正确的有（ ）。","options":["境内信用评级机构从事保险公司信用评级业务应当递交","境外信用评级机构被保险公司聘请的也应当递交","承诺内容包括按照银保监会要求及时全面报送有关材料","承诺接受银保监会的监督、检查"],"answer":["A","B","C","D"],"explanation":"依据第八条第（七）项、第九条和第十九条，境内外评级机构均须递交《配合监管承诺函》，承诺积极配合银保监会监管，包括及时全面报送材料、接受监督和检查等。","difficulty":2,"type":"concept","source":"core"},{"id":"17-M10","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"下列关于信用评级行为的说法，正确的有（ ）。","options":["信用评级机构对不同保险公司进行信用评价时，应当采用一致的评级标准和工作程序","信用评级机构开展保险公司信用评级业务，应当履行科学、完整的评级程序","信用评级机构应当在信用评级有效期内持续跟踪并及时更新调整评级结果","保险公司可以采用直接委托方式选聘境内信用评级机构"],"answer":["A","B","C"],"explanation":"依据第四条、第十三条、第十五条，A、B、C正确；依据第十条，保险公司应当采用公开招标或邀请招标方式选聘境内评级机构，D错误。","difficulty":2,"type":"concept","source":"core"},{"id":"17-X-S01","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"根据《保险公司信用评级》，境内信用评级机构最近年度末实收资本和净资产的最低要求分别是多少？","options":["均不低于1000万元","均不低于2000万元","均不低于3000万元","均不低于5000万元"],"answer":"B","explanation":"依据第17号规则第二章，境内信用评级机构最近年度末实收资本和净资产均不低于2000万元。","difficulty":1,"type":"concept","source":"extra"},{"id":"17-X-S02","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司采用邀请招标方式选聘境内信用评级机构时，发出投标邀请的机构数量及中资机构要求是什么？","options":["不少于2家，至少1家中资","不少于3家，至少1家中资","不少于3家，至少2家中资","不少于5家，至少2家中资"],"answer":"B","explanation":"依据第17号规则，保险公司发出投标邀请的信用评级机构不得少于3家，且其中至少有1家中资信用评级机构。","difficulty":2,"type":"concept","source":"extra"},{"id":"17-X-S03","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"某保险公司于2024年3月15日与中选境内信用评级机构签订聘用合同，依据《保险公司信用评级》，最迟应在何时向银保监会书面报告？","options":["2024年3月18日","2024年3月20日","2024年3月29日","2024年4月1日"],"answer":"C","explanation":"依据第17号规则，保险公司与评级机构签订聘用合同之日起10个工作日内应向银保监会书面报告。3月15日签订，10个工作日（周末顺延）后为3月29日。","difficulty":2,"type":"calc","source":"extra"},{"id":"17-X-S04","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"信用评级机构在对A保险公司开展主体评级过程中，发现其存在重大违法违规行为，依据《保险公司信用评级》，应当如何处理？","options":["在评级报告中调低等级后对外披露","暂缓出具评级报告","向银保监会书面报告","在公开媒体披露以提示投资者"],"answer":"C","explanation":"依据第17号规则监管要求，信用评级机构发现保险公司存在重大违法违规行为时，应当向银保监会报告。","difficulty":3,"type":"scenario","source":"extra"},{"id":"17-X-S05","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司发行的债务工具或资本工具需要进行信用评级，债项评级除考虑公司总体状况外，还应综合考虑债项的哪些特点？","options":["仅考虑发行协议条款","仅考虑清偿顺序","发行协议、期限、清偿顺序、转股权利、增信措施等","仅考虑增信措施"],"answer":"C","explanation":"依据第17号规则易考细节，债项评级除公司总体状况外，还应综合考虑债项的发行协议、期限、清偿顺序、转股权利、增信措施等特点。","difficulty":2,"type":"concept","source":"extra"},{"id":"17-X-S06","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"依据《保险公司信用评级》关于评级基本原则的要求，评级机构对不同保险公司进行信用评价时应当如何处理？","options":["根据公司规模差异化对待","采用一致的评级标准和工作程序，确保公平可比","在征得被评公司同意后差异化","由评级机构自行决定是否一致"],"answer":"B","explanation":"依据第17号规则易考细节，评级机构对不同保险公司进行信用评价时应采用一致的评级标准和工作程序，确保评级结果公平可比。","difficulty":1,"type":"concept","source":"extra"},{"id":"17-X-S07","rule_no":17,"rule_title":"保险公司信用评级","qtype":"single","q":"保险公司在某季度内收到新一期信用评级报告，依据《保险公司信用评级》与《偿付能力报告》的衔接要求，应当在何时披露？","options":["在收到报告次月的月度报告中披露","在收到报告当期的季度报告中列报信用评级信息","在年度报告中集中披露","无须在偿付能力报告中披露"],"answer":"B","explanation":"依据第17号规则，保险公司应在偿付能力季度报告中披露信用评级信息；第18号规则进一步明确收到信用评级报告当期的季度报告中列报相关评级信息。","difficulty":2,"type":"cross","source":"extra"},{"id":"17-X-M01","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"依据《保险公司信用评级》，境内信用评级机构开展保险公司评级业务应当同时具备的条件包括：","options":["最近年度末实收资本和净资产均不低于2000万元","具有3年以上信用评级业务经验的专业人员不少于20人","从事保险公司信用评级的专业人员不少于3人","最近3年没有重大违法违规行为"],"answer":["A","B","C","D"],"explanation":"依据第17号规则，境内评级机构需同时满足四项条件：实收资本与净资产≥2000万元、专业人员≥20人、保险公司评级人员≥3人、最近3年无重大违法违规。","difficulty":1,"type":"concept","source":"extra"},{"id":"17-X-M02","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"依据《保险公司信用评级》，关于境内信用评级机构专业人员配备要求，下列描述正确的有：","options":["具有3年以上信用评级业务经验的专业人员不少于20人","其中从事保险公司信用评级业务的专业人员不少于3人","境外评级机构须配备同等数量的境内专业人员","最近年度末实收资本不低于2000万元"],"answer":["A","B","D"],"explanation":"依据第17号规则：境内机构专业人员≥20人、其中保险公司评级人员≥3人、实收资本≥2000万元；境外评级机构不适用境内机构的人员和资本条件。","difficulty":2,"type":"calc","source":"extra"},{"id":"17-X-M03","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"A保险公司在境内开展融资业务并拟聘请境内信用评级机构，下列做法合规的有：","options":["采用公开招标或邀请招标方式选聘","向3家评级机构发出投标邀请，其中包含1家中资机构","要求投标机构承诺与本公司不存在重大利益关系","中选机构与公司签订聘用合同后30个工作日内向银保监会报告"],"answer":["A","B","C"],"explanation":"依据第17号规则，境内选聘应公开/邀请招标，投标邀请不少于3家且至少1家中资，且应避免重大利益关系以保障独立性；D项错误，报告期限为签订合同之日起10个工作日内。","difficulty":2,"type":"scenario","source":"extra"},{"id":"17-X-M04","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"评级机构在对A保险公司开展主体评级的同时，对A公司发行的次级债进行债项评级，下列说法正确的有：","options":["主体评级针对A保险公司整体信用状况","债项评级针对次级债的发行协议、期限、清偿顺序等特点","债项评级须综合考虑转股权利与增信措施","主体评级也应单独评估债项的清偿顺序"],"answer":["A","B","C"],"explanation":"依据第17号规则关键定义与易考细节：主体评级评价保险公司整体信用状况；债项评级针对债务工具或资本工具，需综合考虑发行协议、期限、清偿顺序、转股权利、增信措施等特点。清偿顺序属于债项评级范畴。","difficulty":3,"type":"scenario","source":"extra"},{"id":"17-X-M05","rule_no":17,"rule_title":"保险公司信用评级","qtype":"multi","q":"依据《保险公司信用评级》，关于评级机构配合监管的时限要求，下列正确的有：","options":["聘用合同签订之日起10个工作日内向银保监会书面报告","投标邀请的评级机构不少于3家","评级机构应向银保监会书面报送信用等级划分标准及含义说明","评级机构发现重大违法违规行为应向银保监会报告"],"answer":["A","B","C","D"],"explanation":"依据第17号规则：签订合同10个工作日内报告、投标邀请不少于3家且至少1家中资、评级机构应报送等级划分标准及含义、发现重大违法违规应向银保监会报告。","difficulty":3,"type":"calc","source":"extra"},{"id":"18-S01","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司向银保监会报送的偿付能力报告包括（ ）。","options":["季度报告、季度快报和临时报告","月度报告、季度报告和年度报告","季度报告、半年度报告和年度报告","定期报告和临时报告两类"],"answer":"A","explanation":"依据第三条，偿付能力报告包括偿付能力季度报告、偿付能力季度快报和偿付能力临时报告。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S02","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"季度报告涉及的会计政策和会计估计应当采用“一体观”，其含义是（ ）。","options":["将报告季度视为年度会计期间的一部分，以对整个年度经营状况和财务状况的判断来决定季度末的会计估计、成本分配、递延和应计等项目","集团内母子公司采用统一会计政策","会计政策一经确定不得变更","境内境外业务采用同一套会计准则"],"answer":"A","explanation":"依据第四条，一体观即将报告季度视为年度会计期间的一部分，以对整个年度经营状况和财务状况的判断来决定季度末的会计估计、成本分配、递延和应计等项目，银保监会特别规定的除外。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S03","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"对所报送偿付能力报告的真实性、准确性、完整性和合规性负责的是（ ）。","options":["保险公司董事会和管理层","精算负责人和首席风险官","外部审计机构","银保监会指定的主监管员"],"answer":"A","explanation":"依据第五条，保险公司董事会和管理层对所报送的偿付能力报告的真实性、准确性、完整性和合规性负责。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S04","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司第1季度和第3季度的偿付能力报告（ ）。","options":["可以不经过董事会审议，但须经董事长批准并作相应声明","必须经董事会审议","可以不经任何审批直接报送","只需总经理批准即可"],"answer":"A","explanation":"依据第十二条，第1季度和第3季度的偿付能力报告可以不经过董事会审议；未经董事会审议的，应在季度报告显著位置声明本报告已经公司董事长批准，董事长和管理层承担相应保证责任。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S05","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"季度报告应当由保险公司七类人员签字，下列不在签字人员范围内的是（ ）。","options":["合规负责人","首席风险官","总精算师（精算负责人）","监事会主席"],"answer":"D","explanation":"依据第十三条，签字人员为董事长、总经理、财务负责人、精算负责人、投资负责人、首席风险官、合规负责人，监事会主席不在其中。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S06","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"关于季度报告董事会和董事长要求对外国保险公司分公司的适用性，正确的是（ ）。","options":["第十一条至第十三条有关董事会和董事长的要求不适用于外国保险公司分公司","外国保险公司分公司完全适用所有条款","外国保险公司分公司只需董事会审议不需签字","外国保险公司分公司由总公司董事长签字即可"],"answer":"A","explanation":"依据第十四条，本规则第十一条至第十三条有关董事会和董事长的要求不适用于外国保险公司分公司。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S07","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"关于董事、监事和总公司高级管理人员薪酬信息的列报，正确的做法是（ ）。","options":["在第四季度报告中列报本年度薪酬的相关信息，其他季度无需列报","每季度均需列报","仅在年度报告中列报","在第二季度报告中列报"],"answer":"A","explanation":"依据第十八条，保险公司应当在第四季度报告中列报董事、监事和总公司高级管理人员本年度薪酬的相关信息，其他季度无需列报。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S08","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司应当列报偿付能力充足率指标的本季度数、上季度可比数和（ ）。","options":["基本情景下的下季度预测数","压力情景下的下季度预测数","本年度累计数","上年度同期数"],"answer":"A","explanation":"依据第二十二条，偿付能力充足率指标应列报本季度数、上季度可比数和基本情景下的下季度预测数。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S09","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"下列属于流动性风险监管指标的是（ ）。","options":["流动性覆盖率、经营活动净现金流回溯不利偏差率和公司净现金流","综合成本率、综合费用率和综合赔付率","净资产收益率、总资产收益率和投资收益率","13个月续保率、综合退保率和营销员脱落率"],"answer":"A","explanation":"依据第二十三条，流动性风险监管指标包括流动性覆盖率、经营活动净现金流回溯不利偏差率和公司净现金流。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S10","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"财产保险公司的效益类经营指标包括（ ）。","options":["综合成本率、综合费用率、综合赔付率等","剩余边际、新业务利润率、新业务价值","未决赔款准备金与赔款支出比","13个月续保率、综合退保率"],"answer":"A","explanation":"依据第二十五条，财产保险公司效益类指标包括综合成本率、综合费用率、综合赔付率、手续费及佣金占比、业务管理费占比；B为人身险指标，C为再保险指标，D为人身险品质类指标。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S11","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"人身保险公司新业务利润率的计算公式为（ ）。","options":["本期新业务的首日利得÷新业务各期保费收入之和×100%","本期新业务保费收入÷总资产×100%","本期新业务的首日利得÷本期签单保费×100%","净利润÷新业务保费收入×100%"],"answer":"A","explanation":"依据第二十六条，新业务利润率＝本期新业务的首日利得÷新业务各期保费收入之和×100%，首日利得指新业务首次进行财务报表准备金评估时的剩余边际。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S12","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司风险管理自评估的频率要求是（ ）。","options":["每年至少开展一次","每季度开展一次","每半年开展一次","每两年开展一次"],"answer":"A","explanation":"依据第三十条，保险公司应当对照第12号规则各项要求，每年至少开展一次风险管理自评估。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S13","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司进行风险管理自评估时，评估结果符合程度的档级分为（ ）。","options":["完全符合、大部分符合、部分符合、不符合、不适用","优、良、中、合格、不合格","A、B、C、D四类","高、中、低三档"],"answer":"A","explanation":"依据第三十一条，自评估应逐项列报符合的程度，包括完全符合、大部分符合、部分符合、不符合、不适用五档。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S14","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"重大再保险合同的认定标准是（ ）。","options":["分入（分出）保额超过本季度末有效保额的5%或分入（分出）保费超过报告期保费收入5%的单项再保险合同","分保保费超过1000万元的单项再保险合同","分入（分出）保额超过总资产的5%的再保险合同","与关联方签订的所有再保险合同"],"answer":"A","explanation":"依据第三十七条，重大再保险合同指分入（分出）保额超过保险公司本季度末有效保额的5%或分入（分出）保费超过报告期保费收入5%的单项再保险合同。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S15","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"重大投资损失是指投资损失金额超过保险公司报告期末净资产总额（ ）的投资损失。","options":["3%","5%","10%","15%"],"answer":"B","explanation":"依据第四十条，重大投资损失指单项股权投资、不动产投资、基础设施投资、信托资产投资、资产证券化产品投资等的投资损失金额超过报告期末净资产总额5%的投资损失。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S16","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"重大融资事项是指单笔融资金额超过公司报告期末净资产（ ）的融资活动。","options":["5%","10%","20%","30%"],"answer":"B","explanation":"依据第四十一条，重大融资事项指增资扩股、发行债务性资本工具等单笔融资金额超过公司报告期末净资产10%的融资活动。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S17","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司在任何时点出现偿付能力不足的情况，应当在发现之日起（ ）内向银保监会报告。","options":["3日","5个工作日","10日","12日"],"answer":"B","explanation":"依据第七十一条，保险公司在任何时点出现偿付能力不足的情况，应当在发现之日起5个工作日内向银保监会报告。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S18","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司出现重大流动性风险时，应当自发现之日起（ ）内向银保监会报告。","options":["3日","5个工作日","10日","15日"],"answer":"A","explanation":"依据第七十四条，保险公司出现重大流动性风险时，应当自发现之日起3日内向银保监会报告，内容包括当前流动性状况、风险产生原因、已采取和拟采取的应急措施等。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S19","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"季度快报和季度报告的报送时限分别为每季度结束后（ ）。","options":["12日；25日","10日；20日","15日；30日","12日；20日"],"answer":"A","explanation":"依据第七十六条，季度快报应当在每季度结束后12日内报送，季度报告应当在每季度结束后25日内报送。","difficulty":2,"type":"concept","source":"core"},{"id":"18-S20","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"关于季度报告的审计要求，正确的是（ ）。","options":["第四季度季度报告应当经会计师事务所审计","四个季度的季度报告都必须经审计","季度报告一律不需审计","仅第二季度报告必须审计"],"answer":"A","explanation":"依据第七十八条，保险公司的第四季度季度报告应当经会计师事务所审计，其他3个季度可根据自身需要和银保监会要求委托审计。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M01","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"季度报告的组成部分包括（ ）。","options":["公司信息、董事会和管理层声明","主要指标、风险管理能力","实际资本、最低资本、压力测试","风险综合评级（分类监管）、重大事项、管理层分析与讨论、外部机构意见"],"answer":["A","B","C","D"],"explanation":"依据第七条，季度报告包括公司信息、董事会和管理层声明、基本情况、主要指标、风险管理能力、风险综合评级、重大事项、管理层分析与讨论、外部机构意见、实际资本、最低资本、压力测试共十二部分。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M02","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"季度报告应当由下列哪些人员签字并加盖公司印章？（ ）","options":["董事长","财务负责人、精算负责人、投资负责人","首席风险官、合规负责人","总经理或具有相同职权的公司高级管理人员"],"answer":["A","B","C","D"],"explanation":"依据第十三条，季度报告应由董事长、总经理（或同等职权高管）、财务负责人、精算负责人、投资负责人、首席风险官、合规负责人签字并加盖公司印章。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M03","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"保险公司应当列报的偿付能力充足率指标包括（ ）。","options":["核心一级资本、核心二级资本、附属一级资本、附属二级资本","可资本化风险最低资本、控制风险最低资本、附加资本、最低资本","核心偿付能力溢额、综合偿付能力溢额","核心偿付能力充足率、综合偿付能力充足率"],"answer":["A","B","C","D"],"explanation":"依据第二十二条，以上均为应列报的偿付能力充足率指标，且需列报本季度数、上季度可比数和基本情景下的下季度预测数。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M04","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"财产保险公司除通用经营指标外，还应列报的效益类指标包括（ ）。","options":["综合成本率","综合费用率","综合赔付率","手续费及佣金占比"],"answer":["A","B","C","D"],"explanation":"依据第二十五条，财产保险公司效益类指标包括综合成本率、综合费用率、综合赔付率、手续费及佣金占比和业务管理费占比。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M05","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"人身保险公司应当列报的品质类指标包括（ ）。","options":["13个月续保率","综合退保率","个人营销渠道的件均保费","人均保费和营销员脱落率"],"answer":["A","B","C","D"],"explanation":"依据第二十六条，人身保险公司品质类指标包括13个月续保率、综合退保率、个人营销渠道的件均保费、人均保费、营销员脱落率。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M06","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"保险公司风险管理自评估应当区分的部分包括（ ）。","options":["风险管理基础与环境、风险管理目标与工具","保险风险管理、市场风险管理、信用风险管理","操作风险管理、战略风险管理、声誉风险管理","流动性风险管理"],"answer":["A","B","C","D"],"explanation":"依据第三十一条，自评估应区分九个部分：风险管理基础与环境、风险管理目标与工具、保险风险管理、市场风险管理、信用风险管理、操作风险管理、战略风险管理、声誉风险管理、流动性风险管理。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M07","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"保险公司发生下列对偿付能力产生重大不利影响的事项时，应当自事项发生之日起5个工作日内向银保监会报告的有（ ）。","options":["重大投资损失","重大赔付、大规模退保或者遭遇重大诉讼","主要股东、子公司或合营企业出现财务危机或者被金融监管机构接管","重大资产遭司法机关冻结或者受到其他机关的重大行政处罚"],"answer":["A","B","C","D"],"explanation":"依据第七十二条，以上情形均属于应自发生之日起5个工作日内报告的重大不利影响事项，此外还包括外国保险公司分公司总公司因偿付能力问题受处罚等情形。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M08","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"经审计的第四季度偿付能力相关信息发生重大变动时，应当自审计报告出具之日起10日内向银保监会报告的情形包括（ ）。","options":["审计机构出具了除“无保留意见”外的审计报告","审计后的核心偿付能力充足率或综合偿付能力充足率不达标","审计后的核心或综合偿付能力充足率变动超过3个百分点","审计后的实际资本或最低资本的变动比例超过1%"],"answer":["A","B","C","D"],"explanation":"依据第七十三条，以上四种情形均属于应自审计报告出具之日起10日内报告的重大变动情形。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M09","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"季度快报的主要指标包括（ ）。","options":["核心偿付能力充足率、综合偿付能力充足率","核心一级资本、核心二级资本、附属一级资本、附属二级资本","认可资产、认可负债、实际资本","可资本化风险最低资本、控制风险最低资本、附加资本"],"answer":["A","B","C","D"],"explanation":"依据第六十九条，季度快报主要指标包括偿付能力充足率指标、各级资本、偿付能力溢额、认可资产、认可负债、实际资本、可资本化风险最低资本、控制风险最低资本和附加资本，并应列报本季度数和上季度可比数。","difficulty":2,"type":"concept","source":"core"},{"id":"18-M10","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"关于保险公司列报重大事项应遵循的原则，正确的有（ ）。","options":["能够估计对偿付能力影响金额的，应当说明对核心偿付能力充足率、综合偿付能力充足率的影响","没有发生某类重大事项的，应当在季度报告中明确说明“未发生重大××事项”","某项重大事项在本报告其他部分有详细列报的，可以简化列报，但要标明详细列报的位置","所有重大事项均须在每个季度完整重复列报"],"answer":["A","B","C"],"explanation":"依据第四十六条，列报重大事项应遵循三点原则，D项与简化列报原则相悖。","difficulty":2,"type":"concept","source":"core"},{"id":"18-X-S01","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"根据《保险公司偿付能力监管报告规则》（第18号），保险公司季度报告应在每季度结束后多少日内报送银保监会？","options":["12日","20日","25日","30日"],"answer":"C","explanation":"根据第18号规则第五章报送要求，季度报告在每季度结束后25日内报送；季度快报则为12日内。","difficulty":1,"type":"concept","source":"extra"},{"id":"18-X-S02","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司A本季度末有效保额100亿元，本季度签订一项分入再保险合同，分入保额6亿元、分入保费收入1.5亿元；A本季度保费收入合计30亿元。依据第18号规则，该再保险合同是否构成'重大再保险合同'？","options":["不构成，分入保额未超5%阈值","构成，分入保额超5%阈值","不构成，分入保费未超5%阈值","不构成，分入保额和分入保费均未超5%阈值"],"answer":"B","explanation":"重大再保险合同指分入（分出）保额超过保险公司本季度末有效保额的5%或分入（分出）保费超过报告期保费收入5%的单项再保险合同，满足任一即可。分入保额6亿/有效保额100亿=6%>5%，故构成。","difficulty":2,"type":"scenario","source":"extra"},{"id":"18-X-S03","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司某年初净资产500亿元，年末净资产600亿元，全年净利润60亿元。该公司净资产收益率约为：","options":["10.0%","10.9%","11.1%","12.0%"],"answer":"B","explanation":"净资产收益率=净利润÷[(期初净资产+期末净资产)÷2]×100%=60÷[(500+600)÷2]×100%=60÷550×100%≈10.9%。","difficulty":2,"type":"calc","source":"extra"},{"id":"18-X-S04","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司某季度自留保费100亿元，未到期责任准备金变动额5亿元；赔付支出40亿元，未决赔款准备金变动额15亿元，摊回赔付支出5亿元；业务及管理费20亿元，手续费及佣金10亿元，分保费用支出5亿元，承保业务的税金及附加2亿元，摊回分保费用2亿元。该公司本季度综合成本率约为：","options":["84.2%","89.5%","90.5%","94.7%"],"answer":"B","explanation":"综合成本率=(40+15-5+20+10+5+2-2)÷(100-5)×100%=85÷95×100%≈89.5%。","difficulty":2,"type":"calc","source":"extra"},{"id":"18-X-S05","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"根据第18号规则，季度快报的内容仅包括下列哪两部分？","options":["基本信息、主要指标、风险管理能力","基本信息、主要指标","公司信息、董事会声明、基本情况、主要指标","基本情况、主要指标、压力测试"],"answer":"B","explanation":"根据第18号规则第三章，季度快报仅包括基本信息和主要指标两部分。","difficulty":1,"type":"concept","source":"extra"},{"id":"18-X-S06","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"保险公司发生以下四种情形：(1)偿付能力不足；(2)重大不利影响事项；(3)审计后偿付能力充足率变动超过3个百分点；(4)重大流动性风险。依据第18号规则，上述事项向银保监会提交临时报告的时限分别为：","options":["5个、5个、10个、3个工作日内","5个、3个、10个、5个工作日内","10个、5个、3个、5个工作日内","5个、5个、10个、3个自然日内"],"answer":"A","explanation":"根据第18号规则第四章，偿付能力不足和重大不利影响事项为5个工作日内；审计后重大变动为审计报告出具之日起10个工作日内；重大流动性风险为发现之日起3个工作日内。","difficulty":3,"type":"scenario","source":"extra"},{"id":"18-X-S07","rule_no":18,"rule_title":"偿付能力报告","qtype":"single","q":"根据第18号规则，审计后'重大变动'的判定标准是：","options":["核心或综合偿付能力充足率变动超过3个百分点；实际资本或最低资本变动比例超过1%","核心或综合偿付能力充足率变动超过5个百分点；实际资本或最低资本变动比例超过3%","核心偿付能力充足率变动超过3个百分点；实际资本变动比例超过1%","核心偿付能力充足率变动超过1个百分点；实际资本或最低资本变动比例超过3%"],"answer":"A","explanation":"根据第18号规则第四章，审计后重大变动标准：核心或综合偿付能力充足率变动超过3个百分点；实际资本或最低资本变动比例超过1%。","difficulty":3,"type":"concept","source":"extra"},{"id":"18-X-M01","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"根据第18号规则，季度报告应由以下哪几类人员签字并加盖公司印章？","options":["董事长","总经理（或同等职权高管）","首席风险官","精算负责人"],"answer":["A","B","C","D"],"explanation":"根据第18号规则第二章，季度报告应由董事长、总经理（或同等职权高管）、财务负责人、精算负责人、投资负责人、首席风险官、合规负责人七类人员签字并加盖公司印章。","difficulty":2,"type":"concept","source":"extra"},{"id":"18-X-M02","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"保险公司本季度发生以下事项，依据第18号规则哪些属于'重大事项'应在季度报告中列报？","options":["对子公司增资5亿元","单项股权投资项目亏损8亿元（公司报告期末净资产总额120亿元）","公司发行债务性资本工具融资20亿元（公司报告期末净资产150亿元）","诉讼标的金额排名前三位的诉讼事项"],"answer":["A","B","C","D"],"explanation":"重大投资行为包括对子公司、合营企业、联营企业的投资；重大投资损失超过报告期末净资产总额5%（120×5%=6亿元）；重大融资事项单笔金额超过报告期末净资产10%（150×10%=15亿元）；重大诉讼事项为诉讼标的金额排名前三位的诉讼。","difficulty":2,"type":"scenario","source":"extra"},{"id":"18-X-M03","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"根据第18号规则，综合退保率公式的分母包括：","options":["长期险责任准备金期初余额","保户储金及投资款期初余额","独立账户负债期初余额","本年度签单保费"],"answer":["A","B","C","D"],"explanation":"综合退保率=（退保金+保户储金及投资款的退保金+投资连接保险独立账户的退保金）÷（长期险责任准备金期初余额+保户储金及投资款期初余额+独立账户负债期初余额+本年度签单保费）×100%。","difficulty":2,"type":"calc","source":"extra"},{"id":"18-X-M04","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"关于保险集团偿付能力报告与保险公司偿付能力报告的对比，依据第18号和第19号规则，下列说法正确的是：","options":["保险集团按第19号规则编报偿付能力报告，保险公司按第18号规则编报","保险集团应于每年5月31日前报送经审计的上一年度偿付能力报告","保险公司须按季度报送偿付能力季度报告，保险集团须按半年度报送半年度偿付能力报告","保险公司第四季度季度报告需经会计师事务所审计"],"answer":["A","B","C","D"],"explanation":"根据第19号规则，保险集团应于每年5月31日前报送经审计的上一年度偿付能力报告，每年9月15日前报送半年度偿付能力报告；保险公司按第18号规则编报季度报告和年度报告。保险公司第四季度季度报告应当经会计师事务所审计。","difficulty":3,"type":"cross","source":"extra"},{"id":"18-X-M05","rule_no":18,"rule_title":"偿付能力报告","qtype":"multi","q":"根据第18号规则，季度报告共十三节，包括下列哪些部分？","options":["基本情况","主要指标","实际资本","压力测试"],"answer":["A","B","C","D"],"explanation":"根据第18号规则第二章，季度报告共十三节，包括公司信息、董事会和管理层声明、基本情况、主要指标、风险管理能力、风险综合评级、重大事项、管理层讨论与分析、外部机构意见、实际资本、最低资本、压力测试等。","difficulty":1,"type":"concept","source":"extra"},{"id":"19-S01","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团包括的基本类别是（ ）。","options":["保险控股型集团、非保险控股型集团、混合型集团","金融控股型集团、产业控股型集团、综合型集团","保险主导型集团、银行主导型集团、混合型集团","境内集团、境外集团、跨国集团"],"answer":"A","explanation":"依据第二条，本规则所称保险集团包括保险控股型集团、非保险控股型集团、混合型集团三个基本类别。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S02","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"混合型集团是指（ ）。","options":["由同一实际控制人或一致行动人控制（或共同控制）的多家保险公司所组成的企业集合，不具有显性的控制人","由一家保险公司控股多家非保险机构的企业集合","由银行控股多家保险公司的企业集合","同时经营保险业务和银行业务的企业集合"],"answer":"A","explanation":"依据第三条第（三）项，混合型集团由同一实际控制人或一致行动人控制（或共同控制）的多家保险公司组成，不具有显性的控制人。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S03","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团偿付能力监管的三个层次不包括（ ）。","options":["单一法人公司监管","集团监管","系统重要性保险集团监管","跨国联合监管"],"answer":"D","explanation":"依据第八条，三个层次为单一法人公司监管、集团监管、系统重要性保险集团监管。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S04","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团综合偿付能力充足率的达标要求是（ ）。","options":["不低于50%","不低于75%","不低于100%","不低于150%"],"answer":"C","explanation":"依据第十二条，保险集团综合偿付能力充足率不低于100%，核心偿付能力充足率不低于50%，风险综合评级在B类及以上。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S05","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团的最低资本组成不包括（ ）。","options":["可资本化风险最低资本","控制风险最低资本","附加资本","流动性风险最低资本"],"answer":"D","explanation":"依据第十五条，保险集团最低资本由可资本化风险最低资本、控制风险最低资本、附加资本三部分组成。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S06","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"境外保险成员公司的总资产不超过集团总资产（合并财务报表）（ ）的，其最低资本可根据所在地监管标准计算。","options":["3%","5%","10%","20%"],"answer":"B","explanation":"依据第十七条第（二）项，境外保险成员公司总资产不超过集团总资产5%的，或所在国监管制度获中国等效资格的，最低资本可按所在地监管标准计算。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S07","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"关于非受监管公司的最低资本要求，正确的是（ ）。","options":["最低资本要求为零，但银保监会可要求风险较大的非受监管公司计算最低资本","按其净资产的10%计算","按所在行业监管标准计算","一律按中国偿付能力监管规则计算"],"answer":"A","explanation":"依据第十七条第（五）项，非受监管公司的最低资本要求为零；对于风险较大的非受监管公司，银保监会可以要求其计算最低资本，具体标准另行规定。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S08","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团内部担保风险最低资本的风险暴露为集团成员公司之间重大担保余额超过保险集团净资产（合并财务报表）（ ）的部分，基础因子RF0为（ ）。","options":["10%；0.05","20%；0.1","20%；0.05","30%；0.1"],"answer":"B","explanation":"依据第二十三条，内部担保风险的风险暴露为重大担保余额超过集团净资产20%的部分，基础因子RF0＝0.1。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S09","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"根据保险集团类型设置的特征系数k2，混合型集团的赋值为（ ）。","options":["0","0.1","0.2","0.25"],"answer":"C","explanation":"依据第二十三条，k2按集团类型赋值：保险控股集团为0，非保险控股型集团为0.1，混合型集团为0.2。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S10","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团集中度风险最低资本的计算公式为（ ）。","options":["MC集中度＝MC交易对手＋MC行业＋MC客户","MC集中度＝√(MC交易对手²＋MC行业²＋MC客户²)","MC集中度＝max(MC交易对手，MC行业，MC客户)","MC集中度＝(MC交易对手＋MC行业＋MC客户)÷3"],"answer":"B","explanation":"依据第二十五条，MC集中度＝√(MC交易对手²＋MC行业²＋MC客户²)，即三项风险最低资本的平方和开根号。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S11","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"交易对手为全国性股份制商业银行的，集中度限额为保险集团总资产（合并财务报表）的（ ），基础因子RF0为（ ）。","options":["3%；0.05","5%；0.03","5%；0.05","10%；0.03"],"answer":"B","explanation":"依据第二十六条和第二十七条，全国性股份制商业银行的集中度限额为集团总资产的5%，基础因子RF0＝0.03；其他交易对手限额为3%，RF0＝0.05。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S12","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"行业集中度风险的风险暴露为投资于单一行业的资产账面价值超过保险集团总资产（ ）的部分。","options":["5%","10%","20%","30%"],"answer":"B","explanation":"依据第二十九条，行业集中度风险暴露为投资于单一行业资产账面价值超过集团总资产（合并报表口径）10%的部分，基础因子RF0＝0.05。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S13","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团境内投资的行业分类应按照（ ）执行。","options":["申银万国行业分类标准一级行业分类","全球行业分类标准（GICS）一级行业分类","国民经济行业分类（GB/T 4754）","证监会上市公司行业分类指引"],"answer":"A","explanation":"依据第三十一条，境内投资按申银万国行业分类标准一级行业分类，境外投资按全球行业分类标准（GICS）一级行业分类，且境内外独立计算不得合并。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S14","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"非保险控股型集团和混合型集团评估实际资本采用的方法是（ ）。","options":["合并报表法","减项合并法","加权平均法","穿透法"],"answer":"B","explanation":"依据第三十九条，非保险控股型集团和混合型集团应采用减项合并法，即集团实际资本＝成员公司实际资本之和－成员公司之间重复计算的资本；保险控股型集团采用合并报表法。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S15","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险控股型集团母公司风险管理部门的人员配置要求是（ ）。","options":["至少配备8名具有偿付能力和风险管理相关工作经验的人员，且其中至少5人应具有3年以上相关工作经验","至少配备5名人员，其中3人有3年以上经验","至少配备10名人员，全部具有5年以上经验","至少配备20名人员，其中3人从事保险信用评级"],"answer":"A","explanation":"依据第五十四条，母公司应设立独立的风险管理部门，至少配备8名具有偿付能力和风险管理相关工作经验的人员，且其中至少5人应具有3年以上相关工作经验。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S16","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"银保监会对保险集团的偿付能力风险管理进行监管评估的频率是（ ）。","options":["每三年一次","每年一次","每两年一次","每五年一次"],"answer":"A","explanation":"依据第一百二十条，银保监会每三年对保险集团的偿付能力风险管理进行一次监管评估，确定保险集团的控制风险。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S17","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团偿付能力风险管理评估中，保险集团本级与保险成员公司评估结果的权重分别为（ ）。","options":["40%和60%","50%和50%","60%和40%","30%和70%"],"answer":"A","explanation":"依据第一百二十二条，评估对象为集团本级和保险成员公司并采用加权平均法，本级与成员公司权重分别为40%和60%。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S18","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团应于每年（ ）之前向银保监会报送经审计的上一年度偿付能力报告。","options":["4月30日","5月31日","6月15日","9月15日"],"answer":"B","explanation":"依据第一百三十三条，保险集团应当于每年5月31日之前向银保监会报送经审计的上一年度偿付能力报告；半年度报告于9月15日前报送。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S19","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团发生超过合并财务报表净资产（ ）的重大投资损失时，应在事项发生后2个工作日内向银保监会提交临时报告。","options":["10%","20%","30%","50%"],"answer":"C","explanation":"依据第一百四十二条，发生超过合并财务报表净资产30%的重大投资损失等事项后2个工作日内应提交临时报告。","difficulty":2,"type":"concept","source":"core"},{"id":"19-S20","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团应在每年6月15日之前披露的是（ ）。","options":["上一年度偿付能力报告摘要","半年度偿付能力报告摘要","一季度偿付能力报告","压力测试报告"],"answer":"A","explanation":"依据第一百四十六条，保险集团应于每年6月15日之前在官方网站披露上一年度偿付能力报告摘要；于每年9月30日之前披露半年度偿付能力报告摘要。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M01","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"下列风险中，属于保险集团化经营产生的特有风险的有（ ）。","options":["风险传染","组织结构不透明风险","集中度风险","非保险领域风险"],"answer":["A","B","C","D"],"explanation":"依据第四条，固有风险不仅包括单个公司层面的风险，也包括集团层面的风险传染、组织结构不透明风险、集中度风险、非保险领域风险等由于集团化经营产生的特有风险。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M02","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"保险集团偿付能力应当符合的要求包括（ ）。","options":["核心偿付能力充足率不低于50%","综合偿付能力充足率不低于100%","风险综合评级在B类及以上","流动性覆盖率不低于100%"],"answer":["A","B","C"],"explanation":"依据第十二条，三项达标要求为核心偿付能力充足率不低于50%、综合偿付能力充足率不低于100%、风险综合评级在B类及以上，D项不属于该条要求。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M03","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"下列资产中，不计量交易对手集中度风险最低资本的包括（ ）。","options":["政府债券","政策性银行、政府支持机构发行的金融产品","投资性房地产","独立账户资产"],"answer":["A","B","C","D"],"explanation":"依据第二十六条，不计量交易对手集中度风险的资产包括政府债券、政策性银行和政府支持机构发行的金融产品、国有大型商业银行存款和发行的产品、保险资管公司发行的符合条件产品、投资性房地产、独立账户资产。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M04","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"关于保险集团成员公司最低资本的计算，正确的有（ ）。","options":["境内保险成员公司按银保监会相关规定计算","银行最低资本等于各项风险加权资产之和乘以银保监会要求的最低资本充足率","证券公司和期货公司的最低资本等于各项风险资本准备之和","非受监管公司的最低资本要求为零"],"answer":["A","B","C","D"],"explanation":"依据第十七条，以上各项均为成员公司最低资本计算的正确规定。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M05","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"关于保险集团实际资本评估，正确的有（ ）。","options":["保险控股型集团采用合并报表法","非保险控股型集团和混合型集团采用减项合并法","非受监管成员公司的实际资本为其净资产","成员公司之间转让资产应进行资本调整以避免资本重复计算"],"answer":["A","B","C","D"],"explanation":"依据第三十七条、第三十九条、第四十条和第四十三条，以上说法均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M06","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"银保监会按照偿付能力风险大小将保险集团分为A、B、C、D四个监管类别，下列说法正确的有（ ）。","options":["A类集团根据风险由小到大进一步细分为AAA类、AA类、A类集团","B类集团根据风险由小到大进一步细分为BBB类、BB类、B类集团","C类集团指偿付能力充足率不达标，或虽达标但某一类或几类风险较大的集团","D类集团指偿付能力充足率不达标，或虽达标但某一类或几类风险严重的集团"],"answer":["A","B","C","D"],"explanation":"依据第四十七条，A类细分为AAA、AA、A类，B类细分为BBB、BB、B类，C类为风险较大的集团，D类为风险严重的集团。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M07","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"保险控股型集团母公司董事会履行的偿付能力风险管理职责包括（ ）。","options":["审批集团偿付能力风险管理总体目标、风险偏好、风险容忍度和风险管理政策","审批集团偿付能力风险管理组织结构和职责","审批集团资本规划","审批集团偿付能力报告"],"answer":["A","B","C","D"],"explanation":"依据第四十九条，母公司董事会职责包括审批风险管理总体目标与政策、组织结构和职责、资本规划、偿付能力报告及其他重大偿付能力相关事项。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M08","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"保险集团偿付能力风险管理评估结果不高于70分的情形包括（ ）。","options":["保险集团股权结构不清晰或存在重大股权纠纷","偿付能力风险管理要求与评估中“偿付能力风险治理”部分得分率低于60%","未按规定编报资本规划，或资本规划实施出现重大偏差且无合理理由","处于被接管或风险处置阶段"],"answer":["A","B","C","D"],"explanation":"依据第一百二十六条，以上情形均导致评估结果不高于70分，此外还包括关联交易超限、未准确确定成员公司范围、出现重大风险事件等。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M09","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"关于保险集团风险管理策略和风险传染防范，正确的有（ ）。","options":["成员公司风险限额总和超过集团风险限额时，母公司应要求成员公司调整风险限额","保险集团应当设立关联交易控制委员会，重大关联交易经其审查后提交董事会或股东（大）会审批","保险集团资金集中化管理时应单独管理保险资金与非保险资金，不得相互占用","成员公司可以将部分非核心业务或运营职能外包，但不得将金融核心业务外包"],"answer":["A","B","C","D"],"explanation":"依据第六十一条、第七十一条、第七十六条和第七十八条，以上说法均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"19-M10","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"关于保险集团偿付能力报告和信息披露，正确的有（ ）。","options":["保险控股型集团、非保险控股型集团的偿付能力报告主体为保险集团母公司","没有母公司的混合型集团，由银保监会指定某一成员公司作为报告和信息披露主体","保险集团不能按时披露的，延迟披露时间不得超过15日","保险集团应在每年5月31日前将集团压力测试报告报银保监会"],"answer":["A","B","C","D"],"explanation":"依据第一百三十一条、第一百四十七条、第一百四十三条，以上说法均正确。","difficulty":2,"type":"concept","source":"core"},{"id":"19-X-S01","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"根据第19号规则，由一家保险集团（控股）公司或保险公司与受其直接或间接控制、共同控制的一家或多家保险公司及其他非保险机构所共同形成的企业集合属于：","options":["非保险控股型集团","混合型集团","保险控股型集团","系统重要性保险集团"],"answer":"C","explanation":"根据第19号规则，保险控股型集团由保险集团（控股）公司或保险公司与受其直接或间接控制、共同控制的多家保险公司及其他非保险机构共同形成。","difficulty":1,"type":"concept","source":"extra"},{"id":"19-X-S02","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"根据第19号规则，保险集团偿付能力监管分为哪三个层次？","options":["行业监管、集团监管、跨境监管","单一法人公司监管、集团监管、系统重要性保险集团监管","法人监管、合并监管、现场监管","主体监管、行为监管、功能监管"],"answer":"B","explanation":"根据第19号规则，保险集团偿付能力监管分为单一法人公司监管、集团监管、系统重要性保险集团监管三个层次。","difficulty":2,"type":"concept","source":"extra"},{"id":"19-X-S03","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"某保险集团母公司最低资本80亿元，子公司最低资本合计120亿元，合营企业最低资本50亿元（集团权益比例60%），集团层面可资本化特有风险最低资本10亿元，风险分散效应的资本要求减少额8亿元。该集团可资本化风险最低资本为：","options":["248亿元","240亿元","232亿元","210亿元"],"answer":"C","explanation":"集团可资本化风险最低资本=母公司最低资本+子公司最低资本+合营企业最低资本×权益比例+集团层面可资本化特有风险最低资本-风险分散效应的资本要求减少=80+120+50×60%+10-8=232亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"19-X-S04","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团某次偿付能力风险管理监管评估得分S=75分，依据第19号规则，其控制风险因子Q为：","options":["0.05","0.025","0","-0.05"],"answer":"B","explanation":"控制风险因子Q分段公式：S≤70时Q=-0.01S+0.75；70≤S≤90时Q=-0.005S+0.4；90≤S≤100时Q=-0.01S+0.85。S=75对应70-90区间，Q=-0.005×75+0.4=-0.375+0.4=0.025。","difficulty":2,"type":"calc","source":"extra"},{"id":"19-X-S05","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"根据第19号规则，对全国性股份制商业银行的交易对手集中度风险限额为集团总资产的：","options":["3%","5%","8%","10%"],"answer":"B","explanation":"根据第19号规则，交易对手集中度限额：全国性股份制商业银行为集团总资产5%，其他机构为3%；基础因子RF0分别为0.03和0.05。","difficulty":1,"type":"concept","source":"extra"},{"id":"19-X-S06","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"保险集团发生以下情形之一，依据第19号规则应在2个工作日内向银保监会提交临时报告的是：","options":["单一成员公司单一股东变更","合并报表净资产30%以上的重大投资损失","集团年度审计报告意见类型变化","集团下属保险公司季度偿付能力报告迟报"],"answer":"B","explanation":"根据第19号规则第五章，发生重大事项（含超过合并净资产30%的重大投资损失等）后2个工作日内向银保监会提交临时报告。","difficulty":3,"type":"scenario","source":"extra"},{"id":"19-X-S07","rule_no":19,"rule_title":"保险集团","qtype":"single","q":"某保险集团根据第19号规则采用综合因子法计量集团特有风险最低资本，风险暴露EX=1000亿元，基础因子RF0=0.1，特征系数K=0.2，则风险因子RF为：","options":["0.08","0.10","0.12","0.15"],"answer":"C","explanation":"综合因子法下RF=RF0×(1+K)=0.1×(1+0.2)=0.12。","difficulty":2,"type":"calc","source":"extra"},{"id":"19-X-M01","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"根据第19号规则，存在下列哪些情形之一的，保险集团评估结果不高于70分？","options":["股权结构不清晰","风险治理部分得分率低于60%","出现重大风险事件","未按规定报送季度报告"],"answer":["A","B","C"],"explanation":"根据第19号规则，存在八类情形之一的（如股权结构不清晰、风险治理部分得分率低于60%、出现重大风险事件等），保险集团评估结果不高于70分。","difficulty":2,"type":"concept","source":"extra"},{"id":"19-X-M02","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"保险集团A在偿付能力风险管理监管评估中，集团本级制度健全性评估得分36分、遵循有效性评估得分32分；保险成员公司制度健全性评估得分29分、遵循有效性评估得分31分。依据第19号规则，下列说法正确的是：","options":["集团本级综合得分为68分","保险成员公司综合得分为60分","该集团整体评估综合得分约为63.2分","监管评估每三年进行一次"],"answer":["A","B","C","D"],"explanation":"制度健全性和遵循有效性各占50%权重；集团本级综合=36+32=68分；保险成员公司综合=29+31=60分；集团本级权重40%、保险成员公司权重60%，整体综合=68×40%+60×60%=63.2分；监管评估每三年进行一次。","difficulty":2,"type":"scenario","source":"extra"},{"id":"19-X-M03","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"某保险集团持有一家合营企业60%权益，该合营企业最低资本为50亿元；该集团另持有一家合营企业40%权益，该合营企业最低资本为80亿元。依据第19号规则，计算集团最低资本时，关于合营企业最低资本的处理，下列说法正确的是：","options":["第一家合营企业应按60%权益比例计入30亿元","第二家合营企业应按40%权益比例计入32亿元","合营企业最低资本中非本集团持股部分应予剔除","合营企业最低资本应全额计入集团最低资本"],"answer":["A","B","C"],"explanation":"根据第19号规则，合营企业最低资本中非本集团持股部分=非本集团成员公司在合营企业的权益比例×合营企业最低资本，计算集团最低资本时应剔除，即按本集团持股比例计入。第一家50×60%=30亿元，第二家80×40%=32亿元。","difficulty":3,"type":"scenario","source":"extra"},{"id":"19-X-M04","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"关于保险集团与保险公司在偿付能力监管要求上的对比，依据第19号和第1号规则，下列说法正确的是：","options":["保险集团核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%","保险集团风险综合评级须在B类及以上","保险公司核心偿付能力充足率不低于100%","保险集团和保险公司综合偿付能力充足率均不低于100%"],"answer":["A","B","D"],"explanation":"根据第19号规则，保险集团偿付能力达标要求：核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%，风险综合评级在B类及以上。根据第1号规则，保险公司核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%。C错误。","difficulty":3,"type":"cross","source":"extra"},{"id":"19-X-M05","rule_no":19,"rule_title":"保险集团","qtype":"multi","q":"根据第19号规则，关于保险集团实际资本的评估方法，下列说法正确的是：","options":["保险控股型集团采用合并报表法","非保险控股型集团采用减项合并法","混合型集团采用减项合并法","所有保险集团均采用减项合并法"],"answer":["A","B","C"],"explanation":"根据第19号规则，保险控股型集团采用合并报表法评估实际资本；非保险控股型集团和混合型集团采用减项合并法。","difficulty":1,"type":"concept","source":"extra"},{"id":"20-S01","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"制定第20号规则的主要目的是（ ）。","options":["明确劳合社保险（中国）有限公司在偿付能力监管方面的特别规定，有效识别和管理其偿付能力风险","规范劳合社辛迪加在中国境内的市场准入","统一境内外再保险公司的偿付能力计量标准","规定劳合社（中国）的税收优惠政策"],"answer":"A","explanation":"依据第一条，本规则为明确劳合社保险（中国）有限公司在偿付能力监管方面的特别规定，有效识别和管理劳合社（中国）的偿付能力风险而制定。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S02","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"本规则未作规定的，劳合社（中国）的偿付能力监管（ ）。","options":["适用相应的其他保险公司偿付能力监管规则","适用英国劳合社的监管规则","由银保监会另行个案审批","参照国际保险监管规则执行"],"answer":"A","explanation":"依据第二条，劳合社（中国）应当按照本规则评估、计量和报告偿付能力；本规则未作规定的，适用相应的其他保险公司偿付能力监管规则。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S03","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）评估和计量偿付能力应当遵循的原则是（ ）。","options":["穿透原则","审慎原则","合并原则","实质重于形式原则"],"answer":"A","explanation":"依据第三条，劳合社（中国）应当按照穿透原则，分别评估和计量承保部和公司层面可资本化的偿付能力风险，并在此基础上对整体偿付能力进行评估和计量。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S04","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"本规则所称承保部是指（ ）。","options":["劳合社（中国）为在中国开展保险业务的劳合社辛迪加及其管理代理公司设立的对应承保业务部门","劳合社（中国）的再保险业务部门","劳合社总部在中国的分支机构","劳合社（中国）的风险管理部门"],"answer":"A","explanation":"依据第四条，承保部指劳合社（中国）为在中国开展保险业务的劳合社辛迪加及其管理代理公司设立的对应承保业务部门。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S05","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"本规则所称公司层面是指（ ）。","options":["主要承担劳合社（中国）整体运营管理、风险控制等职能的机构，即除承保部外的其他职能部门、组织和人员","劳合社（中国）的母公司","劳合社（中国）所有境内分支机构","劳合社（中国）的董事会和高级管理层"],"answer":"A","explanation":"依据第五条，公司层面指主要承担劳合社（中国）整体运营管理、风险控制等职能的机构，即除承保部外，劳合社（中国）的其他职能部门、组织和人员。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S06","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"留存资产是指劳合社辛迪加作为劳合社（中国）的再保险人或转分保接受人，留存在劳合社（中国）专门用于（ ）的资产。","options":["支付保险赔款和相关理赔费用","缴纳注册资本","支付员工薪酬","对外股权投资"],"answer":"A","explanation":"依据第七条第（一）项，留存资产指留存在劳合社（中国）专门用于支付保险赔款和相关理赔费用的资产，包括留存的应收承保部的分保保费、其他划拨的资产及其投资收益。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S07","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部的（ ）为非认可负债。","options":["分出再保险业务的应付分保账款","保险合同负债","分入再保险业务的应付分保账款","应付赔付款"],"answer":"A","explanation":"依据第九条，承保部的分出再保险业务的应付分保账款为非认可负债；保险合同负债、分入再保险应付分保账款、应付赔付款均为认可负债（第八条）。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S08","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部的最低资本包括（ ）。","options":["保险风险、市场风险和信用风险最低资本，不计算控制风险最低资本","保险风险、市场风险、信用风险和控制风险最低资本","仅保险风险和信用风险最低资本","保险风险、信用风险最低资本和附加资本"],"answer":"A","explanation":"依据第十条，承保部的最低资本包括保险风险最低资本、市场风险最低资本和信用风险最低资本，不计算控制风险最低资本。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S09","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部保险风险最低资本等于（ ）。","options":["非寿险再保险业务保险风险最低资本与非寿险业务保险风险最低资本之和","非寿险再保险业务保险风险最低资本乘以15%","各承保部保险风险最低资本的加权平均值","非寿险业务保险风险最低资本的25%"],"answer":"A","explanation":"依据第十一条，承保部保险风险最低资本为非寿险再保险业务保险风险最低资本和非寿险业务保险风险最低资本之和。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S10","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部再保险业务保费风险最低资本的风险暴露为该业务类型（ ）。","options":["过去12个月再保险分出前的保费","过去12个月再保险分出后的保费","报告期末未到期责任准备金","本季度签单保费"],"answer":"A","explanation":"依据第十二条第（一）项，保费风险最低资本的风险暴露为该业务类型过去12个月再保险分出前的保费；准备金风险的风险暴露为再保险分出前未决赔款准备金。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S11","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部非寿险业务巨灾风险最低资本的计算公式为（ ）。","options":["MC巨灾＝MC保费及准备金×25%","MC巨灾＝MC保费及准备金×15%","MC巨灾＝MC保费×25%＋MC准备金×25%","MC巨灾＝MC保费及准备金×40%"],"answer":"A","explanation":"依据第十三条第（三）项，承保部非寿险业务巨灾风险最低资本不划分业务类型，按MC巨灾＝MC保费及准备金×25%合并计算。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S12","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"承保部的信用风险最低资本应当以（ ）为基础进行评估和计量。","options":["再保险分出前业务","再保险分出后业务","净自留额","公司整体合并业务"],"answer":"A","explanation":"依据第十四条，承保部的信用风险最低资本应当以再保险分出前业务为基础进行评估和计量。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S13","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）公司层面保险风险最低资本的计算公式为（ ）。","options":["各承保部保险风险最低资本之和×15%","各承保部保险风险最低资本之和×25%","各承保部保险风险最低资本之和×60%","公司层面业务保险风险最低资本×15%"],"answer":"A","explanation":"依据第十五条，公司层面保险风险最低资本＝各承保部保险风险最低资本之和×15%。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S14","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"关于劳合社（中国）公司层面控制风险最低资本，正确的规定是（ ）。","options":["公司层面不计算控制风险最低资本","按可资本化风险的10%计算","与承保部合并计算控制风险最低资本","按监管评估结果计算控制风险最低资本"],"answer":"A","explanation":"依据第十六条，劳合社（中国）公司层面不计算控制风险最低资本；承保部同样不计算控制风险最低资本（第十条）。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S15","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）核心偿付能力充足率的计算公式为（ ）。","options":["承保部核心偿付能力充足率平均值×60%＋公司层面核心偿付能力充足率×40%","承保部核心偿付能力充足率平均值×40%＋公司层面核心偿付能力充足率×60%","承保部核心偿付能力充足率平均值×50%＋公司层面核心偿付能力充足率×50%","承保部核心偿付能力充足率平均值×70%＋公司层面核心偿付能力充足率×30%"],"answer":"A","explanation":"依据第二十条，劳合社（中国）核心偿付能力充足率＝承保部核心偿付能力充足率平均值×60%＋公司层面核心偿付能力充足率×40%，综合偿付能力充足率采用相同的加权方式。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S16","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）应在每年（ ）偿付能力季度报告中说明上一年度的偿付能力风险管理能力自评估情况。","options":["第一季度","第二季度","第三季度","第四季度"],"answer":"A","explanation":"依据第二十一条，劳合社（中国）应参照第12号规则每年对偿付能力风险管理能力进行自评估，并在每年第一季度偿付能力季度报告中说明上一年度的自评估情况。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S17","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）开展现金流测试、计算流动性覆盖率时，适用的压力情景是（ ）。","options":["再保险公司的压力情景","财产保险公司的压力情景","人身保险公司的压力情景","银行的压力情景"],"answer":"A","explanation":"依据第二十三条，劳合社（中国）应按第13号规则开展现金流测试，计算整体基本情景和压力情景下的流动性覆盖率，并适用再保险公司的压力情景。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S18","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）各承保部、公司层面以及公司整体的偿付能力应当符合的要求是（ ）。","options":["核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%","核心偿付能力充足率不低于100%，综合偿付能力充足率不低于150%","核心偿付能力充足率不低于75%，综合偿付能力充足率不低于120%","仅要求公司整体达标，各承保部不作要求"],"answer":"A","explanation":"依据第二十四条，各承保部、公司层面以及公司整体的偿付能力均应分别符合核心偿付能力充足率不低于50%、综合偿付能力充足率不低于100%的要求。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S19","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）整体偿付能力充足率不达标的，银保监会采取监管措施的依据是（ ）。","options":["《保险公司偿付能力管理规定》","《中华人民共和国公司法》","《保险集团公司监督管理办法》","《再保险业务管理规定》"],"answer":"A","explanation":"依据第二十五条，劳合社（中国）整体偿付能力充足率不达标的，银保监会根据《保险公司偿付能力管理规定》采取监管措施。","difficulty":2,"type":"concept","source":"core"},{"id":"20-S20","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"本规则的发布情况是（ ）。","options":["2021年12月30日第一次发布，施行日期另行规定","2015年2月13日第一次发布，2021年12月30日修订发布","2015年2月13日第一次发布并施行","2021年12月30日发布并立即施行"],"answer":"A","explanation":"依据第二十八条，本规则于2021年12月30日第一次发布，施行日期另行规定；本规则为偿二代二期新增规则，并非2015年旧规则的修订。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M01","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"承保部的认可资产包括（ ）。","options":["留存资产","应收分保准备金","分入再保险业务的应收分保账款","应收保费"],"answer":["A","B","C","D"],"explanation":"依据第七条，承保部的认可资产包括留存资产、应收分保准备金、分入再保险业务的应收分保账款、应收保费以及银保监会规定的其他认可资产。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M02","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"承保部的认可负债包括（ ）。","options":["保险合同负债","分入再保险业务的应付分保账款","应付赔付款","分出再保险业务的应付分保账款"],"answer":["A","B","C"],"explanation":"依据第八条，承保部认可负债包括保险合同负债、分入再保险业务的应付分保账款、应付赔付款及银保监会规定的其他认可负债；依据第九条，分出再保险业务的应付分保账款为非认可负债。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M03","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"承保部开展非寿险业务计量保险风险最低资本时，适用的特别规定包括（ ）。","options":["保费风险最低资本的风险暴露为过去12个月再保险分出前的保费","不适用综合成本率特征系数","不适用非比例分保净分出比例等特征系数","巨灾风险最低资本按MC巨灾＝MC保费及准备金×25%合并计算，不划分业务类型"],"answer":["A","B","C","D"],"explanation":"依据第十三条，以上均为承保部非寿险业务保险风险最低资本计量的特别规定；此外准备金风险不适用未决赔款准备金回溯偏差率等特征系数。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M04","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"关于劳合社（中国）偿付能力充足率的计算，正确的有（ ）。","options":["承保部核心偿付能力充足率＝承保部核心资本÷承保部最低资本×100%","公司层面综合偿付能力充足率＝公司层面实际资本÷公司层面最低资本×100%","整体偿付能力充足率根据承保部和公司层面偿付能力充足率加权计算","承保部核心偿付能力充足率平均值＝各承保部核心资本之和÷各承保部最低资本之和"],"answer":["A","B","C","D"],"explanation":"依据第十八条、第十九条和第二十条，以上计算方法均正确，整体充足率按承保部平均值60%与公司层面40%加权。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M05","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"劳合社（中国）计量偿付能力时，不计算控制风险最低资本的层面包括（ ）。","options":["承保部","公司层面","两者均不计算","劳合社整体单独计算控制风险最低资本"],"answer":["A","B"],"explanation":"依据第十条和第十六条，承保部和公司层面均不计算控制风险最低资本；D项无规定依据，C项与A、B重复表述不当。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M06","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"关于留存资产，下列说法正确的有（ ）。","options":["留存资产是劳合社辛迪加作为劳合社（中国）的再保险人或转分保接受人留存的资产","专门用于支付保险赔款和相关理赔费用","包括留存的应收承保部的分保保费","包括其他划拨的资产及其投资收益"],"answer":["A","B","C","D"],"explanation":"依据第七条第（一）项，留存资产的定义与范围包括以上全部内容，属于承保部的认可资产。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M07","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"关于劳合社（中国）的监督管理要求，正确的有（ ）。","options":["每年对偿付能力风险管理能力进行自评估","应加强整体和各承保部的流动性风险管理","按第13号规则开展现金流测试并计算流动性覆盖率","适用再保险公司的压力情景"],"answer":["A","B","C","D"],"explanation":"依据第二十一条、第二十二条和第二十三条，以上均为劳合社（中国）的监督管理要求。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M08","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"承保部开展非寿险再保险业务计量保险风险最低资本时，适用的规定包括（ ）。","options":["按照第6号规则（保险风险最低资本（再保险公司））计量","比例再保险业务不适用综合成本率特征系数","准备金风险最低资本的风险暴露为再保险分出前未决赔款准备金","巨灾风险最低资本划分为比例再保险业务和非比例再保险业务分别计算"],"answer":["A","B","C","D"],"explanation":"依据第十二条，以上均为承保部非寿险再保险业务保险风险最低资本计量的规定。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M09","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"关于劳合社（中国）偿付能力评估的达标要求，正确的有（ ）。","options":["各承保部核心偿付能力充足率不低于50%","各承保部综合偿付能力充足率不低于100%","公司层面核心偿付能力充足率不低于50%","公司整体综合偿付能力充足率不低于100%"],"answer":["A","B","C","D"],"explanation":"依据第二十四条，各承保部、公司层面以及公司整体的偿付能力应当分别符合核心偿付能力充足率不低于50%、综合偿付能力充足率不低于100%的要求。","difficulty":2,"type":"concept","source":"core"},{"id":"20-M10","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"同一承保部对应多个劳合社辛迪加时，下列做法正确的有（ ）。","options":["以承保部对应的每一劳合社辛迪加开展的业务为主体进行评估和计量","按照本规则中承保部的相关规定评估偿付能力","将多个辛迪加业务合并后按公司层面规定计量","由银保监会指定其中一个辛迪加为准"],"answer":["A","B"],"explanation":"依据第二十六条，同一承保部对应多个劳合社辛迪加的，应以承保部对应的每一劳合社辛迪加开展的业务为主体，按照本规则中承保部的相关规定对其偿付能力进行评估和计量；C、D无规定依据。","difficulty":2,"type":"concept","source":"core"},{"id":"20-X-S01","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"根据第20号规则，'承保部'是指：","options":["劳合社（中国）为在中国开展保险业务的劳合社辛迪加及其管理代理公司设立的对应承保业务部门","劳合社（中国）的整体运营管理部门","劳合社（中国）的风险控制部门","劳合社（中国）的保险业务部门"],"answer":"A","explanation":"根据第20号规则，承保部是劳合社（中国）为在中国开展保险业务的劳合社辛迪加及其管理代理公司设立的对应承保业务部门。","difficulty":1,"type":"concept","source":"extra"},{"id":"20-X-S02","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"某劳合社（中国）下设承保部A、承保部B及公司层面三个机构，承保部A主要承保非寿险再保险业务，承保部B主要承保非寿险业务，公司层面承担整体运营管理职能。依据第20号规则，评估该劳合社（中国）整体偿付能力的正确做法是：","options":["将承保部A、承保部B和公司层面合并后整体评估","仅以公司层面为主体进行评估","按穿透原则分别评估承保部和公司层面，再加权合成整体指标","仅以承保部A、承保部B加权后整体评估"],"answer":"C","explanation":"根据第20号规则，劳合社（中国）应按穿透原则，分别评估和计量承保部和公司层面可资本化的偿付能力风险，并在此基础上对劳合社（中国）整体偿付能力进行评估。","difficulty":2,"type":"scenario","source":"extra"},{"id":"20-X-S03","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"某承保部某季度非寿险再保险业务的保费及准备金风险最低资本为8亿元，非寿险业务的保费及准备金风险最低资本为12亿元。该承保部巨灾风险最低资本为：","options":["3亿元","4亿元","5亿元","20亿元"],"answer":"C","explanation":"根据第20号规则，巨灾风险最低资本=MC保费及准备金×25%。承保部巨灾风险=（8+12）×25%=5亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"20-X-S04","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）共有3个承保部，保险风险最低资本分别为4亿元、6亿元、10亿元。该公司层面保险风险最低资本为：","options":["3亿元","6亿元","20亿元","24亿元"],"answer":"A","explanation":"根据第20号规则，公司层面保险风险最低资本=各承保部保险风险最低资本之和×15%=（4+6+10）×15%=20×15%=3亿元。","difficulty":2,"type":"calc","source":"extra"},{"id":"20-X-S05","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"根据第20号规则，'留存资产'是指：","options":["劳合社（中国）的全部资金运用资产","劳合社辛迪加作为劳合社（中国）的再保险人或转分保接受人，留存在劳合社（中国）专门用于支付保险赔款和相关理赔费用的资产","劳合社（中国）的固定资产","劳合社（中国）的应收保费"],"answer":"B","explanation":"根据第20号规则，留存资产指劳合社辛迪加作为劳合社（中国）的再保险人或转分保接受人，留存在劳合社（中国）专门用于支付保险赔款和相关理赔费用的资产，包括留存的应收承保部的分保保费、其他划拨的资产及其投资收益。","difficulty":1,"type":"concept","source":"extra"},{"id":"20-X-S06","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"劳合社（中国）有两个承保部A和B：A承保部核心偿付能力充足率100%、综合偿付能力充足率120%；B承保部核心偿付能力充足率120%、综合偿付能力充足率140%；公司层面核心偿付能力充足率150%、综合偿付能力充足率180%。依据第20号规则，劳合社（中国）整体核心偿付能力充足率和综合偿付能力充足率分别为：","options":["126%和150%","110%和130%","120%和142%","116%和146%"],"answer":"A","explanation":"整体核心偿付能力充足率=承保部核心充足率平均值×60%+公司层面核心充足率×40%=（100%+120%）/2×60%+150%×40%=110%×60%+150%×40%=126%；整体综合=（120%+140%）/2×60%+180%×40%=130%×60%+180%×40%=150%。","difficulty":3,"type":"scenario","source":"extra"},{"id":"20-X-S07","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"single","q":"某劳合社（中国）承保部根据第20号规则评估，最低资本包括：保险风险最低资本10亿元、市场风险最低资本5亿元、信用风险最低资本3亿元、控制风险最低资本2亿元。则该承保部正确的最低资本为：","options":["18亿元","20亿元","15亿元","16亿元"],"answer":"A","explanation":"根据第20号规则，承保部最低资本包括保险风险最低资本、市场风险最低资本和信用风险最低资本，不计算控制风险最低资本。所以承保部最低资本=10+5+3=18亿元，不应包括控制风险。","difficulty":3,"type":"calc","source":"extra"},{"id":"20-X-M01","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"根据第20号规则，以下哪些层面不计算控制风险最低资本？","options":["承保部","公司层面","整体层面","以上都不计算"],"answer":["A","B"],"explanation":"根据第20号规则，承保部最低资本包括保险风险、市场风险和信用风险最低资本，不计算控制风险最低资本；公司层面也不计算控制风险最低资本。","difficulty":2,"type":"concept","source":"extra"},{"id":"20-X-M02","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"根据第20号规则，下列属于承保部认可资产的有：","options":["留存资产","应收分保准备金","分入再保险业务的应收分保账款","应收保费"],"answer":["A","B","C","D"],"explanation":"根据第20号规则，留存资产、应收分保准备金、分入再保险业务的应收分保账款、应收保费属于承保部的认可资产。","difficulty":2,"type":"concept","source":"extra"},{"id":"20-X-M03","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"根据第20号规则，承保部某些业务的特征系数不适用，下列说法正确的是：","options":["承保部非寿险业务的保费风险不适用综合成本率特征系数","承保部非寿险业务的保费风险不适用非比例分保净分出比例等特征系数","承保部非寿险再保险业务的非比例再保险业务不适用综合成本率特征系数","承保部非寿险业务的准备金风险适用未决赔款准备金回溯偏差率特征系数"],"answer":["A","B","C"],"explanation":"根据第20号规则，承保部非寿险业务的保费风险不适用综合成本率、非比例分保净分出比例等特征系数；准备金风险不适用未决赔款准备金回溯偏差率等特征系数；承保部非寿险再保险业务的比例再保险业务不适用综合成本率特征系数。D错误。","difficulty":2,"type":"scenario","source":"extra"},{"id":"20-X-M04","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"关于劳合社（中国）与其他保险公司在偿付能力监管上的对比，依据第20号规则与其他相关规则，下列说法正确的是：","options":["劳合社（中国）应按穿透原则分别评估承保部和公司层面","劳合社（中国）核心偿付能力充足率不低于50%，综合偿付能力充足率不低于100%","劳合社（中国）整体偿付能力充足率不达标的，银保监会按第18号规则采取监管措施","劳合社（中国）应按第13号规则开展现金流测试"],"answer":["A","B","D"],"explanation":"根据第20号规则，劳合社（中国）应按穿透原则分别评估；核心和综合偿付能力充足率分别不低于50%和100%；按第13号规则开展现金流测试。C错误，整体偿付能力充足率不达标的，银保监会根据《保险公司偿付能力管理规定》采取监管措施，并非按第18号规则。","difficulty":3,"type":"cross","source":"extra"},{"id":"20-X-M05","rule_no":20,"rule_title":"劳合社保险（中国）有限公司","qtype":"multi","q":"根据第20号规则，同一承保部对应多个劳合社辛迪加的，应如何处理？","options":["以承保部对应的每一劳合社辛迪加开展的业务为主体，按承保部规定评估和计量偿付能力","合并为一个承保部主体评估","任选一个辛迪加评估即可","由银保监会指定评估主体"],"answer":["A"],"explanation":"根据第20号规则，同一承保部对应多个劳合社辛迪加的，应以承保部对应的每一劳合社辛迪加开展的业务为主体，按承保部规定评估和计量偿付能力。","difficulty":1,"type":"concept","source":"extra"}],"rules":[{"no":1,"title":"实际资本","pillar":"第一支柱·定量资本","count":42},{"no":2,"title":"最低资本","pillar":"第一支柱·定量资本","count":42},{"no":3,"title":"寿险合同负债评估","pillar":"第一支柱·定量资本","count":42},{"no":4,"title":"保险风险最低资本（非寿险业务）","pillar":"第一支柱·定量资本","count":42},{"no":5,"title":"保险风险最低资本（寿险业务）","pillar":"第一支柱·定量资本","count":42},{"no":6,"title":"保险风险最低资本（再保险公司）","pillar":"第一支柱·定量资本","count":42},{"no":7,"title":"市场风险和信用风险的穿透计量","pillar":"第一支柱·定量资本","count":42},{"no":8,"title":"市场风险最低资本","pillar":"第一支柱·定量资本","count":42},{"no":9,"title":"信用风险最低资本","pillar":"第一支柱·定量资本","count":42},{"no":10,"title":"压力测试","pillar":"第一支柱·定量资本","count":42},{"no":11,"title":"风险综合评级（分类监管）","pillar":"第二支柱·定性监管","count":42},{"no":12,"title":"偿付能力风险管理要求与评估","pillar":"第二支柱·定性监管","count":42},{"no":13,"title":"流动性风险","pillar":"第二支柱·定性监管","count":42},{"no":14,"title":"资本规划","pillar":"第二支柱·定性监管","count":42},{"no":15,"title":"偿付能力信息公开披露","pillar":"第三支柱·市场约束","count":42},{"no":16,"title":"偿付能力信息交流","pillar":"第三支柱·市场约束","count":42},{"no":17,"title":"保险公司信用评级","pillar":"第二支柱·定性监管","count":42},{"no":18,"title":"偿付能力报告","pillar":"第三支柱·市场约束","count":42},{"no":19,"title":"保险集团","pillar":"特殊主体·保险集团","count":42},{"no":20,"title":"劳合社保险（中国）有限公司","pillar":"特殊主体·劳合社中国","count":42}]};
